const raw = $input.first().json || {};

// ======================================================
// GET INITIAL SEARCH CONTEXT
// ======================================================

let context = {};

try {
  context =
    $('Route Asset Type').item.json || {};
} catch (error) {
  try {
    context =
      $('Prepare Asset Search').item.json || {};
  } catch {
    context = {};
  }
}

// ======================================================
// HELPERS
// ======================================================

function cleanString(value) {
  return String(value ?? '').trim();
}

function toNumber(value, fallback = 0) {
  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

// ======================================================
// YOUTUBE ID
// Only valid 11-character IDs are accepted.
// ======================================================

function extractYouTubeId(value) {

  const text =
    cleanString(value);

  if (!text) {
    return '';
  }

  // youtube.com/watch?v=XXXXXXXXXXX
  let match =
    text.match(
      /(?:youtube\.com\/watch\?(?:[^#\s<>"']*&)?v=)([A-Za-z0-9_-]{11})/i
    );

  if (match?.[1]) {
    return match[1];
  }

  // youtu.be/XXXXXXXXXXX
  match =
    text.match(
      /youtu\.be\/([A-Za-z0-9_-]{11})/i
    );

  if (match?.[1]) {
    return match[1];
  }

  // youtube.com/embed/XXXXXXXXXXX
  match =
    text.match(
      /youtube\.com\/embed\/([A-Za-z0-9_-]{11})/i
    );

  if (match?.[1]) {
    return match[1];
  }

  // youtube.com/shorts/XXXXXXXXXXX
  match =
    text.match(
      /youtube\.com\/shorts\/([A-Za-z0-9_-]{11})/i
    );

  if (match?.[1]) {
    return match[1];
  }

  return '';
}

// ======================================================
// CLEAN URL
// ======================================================

function canonicalizeUrl(value) {

  const rawValue =
    cleanString(value);

  if (!rawValue) {
    return '';
  }

  // YouTube gets strict canonicalization
  const youtubeId =
    extractYouTubeId(rawValue);

  if (youtubeId) {
    return (
      `https://www.youtube.com/watch?v=${youtubeId}`
    );
  }

  // Remove HTML garbage
  let cleaned =
    rawValue
      .replace(/<[^>]*>/g, '')
      .trim();

  // Keep only the actual URL-looking beginning
  const urlMatch =
    cleaned.match(
      /https?:\/\/[^\s<>"']+/i
    );

  if (urlMatch?.[0]) {
    cleaned = urlMatch[0];
  }

  try {

    const parsed =
      new URL(cleaned);

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return cleaned;
  }
}

// ======================================================
// SERPER PARAMETERS
// ======================================================

const actualSearchQuery =
  cleanString(
    raw.searchParameters?.q ||
    raw.search_parameters?.q ||
    context.search_query
  );

const actualMaxResults =
  toNumber(
    raw.searchParameters?.num ||
    raw.search_parameters?.num,
    toNumber(
      context.max_results,
      5
    )
  );

// ======================================================
// RAW VIDEOS
// ======================================================

let rawVideos = [];

if (Array.isArray(raw.videos)) {

  rawVideos =
    raw.videos;

} else if (Array.isArray(raw.results)) {

  rawVideos =
    raw.results;

} else if (Array.isArray(raw.videoResults)) {

  rawVideos =
    raw.videoResults;

} else if (Array.isArray(raw.items)) {

  rawVideos =
    raw.items;
}

// ======================================================
// NORMALIZE
// ======================================================

const normalizedResults =
  rawVideos.map((video, index) => {

    const rawUrl =
      cleanString(
        video.link ||
        video.url
      );

    return {

      asset_type:
        'video',

      title:
        cleanString(
          video.title ||
          video.name
        ),

      // CLEAN CANONICAL URL
      url:
        canonicalizeUrl(
          rawUrl
        ),

      // Keep original only for debugging
      original_url:
        rawUrl,

      youtube_video_id:
        extractYouTubeId(
          rawUrl
        ),

      preview_image_url:
        cleanString(
          video.imageUrl ||
          video.thumbnail ||
          video.thumbnailUrl ||
          video.preview_image_url
        ),

      preview_video_url:
        cleanString(
          video.videoUrl ||
          video.previewVideoUrl ||
          video.preview_video_url
        ),

      source:
        cleanString(
          video.source ||
          video.platform
        ),

      channel:
        cleanString(
          video.channel ||
          video.channelName ||
          video.author
        ),

      duration:
        cleanString(
          video.duration
        ),

      date:
        cleanString(
          video.date ||
          video.publishedDate ||
          video.published_at
        ),

      snippet:
        cleanString(
          video.snippet ||
          video.description
        ),

      original_position:
        toNumber(
          video.position ||
          video.rank ||
          index + 1,
          index + 1
        )
    };
  });

// ======================================================
// REMOVE INVALID / DUPLICATE URLs
// ======================================================

const seenUrls =
  new Set();

const uniqueResults =
  normalizedResults.filter(result => {

    if (!result.url) {
      return false;
    }

    if (
      seenUrls.has(
        result.url
      )
    ) {
      return false;
    }

    seenUrls.add(
      result.url
    );

    return true;
  });

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      game_title:
        cleanString(
          context.game_title
        ),

      asset_type:
        'video',

      search_query:
        actualSearchQuery,

      max_results:
        actualMaxResults,

      aspect_ratio:
        cleanString(
          context.aspect_ratio ||
          '16:9'
        ),

      source_preference:
        cleanString(
          context.source_preference ||
          'official'
        ),

      search_round:
        0,

      max_search_rounds:
        toNumber(
          context.max_search_rounds,
          3
        ),

      search_exhausted:
        false,

      expanded_search:
        false,

      expanded_search_version:
        '',

      previous_candidate_url:
        '',

      previous_failure_reason:
        '',

      actual_serper_query:
        actualSearchQuery,

      context_source:
        'initial_search',

      result_count:
        uniqueResults.length,

      results:
        uniqueResults,

      normalize_video_version:
        'initial-3.1-strict-url-sanitizer'
    }
  }
];

const input = $input.first().json;

const images = Array.isArray(input.images) ? input.images : [];

const maxResults = Number(
  $('Prepare Asset Search').first().json.max_results || 5
);

const results = images
  .slice(0, maxResults)
  .map((image, index) => ({
    asset_type: 'image',
    title: image.title || '',
    image_url: image.imageUrl || '',
    thumbnail_url: image.thumbnailUrl || '',
    source_page_url: image.link || '',
    source: image.source || '',
    domain: image.domain || '',
    width: Number(image.imageWidth || 0),
    height: Number(image.imageHeight || 0),
    original_position: image.position || index + 1
  }));

return [
  {
    json: {
      game_title: $('Prepare Asset Search').first().json.game_title,
      search_query: $('Prepare Asset Search').first().json.search_query,
      source_preference: $('Prepare Asset Search').first().json.source_preference,
      aspect_ratio: $('Prepare Asset Search').first().json.aspect_ratio,
      asset_type: 'image',
      result_count: results.length,
      results
    }
  }
];

const input = $input.first().json || {};

// ======================================================
// INPUT
// ======================================================

const gameTitle =
  String(input.game_title || '').trim();

const searchQuery =
  String(input.search_query || '').trim();

const sourcePreference =
  String(input.source_preference || '')
    .trim()
    .toLowerCase();

const rawResults =
  Array.isArray(input.results) ? input.results :
  Array.isArray(input.video_results) ? input.video_results :
  Array.isArray(input.videos) ? input.videos :
  Array.isArray(input.items) ? input.items :
  [];

// ======================================================
// HELPERS
// ======================================================

function normalize(text) {
  return String(text || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[Â®â„¢Â©]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonicalizeUrl(url) {

  const value =
    String(url || '').trim();

  if (!value) {
    return '';
  }

  try {

    const parsed =
      new URL(value);

    let host =
      parsed.hostname
        .replace(/^www\./, '')
        .replace(/^m\./, '')
        .toLowerCase();

    if (
      host === 'youtube.com' ||
      host === 'youtu.be'
    ) {

      let videoId = '';

      if (host === 'youtu.be') {

        videoId =
          parsed.pathname
            .replace(/^\/+/, '')
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams.get('v') || '';
      }

      if (videoId) {
        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return value;
  }
}

function extractYear(text) {

  const match =
    String(text || '')
      .match(/\b(19\d{2}|20\d{2})\b/);

  return match
    ? Number(match[1])
    : null;
}

function extractAllYears(text) {

  return [
    ...String(text || '')
      .matchAll(/\b(19\d{2}|20\d{2})\b/g)
  ].map(match =>
    Number(match[1])
  );
}

function getPublishYear(result) {

  const fields = [
    result.date,
    result.published_date,
    result.publishedAt,
    result.published_at,
    result.upload_date
  ];

  for (const field of fields) {

    const year =
      extractYear(field);

    if (year) {
      return year;
    }
  }

  return null;
}

function clamp(n, min, max) {
  return Math.max(
    min,
    Math.min(max, n)
  );
}

// ======================================================
// TARGET WORD HELPERS
// ======================================================

const genericWords =
  new Set([
    'official',
    'trailer',
    'teaser',
    'gameplay',
    'game',
    'video',
    'videos',
    'launch',
    'release',
    'reveal',
    'announcement',
    'cinematic',
    'story',
    'extended',
    'full',
    'new',
    'first',
    'look',
    'preview',
    'walkthrough',
    'demo',
    'playthrough',
    'showcase',
    'highlights',
    'clip',
    'clips',
    'hd',
    'uhd',
    '4k',
    '8k',
    '60fps',
    '60',
    'fps',
    'pc',
    'ps4',
    'ps5',
    'xbox',
    'series',
    'switch',
    'steam',
    'e3',
    'gamescom'
  ]);

const insignificantTitleWords =
  new Set([
    'the',
    'a',
    'an',
    'of',
    'and',
    'for',
    'to',
    'in',
    'on',
    'with'
  ]);

function cleanTargetTokens(title) {

  const noYear =
    normalize(title)
      .replace(
        /\b(19\d{2}|20\d{2})\b/g,
        ''
      );

  return noYear
    .split(' ')
    .filter(Boolean)
    .filter(token =>
      !genericWords.has(token)
    );
}

function meaningfulExtraTokens(
  candidateTitle,
  targetBase
) {

  const candidate =
    normalize(candidateTitle);

  const target =
    normalize(targetBase);

  if (
    !candidate.startsWith(target)
  ) {
    return [];
  }

  const remainder =
    candidate
      .slice(target.length)
      .trim();

  if (!remainder) {
    return [];
  }

  return remainder
    .split(' ')
    .filter(Boolean)
    .filter(token =>
      !genericWords.has(token)
    )
    .filter(token =>
      !insignificantTitleWords.has(token)
    )
    .filter(token =>
      !/^(19\d{2}|20\d{2})$/
        .test(token)
    );
}

// ======================================================
// SOURCE CLASSIFICATION
// ======================================================

const officialChannels = [
  'bethesda softworks',
  'id software',

  'playstation',
  'sony interactive entertainment',

  'xbox',
  'microsoft',

  'nintendo',

  'steam',
  'valve',

  'epic games',

  // Added: official storefront/channel
  'gog',

  'ubisoft',

  'electronic arts',
  'ea',
  'ea sports',

  'capcom',
  'sega',

  'square enix',

  'bandai namco',

  'rockstar games',

  'activision',

  'blizzard entertainment',

  'cd projekt red',
  'cd projekt',

  'devolver digital',

  'warner bros games',
  'wb games',

  '2k',
  '2k games',

  'konami',
  'atlus',

  'focus entertainment',

  'thq nordic',

  'deep silver',

  'paradox interactive'
];

const editorialChannels = [
  'ign',
  'gamespot',
  'pc gamer',
  'eurogamer',
  'gamesradar',
  'polygon',
  'rock paper shotgun',
  'vg247',
  'vgc',
  'gematsu',
  'game informer',
  'digital foundry',
  'push square',
  'pure xbox',
  'nintendo life',
  'destructoid',
  'kotaku',
  'engadget',
  'the verge'
];

const eventChannels = [
  'the game awards',
  'summer game fest',
  'gamescom',
  'future games show',
  'pc gaming show'
];

function exactOrStrongChannelMatch(
  normalizedChannel,
  list
) {

  return list.some(entry => {

    const normalizedEntry =
      normalize(entry);

    return (
      normalizedChannel ===
        normalizedEntry ||

      normalizedChannel.startsWith(
        `${normalizedEntry} `
      ) ||

      normalizedChannel.endsWith(
        ` ${normalizedEntry}`
      )
    );
  });
}

function classifySource(result) {

  const channel =
    normalize(
      result.channel ||
      result.channel_name ||
      result.author ||
      ''
    );

  const source =
    normalize(
      result.source ||
      result.platform ||
      ''
    );

  const url =
    String(result.url || '')
      .toLowerCase();

  // --------------------------------------
  // FIRST PARTY / OFFICIAL CHANNEL
  // --------------------------------------

  if (
    channel &&
    exactOrStrongChannelMatch(
      channel,
      officialChannels
    )
  ) {

    return {
      source_class:
        'official_first_party',

      source_trust_score:
        100,

      source_verified_for_ranking:
        true
    };
  }

  // --------------------------------------
  // ESTABLISHED EDITORIAL MEDIA
  // --------------------------------------

  if (
    channel &&
    exactOrStrongChannelMatch(
      channel,
      editorialChannels
    )
  ) {

    return {
      source_class:
        'established_editorial_media',

      source_trust_score:
        80,

      source_verified_for_ranking:
        true
    };
  }

  // --------------------------------------
  // GAMING EVENTS
  // --------------------------------------

  if (
    channel &&
    exactOrStrongChannelMatch(
      channel,
      eventChannels
    )
  ) {

    return {
      source_class:
        'official_gaming_event',

      source_trust_score:
        85,

      source_verified_for_ranking:
        true
    };
  }

  // --------------------------------------
  // OFFICIAL STOREFRONTS
  // --------------------------------------

  if (
    url.includes(
      'store.steampowered.com'
    ) ||

    url.includes(
      'store.playstation.com'
    ) ||

    url.includes(
      'xbox.com/'
    ) ||

    url.includes(
      'nintendo.com/'
    ) ||

    url.includes(
      'epicgames.com/store'
    ) ||

    url.includes(
      'gog.com/'
    )
  ) {

    return {
      source_class:
        'official_store_platform',

      source_trust_score:
        95,

      source_verified_for_ranking:
        true
    };
  }

  // --------------------------------------
  // UNKNOWN YOUTUBE CHANNEL
  // --------------------------------------

  if (
    source === 'youtube' ||
    url.includes('youtube.com/') ||
    url.includes('youtu.be/')
  ) {

    return {
      source_class:
        'youtube_unverified_channel',

      source_trust_score:
        40,

      source_verified_for_ranking:
        false
    };
  }

  // --------------------------------------
  // OTHER
  // --------------------------------------

  return {
    source_class:
      'unverified_source',

    source_trust_score:
      30,

    source_verified_for_ranking:
      false
  };
}

// ======================================================
// CONTENT-TYPE ACQUISITION LADDER
//
// Orthogonal to source-channel trust (classifySource above): this looks
// at WHAT KIND of video a candidate is (extended gameplay vs. a trailer),
// independent of who posted it. A trailer from the official channel
// still outranks extended gameplay from an unverified channel on
// source-authenticity grounds -- this only breaks ties/adds a bonus
// among otherwise-comparable candidates, it never overrides the
// rights/authenticity gate above.
// ======================================================

const CONTENT_TYPE_LADDER = [
  { type: 'extended_gameplay', priority: 100, re: /\bextended gameplay\b|\bfull gameplay\b|\buncut gameplay\b|\braw gameplay\b/i },
  { type: 'gameplay_showcase', priority: 90, re: /\bgameplay showcase\b|\bgameplay reveal\b|\bgameplay overview\b|\bgameplay deep ?dive\b/i },
  { type: 'developer_walkthrough', priority: 85, re: /\bdeveloper walkthrough\b|\bdev walkthrough\b|\bdeveloper commentary\b/i },
  { type: 'platform_gameplay', priority: 75, re: /\b(playstation|xbox|nintendo|switch|pc)\b.*\bgameplay\b|\bgameplay\b.*\b(playstation|xbox|nintendo|switch|pc)\b/i },
  { type: 'gameplay_trailer', priority: 55, re: /\bgameplay trailer\b/i },
  { type: 'editorial_gameplay', priority: 50, re: /\blet'?s play\b|\bfirst look\b.*\bgameplay\b|\bpreview\b.*\bgameplay\b/i },
  { type: 'other_trailer', priority: 20, re: /\btrailer\b|\bteaser\b|\bcinematic\b|\bannouncement\b/i },
];

function classifyContentType(title, description) {
  const t = `${title || ''} ${description || ''}`;
  for (const rule of CONTENT_TYPE_LADDER) {
    if (rule.re.test(t)) return { content_type_class: rule.type, content_type_priority: rule.priority };
  }
  return { content_type_class: 'unclassified', content_type_priority: 40 };
}

function parseDurationToSeconds(text) {
  const trimmed = String(text || '').trim();
  if (!trimmed) return null;
  const parts = trimmed.split(':').map(Number);
  if (!parts.length || parts.some(p => !Number.isFinite(p))) return null;
  return parts.reduce((acc, p) => acc * 60 + p, 0);
}

// ======================================================
// TARGET IDENTITY
// ======================================================

const targetYear =
  extractYear(gameTitle);

const targetBase =
  gameTitle
    .replace(
      /\((19\d{2}|20\d{2})\)/g,
      ''
    )
    .replace(
      /\b(19\d{2}|20\d{2})\b/g,
      ''
    )
    .trim();

const targetNormalized =
  normalize(targetBase);

const targetTokens =
  cleanTargetTokens(gameTitle);

// ======================================================
// PREVIOUS FAILED CANDIDATE
// ======================================================

const previousCandidateUrl =
  canonicalizeUrl(
    input.previous_candidate_url ||
    ''
  );

// ======================================================
// RANK
// ======================================================

const ranked =
  rawResults.map(
    (result, index) => {

      const title =
        String(
          result.title ||
          result.name ||
          ''
        ).trim();

      const description =
        String(
          result.description ||
          result.snippet ||
          ''
        ).trim();

      const channel =
        String(
          result.channel ||
          result.channel_name ||
          result.author ||
          ''
        ).trim();

      const source =
        String(
          result.source ||
          result.platform ||
          ''
        ).trim();

      const candidateUrl =
        canonicalizeUrl(
          result.url ||
          result.link ||
          ''
        );

      const candidateText =
        normalize([
          title,
          description,
          channel,
          source
        ].join(' '));

      const candidateTitleNormalized =
        normalize(title);

      const publishYear =
        getPublishYear(result);

      const titleYears =
        extractAllYears(title);

      const sourceInfo =
        classifySource({
          ...result,
          url: candidateUrl
        });

      let score = 0;

      const reasons = [];

      const rejectionReasons = [];

      // ==================================================
      // 0. PREVIOUSLY FAILED CANDIDATE
      // ==================================================

      const isPreviousFailedCandidate =
        Boolean(
          previousCandidateUrl &&
          candidateUrl &&
          candidateUrl ===
            previousCandidateUrl
        );

      if (isPreviousFailedCandidate) {

        score -= 1000;

        reasons.push(
          'previous_candidate_already_failed'
        );

        rejectionReasons.push(
          'previous_failed_candidate'
        );
      }

      // ==================================================
      // 1. CORE GAME TITLE MATCHING
      // ==================================================

      let matchedTokens = 0;

      for (
        const token of targetTokens
      ) {

        if (
          candidateText.includes(token)
        ) {
          matchedTokens++;
        }
      }

      const coverage =
        targetTokens.length > 0
          ? matchedTokens /
            targetTokens.length
          : 0;

      if (
        targetNormalized &&
        candidateTitleNormalized
          .includes(targetNormalized)
      ) {

        score += 40;

        reasons.push(
          'target_title_phrase_found'
        );
      }

      score +=
        coverage * 30;

      if (coverage >= 0.8) {

        reasons.push(
          'strong_title_token_match'
        );
      }

      if (
        targetTokens.length >= 2 &&
        coverage < 0.6
      ) {

        rejectionReasons.push(
          'weak_game_title_match'
        );
      }

      if (
        targetTokens.length === 1 &&
        matchedTokens === 0
      ) {

        rejectionReasons.push(
          'game_title_not_found'
        );
      }

      // ==================================================
      // 2. RELEASE YEAR
      // ==================================================

      if (targetYear) {

        if (
          candidateText.includes(
            String(targetYear)
          )
        ) {

          score += 35;

          reasons.push(
            'target_year_explicitly_found'
          );
        }

        if (publishYear) {

          const diff =
            Math.abs(
              publishYear -
              targetYear
            );

          if (diff <= 1) {

            score += 30;

            reasons.push(
              'publication_year_strong_match'
            );
          }

          else if (diff <= 2) {

            score += 22;

            reasons.push(
              'publication_year_close_match'
            );
          }

          else if (diff <= 4) {

            score += 5;

            reasons.push(
              'publication_year_possible_match'
            );
          }

          else {

            score -= 25;

            reasons.push(
              'publication_year_far_from_target'
            );
          }
        }

        const conflictingYears =
          titleYears.filter(
            year =>
              year !== targetYear
          );

        if (
          conflictingYears.length > 0 &&
          !candidateTitleNormalized
            .includes(
              String(targetYear)
            )
        ) {

          rejectionReasons.push(
            `conflicting_title_year:${conflictingYears.join(',')}`
          );
        }
      }

      // ==================================================
      // 3. FRANCHISE / SEQUEL COLLISION
      // ==================================================

      const extraTokens =
        meaningfulExtraTokens(
          title,
          targetBase
        );

      const candidateExplicitTargetYear =
        targetYear &&
        candidateText.includes(
          String(targetYear)
        );

      const publishYearClose =
        targetYear &&
        publishYear &&
        Math.abs(
          publishYear -
          targetYear
        ) <= 2;

      if (
        extraTokens.length > 0 &&
        targetTokens.length <= 2 &&
        !candidateExplicitTargetYear &&
        !publishYearClose
      ) {

        score -= 35;

        reasons.push(
          `possible_franchise_variant:${extraTokens
            .slice(0, 4)
            .join('_')}`
        );

        rejectionReasons.push(
          'possible_wrong_sequel_or_subtitle'
        );
      }

      // ==================================================
      // 4. RELEASE PERIOD CONFLICT
      // ==================================================

      if (
        targetYear &&
        publishYear &&
        Math.abs(
          publishYear -
          targetYear
        ) >= 5 &&
        !candidateExplicitTargetYear
      ) {

        rejectionReasons.push(
          `release_period_conflict:${publishYear}`
        );
      }

      // ==================================================
      // 5. PREVIOUS RELEVANCE SCORE
      // ==================================================

      const previousScore =
        Number(
          result.relevance_score ||
          0
        );

      if (
        Number.isFinite(
          previousScore
        )
      ) {

        score +=
          clamp(
            previousScore,
            0,
            100
          ) * 0.15;
      }

      // ==================================================
      // 6. SOURCE AUTHENTICITY
      // ==================================================

      if (
        sourceInfo.source_class ===
        'official_first_party'
      ) {

        score += 45;

        reasons.push(
          'verified_official_channel'
        );
      }

      else if (
        sourceInfo.source_class ===
        'official_store_platform'
      ) {

        score += 40;

        reasons.push(
          'verified_official_platform'
        );
      }

      else if (
        sourceInfo.source_class ===
        'official_gaming_event'
      ) {

        score += 25;

        reasons.push(
          'trusted_gaming_event'
        );
      }

      else if (
        sourceInfo.source_class ===
        'established_editorial_media'
      ) {

        score += 20;

        reasons.push(
          'trusted_editorial_source'
        );
      }

      else {

        score -= 10;

        reasons.push(
          'unverified_source'
        );
      }

      // ==================================================
      // 7. SOURCE PREFERENCE
      // ==================================================

      if (
        sourcePreference ===
        'official'
      ) {

        if (
          sourceInfo.source_class ===
            'official_first_party' ||

          sourceInfo.source_class ===
            'official_store_platform'
        ) {

          score += 20;

          reasons.push(
            'official_source_preference_bonus'
          );
        }
      }

      // ==================================================
      // 8. "OFFICIAL" CLAIM FROM UNKNOWN CHANNEL
      // ==================================================

      const titleClaimsOfficial =
        candidateTitleNormalized
          .includes('official');

      if (
        titleClaimsOfficial &&
        !sourceInfo
          .source_verified_for_ranking
      ) {

        score -= 10;

        reasons.push(
          'official_label_from_unverified_channel'
        );
      }

      // ==================================================
      // 9. CONTENT-TYPE ACQUISITION LADDER (additive bonus only)
      // ==================================================

      const contentTypeInfo =
        classifyContentType(title, description);

      // Scaled down substantially relative to source-authenticity scoring
      // (max +45 there) so this can only influence ordering among
      // otherwise-comparable candidates, never outrank a verified official
      // source over an unverified one.
      score +=
        (contentTypeInfo.content_type_priority - 40) * 0.3;

      if (contentTypeInfo.content_type_priority >= 75) {
        reasons.push('preferred_gameplay_acquisition_type:' + contentTypeInfo.content_type_class);
      }

      const candidateDurationSeconds =
        parseDurationToSeconds(
          result.duration
        );

      if (
        candidateDurationSeconds &&
        candidateDurationSeconds >= 180
      ) {

        score += 8;

        reasons.push(
          'extended_duration_bonus'
        );
      }

      // ==================================================
      // FINAL DECISION
      // ==================================================

      const rejected =
        rejectionReasons.length > 0;

      let gameMatchStatus;

      if (rejected) {

        gameMatchStatus =
          'rejected_version_mismatch';

      }

      else if (score >= 90) {

        gameMatchStatus =
          'strong_match';

      }

      else if (score >= 55) {

        gameMatchStatus =
          'probable_match';

      }

      else {

        gameMatchStatus =
          'weak_match';
      }

      const eligible =
        !rejected &&
        gameMatchStatus !==
          'weak_match';

      return {
        ...result,

        url:
          candidateUrl,

        original_rank:
          index + 1,

        game_match_score:
          Math.round(
            score * 100
          ) / 100,

        game_match_status:
          gameMatchStatus,

        game_match_eligible:
          eligible,

        game_match_reasons:
          reasons,

        game_match_rejection_reasons:
          rejectionReasons,

        detected_publish_year:
          publishYear,

        target_game_title:
          gameTitle,

        target_game_year:
