function aspectRatioScore(width, height) {
  if (!width || !height) return 0;

  const ratio = width / height;

  let targetRatio = 16 / 9;

  if (targetAspect === '9:16') {
    targetRatio = 9 / 16;
  }

  const difference = Math.abs(ratio - targetRatio);

  if (difference < 0.02) return 25;
  if (difference < 0.05) return 20;
  if (difference < 0.10) return 10;

  return 0;
}

const ranked = results.map((item) => {
  let score = 0;

  const title = String(item.title || '').toLowerCase();
  const domain = String(item.domain || '').toLowerCase();
  const source = String(item.source || '').toLowerCase();

  const width = Number(item.width || 0);
  const height = Number(item.height || 0);

  // Game relevance
  if (gameTitle && title.includes(gameTitle)) {
    score += 40;
  }

  // Official source
  if (officialDomains.some(d => domain.includes(d))) {
    score += 35;
  }

  // Trusted gaming/editorial source
  if (trustedDomains.some(d => domain.includes(d))) {
