// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function toNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function canonicalizeUrl(value) {
  const raw = clean(value);

  if (!raw) {
    return '';
  }

  // YouTube
  const yt = raw.match(
    /(?:youtube\.com\/watch\?(?:[^#\s]*&)?v=|youtu\.be\/)([A-Za-z0-9_-]{6,})/i
  );

  if (yt?.[1]) {
    return `https://www.youtube.com/watch?v=${yt[1]}`;
  }

  // Dailymotion
  const dm = raw.match(
    /https?:\/\/(?:www\.)?dailymotion\.com\/video\/([A-Za-z0-9]+)/i
  );

  if (dm?.[1]) {
    return `https://www.dailymotion.com/video/${dm[1]}`;
  }

  // Generic URL
  const http = raw.match(/https?:\/\/[^\s<>"']+/i);

  if (!http?.[0]) {
    return '';
  }

  // Serper video results may use a valid Google redirect URL. Keep the
  // syntactically valid HTTP URL here; the downloader resolves redirects.
  return http[0].replace(/#.*$/,'');
}

function uniqueCanonicalUrls(values) {
  if (!Array.isArray(values)) {
    return [];
  }

  return [
    ...new Set(
      values
        .map(canonicalizeUrl)
        .filter(Boolean)
    )
  ];
}

