        source_package:
          null,

        ready_for_editorial_download:
          false,

        quality_status:
          'not_checked',

        quality_accepted:
          false,

        quality_rejection_reason:
          '',

        detected_width:
          0,

        detected_height:
          0,

        detected_bitrate:
          0,

        detected_codec:
          '',

        detected_fps:
          '',

        detected_duration:
          0,

        min_required_bitrate:
          0,

        retry_available:
          canExpandSearch,

        retry_reason:
          noCandidateReason,

        rights_gate_version:
          'video-3.7-graceful-empty-candidate'
      }
    }
  ];
}

// ======================================================
// RISK SIGNALS
// ======================================================

const riskText = [
  candidateTitle,
  clean(best.snippet),
  clean(best.description),
  clean(input.search_query)
]
  .join(' ')
  .toLowerCase();

const highRiskPatterns = [
  /\bleak(?:ed|s|ing)?\b/i,
  /\bnda\b/i,
  /\bstolen\b/i,
  /\bpirat(?:e|ed|acy)\b/i,
  /\bunreleased\b/i,
  /\bdeveloper build\b/i,
  /\bdev build\b/i,
  /\bpre-release build\b/i,
  /\bprivate build\b/i,
  /\bconfidential\b/i
];

const hasHighRiskSignal =
  highRiskPatterns.some(
    pattern => pattern.test(riskText)
  );

// ======================================================
// SOURCE CLASSIFICATION
// ======================================================

const sourceClassLower =
  preliminarySourceClass.toLowerCase();

const channelLower =
  candidateChannel.toLowerCase();

const officialPublisherPatterns = [
  'bethesda',
  'id software',
  'playstation',
  'sony',
  'xbox',
  'microsoft',
  'nintendo',
  'electronic arts',
  'ea',
  'ubisoft',
  'capcom',
  'sega',
  'square enix',
  'bandai namco',
  'rockstar',
  'activision',
  'blizzard',
  'cd projekt',
  'cdpr',
  'epic games',
  'gog'
];

const editorialMediaPatterns = [
  'ign',
  'gamespot',
  'digital foundry',
  'pc gamer',
  'eurogamer',
  'gamesradar',
  'polygon',
  'rock paper shotgun',
  'vg247',
  'vgc',
  'gematsu',
  'game informer'
];

const eventPatterns = [
  'the game awards',
  'summer game fest',
  'gamescom',
  'future games show',
  'pc gaming show'
];

function matchesAny(value, list) {
  return list.some(
    item => value.includes(item)
  );
}

const looksOfficial =
  sourceClassLower.includes('official_first_party') ||
  sourceClassLower.includes('official_platform') ||
  sourceClassLower.includes('first_party') ||
  sourceClassLower.includes('official_publisher') ||
  matchesAny(
    channelLower,
    officialPublisherPatterns
  );

const looksEditorialMedia =
  sourceClassLower.includes('trusted_editorial') ||
  sourceClassLower.includes('established_media') ||
  sourceClassLower.includes('established_editorial_media') ||
  sourceClassLower.includes('editorial_media') ||
  matchesAny(
    channelLower,
    editorialMediaPatterns
  );

const looksOfficialEvent =
  sourceClassLower.includes('official_event') ||
  sourceClassLower.includes('gaming_event') ||
  matchesAny(
    channelLower,
    eventPatterns
  );

const looksUnverifiedYouTube =
  sourceClassLower.includes('youtube_unverified') ||
  (
    candidateSource.toLowerCase() === 'youtube' &&
    !looksOfficial &&
    !looksEditorialMedia &&
    !looksOfficialEvent
  );

// ======================================================
// EDITORIAL RULES
// ======================================================

const editorialRules = {
  short_excerpt_only: true,
  whole_trailer_reupload: false,
  commentary_or_analysis_required: true,
  original_audio_preferred: false,
  mute_or_replace_music_preferred: true,
  attribution_recommended: true,
  crop_zoom_cut_allowed_as_editing: true,
  source_url_must_be_preserved: true,
  avoid_logos_when_practical: true
};

// ======================================================
// DEFAULT RIGHTS STATE
// ======================================================

let candidateSourceClass =
  preliminarySourceClass ||
  'unknown_source';

let rightsStatus =
  'manual_review_required';

let rightsDecision =
  'manual_review';

let riskLevel =
  'medium';

let safeForAutoUse =
  false;

let editorialUseAllowed =
  false;

let editorialPipelineAllowed =
  false;

let canDownload =
  false;

let requiresPolicyCheck =
  false;

let requiresHumanReview =
  true;

let recommendedAction =
  'review_source_manually';

let decisionReason =
  'The source could not be classified with sufficient confidence for automated editorial use.';

let policyCheckReason = '';

let authenticityScore =
  preliminaryTrustScore;

let editorialCandidateScore =
  preliminaryTrustScore;

// ======================================================
// DECISION 1 â€” HIGH RISK
// ======================================================

if (hasHighRiskSignal) {

  candidateSourceClass =
    preliminarySourceClass ||
    'high_risk_source';

  rightsStatus =
    'blocked_high_risk_source';

  rightsDecision =
    'block';

  riskLevel =
    'high';

  safeForAutoUse =
    false;

  editorialUseAllowed =
    false;

  editorialPipelineAllowed =
    false;

  canDownload =
    false;

  requiresPolicyCheck =
    false;

  requiresHumanReview =
    false;

  recommendedAction =
    'do_not_use_source';

  decisionReason =
    'The candidate contains strong leak, NDA, stolen, pirated, or unreleased-material indicators.';

  authenticityScore =
    Math.min(
      preliminaryTrustScore || 20,
      20
    );

  editorialCandidateScore =
    authenticityScore;
}

// ======================================================
// DECISION 2 â€” OFFICIAL
// ======================================================

else if (looksOfficial) {

  candidateSourceClass =
    'official_first_party';

  rightsStatus =
    'editorial_transformative_use';

  rightsDecision =
    'editorial_use';

  riskLevel =
    'medium';

  safeForAutoUse =
    false;

  editorialUseAllowed =
    true;

  editorialPipelineAllowed =
    true;

  canDownload =
    true;

  requiresPolicyCheck =
    false;

  requiresHumanReview =
    false;

  recommendedAction =
    'download_and_prepare_editorial_excerpt';

  decisionReason =
    'The source is an official publisher, developer, or official platform distribution source and is suitable for limited editorial use under the workflow editorial rules.';

  authenticityScore =
    Math.max(
      preliminaryTrustScore,
      100
    );

  editorialCandidateScore =
    100;
}

// ======================================================
// DECISION 3 â€” TRUSTED EDITORIAL MEDIA
// ======================================================

else if (looksEditorialMedia) {

  candidateSourceClass =
    'established_editorial_media';

  rightsStatus =
    'editorial_transformative_use';

  rightsDecision =
    'editorial_use';

  riskLevel =
    'medium';

  safeForAutoUse =
    false;

  editorialUseAllowed =
    true;

  editorialPipelineAllowed =
    true;

  canDownload =
    true;

  requiresPolicyCheck =
    false;

  requiresHumanReview =
    false;

  recommendedAction =
    'download_and_prepare_editorial_excerpt';

  decisionReason =
    'The source is an established gaming or technology editorial outlet and may be considered for limited transformative editorial excerpts under the workflow rules.';

  authenticityScore =
    Math.max(
      preliminaryTrustScore,
      80
    );

  editorialCandidateScore =
    Math.max(
      authenticityScore,
      80
    );
}

// ======================================================
// DECISION 4 â€” OFFICIAL GAMING EVENT
// ======================================================

else if (looksOfficialEvent) {

  candidateSourceClass =
    'official_gaming_event';

  rightsStatus =
    'editorial_transformative_use';

  rightsDecision =
    'editorial_use';

  riskLevel =
    'medium';

  safeForAutoUse =
    false;

  editorialUseAllowed =
    true;

  editorialPipelineAllowed =
    true;

  canDownload =
    true;

  requiresPolicyCheck =
    false;

  requiresHumanReview =
    false;

  recommendedAction =
    'download_and_prepare_editorial_excerpt';

  decisionReason =
    'The candidate comes from a recognized gaming event source and is eligible for limited editorial excerpt processing under the workflow rules.';

  authenticityScore =
    Math.max(
      preliminaryTrustScore,
      80
    );

  editorialCandidateScore =
    Math.max(
      authenticityScore,
      80
    );
}

// ======================================================
// DECISION 5 â€” UNVERIFIED YOUTUBE
// ======================================================

else if (looksUnverifiedYouTube) {

  candidateSourceClass =
    'youtube_unverified_channel';

  rightsStatus =
    'policy_check_required';

  rightsDecision =
    'pending_policy_check';

  riskLevel =
    'medium';

  safeForAutoUse =
    false;

  editorialUseAllowed =
    false;

  editorialPipelineAllowed =
    false;

  canDownload =
    false;

  requiresPolicyCheck =
    true;

  requiresHumanReview =
    false;

  recommendedAction =
    'check_usage_policy';

  decisionReason =
    'The source is not verified as an official publisher/platform or established trusted media source, so the workflow should check applicable usage policy before automated use.';

  policyCheckReason =
    'The video comes from an unverified third-party source.';

  authenticityScore =
    preliminaryTrustScore > 0
      ? preliminaryTrustScore
      : 40;

  editorialCandidateScore =
    authenticityScore;
}

// ======================================================
// POLICY SEARCH QUERY
// ======================================================

const policyEntity =
  candidateChannel ||
  candidateSource ||
  gameTitle;

const policySearchQuery =
  `${gameTitle} ${policyEntity} official usage policy ` +
  `video policy fan content policy media policy content usage terms`;

// ======================================================
// COLLECTION / RETRY STATE
// ======================================================

const sourcePackages =
  Array.isArray(input.source_packages)
    ? input.source_packages
    : [];

const sourcePackageCount =
  sourcePackages.length;

const desiredSourceCount =
  toNumber(
    input.desired_source_count,
    3
  );

const usedSourceUrls =
  uniqueCanonicalUrls(
    input.used_source_urls
  );

const failedCandidateUrls =
  uniqueCanonicalUrls(
    input.failed_candidate_urls
  );

const failedCandidateHistory =
  Array.isArray(input.failed_candidate_history)
    ? input.failed_candidate_history
    : [];

const excludedCandidateUrls =
  uniqueCanonicalUrls([
    ...(
      Array.isArray(input.excluded_candidate_urls)
        ? input.excluded_candidate_urls
        : []
    ),
    ...failedCandidateUrls,
    ...usedSourceUrls
  ]);

const collectionTotalFootageSeconds =
  toNumber(
    input.collection_total_footage_seconds,
    0
  );

const isCollectionContinuation =
  sourcePackageCount > 0 ||
  input.is_collection_continuation === true;

// ======================================================
// NEW ACTIVE CANDIDATE OBJECT
// ======================================================

const currentCandidate = {
  title:
    candidateTitle,

  url:
    candidateUrl,

  channel:
    candidateChannel,

  source:
    candidateSource,

  source_class:
    candidateSourceClass,

  source_authenticity_score:
    authenticityScore,

  rights_status:
    rightsStatus,

  rights_decision:
    rightsDecision,

  risk_level:
    riskLevel,

  can_download:
    canDownload,

  editorial_use_allowed:
    editorialUseAllowed,

  editorial_pipeline_allowed:
    editorialPipelineAllowed
};

// ======================================================
// OUTPUT
//
// ...input preserves SEARCH + COLLECTION state.
//
// Every ACTIVE SOURCE field is then overwritten so stale
// candidate information cannot survive.
// ======================================================

return [
  {
    json: {

      ...input,

      // ==================================================
      // CURRENT CANDIDATE â€” SINGLE SOURCE OF TRUTH
      // ==================================================

      game_title:
        gameTitle,

      candidate_title:
        candidateTitle,

      candidate_url:
        candidateUrl,

      candidate_channel:
        candidateChannel,

      candidate_source:
        candidateSource,

      candidate_source_class:
        candidateSourceClass,

      // --------------------------------------------------
      // ACTIVE SOURCE ALIASES
      // These MUST always equal the current candidate.
      // --------------------------------------------------

      source_title:
        candidateTitle,

      source_url:
        candidateUrl,

      source_channel:
        candidateChannel,

      source_platform:
        candidateSource,

      source_class:
        candidateSourceClass,

      // --------------------------------------------------
      // PROCESSING SOURCE
      // --------------------------------------------------

      processing_source_title:
        candidateTitle,

      processing_source_url:
        candidateUrl,

      processing_source_channel:
        candidateChannel,

      processing_source_platform:
        candidateSource,

      processing_source_class:
        candidateSourceClass,

      // --------------------------------------------------
      // CURRENT CANDIDATE OBJECT
      // --------------------------------------------------

      current_candidate:
        currentCandidate,

      // ==================================================
      // RIGHTS
      // ==================================================

      rights_status:
        rightsStatus,

      rights_decision:
        rightsDecision,

      risk_level:
        riskLevel,

      safe_for_auto_use:
        safeForAutoUse,

      editorial_use_allowed:
        editorialUseAllowed,

      editorial_pipeline_allowed:
        editorialPipelineAllowed,

      can_download:
        canDownload,

      requires_policy_check:
        requiresPolicyCheck,

      requires_human_review:
        requiresHumanReview,

      recommended_action:
        recommendedAction,

      decision_reason:
        decisionReason,

      policy_check_reason:
        policyCheckReason,

      policy_search_query:
        policySearchQuery,

      editorial_rules:
        editorialRules,

      source_authenticity_score:
        authenticityScore,

      preliminary_source_trust_score:
        preliminaryTrustScore,

      preliminary_source_verified:
        best.preliminary_source_verified === true,

      relevance_score:
        relevanceScore,

      editorial_candidate_score:
        editorialCandidateScore,

      // ==================================================
      // MEDIA METADATA
      // ==================================================

      preview_image_url:
        previewImageUrl,

      preview_video_url:
        previewVideoUrl,

      duration:
        duration,

      source_date:
        sourceDate,

      youtube_video_id:
        youtubeVideoId,

      // ==================================================
      // COLLECTION STATE â€” PRESERVED
      // ==================================================

      source_packages:
        sourcePackages,

      source_package_count:
        sourcePackageCount,

      desired_source_count:
        desiredSourceCount,

      used_source_urls:
        usedSourceUrls,

      collection_total_footage_seconds:
        collectionTotalFootageSeconds,

      needs_more_sources:
        sourcePackageCount < desiredSourceCount,

      collection_ready:
        sourcePackageCount >= desiredSourceCount,

      is_collection_continuation:
