parameters.jsCode:
// Rank Usage Policy Results
// Mode: Run Once for All Items
// VERSION: 1.3-policy-page-safe

const searchData = $input.first().json || {};
const context =
  $('Prepare Resolved Rights Holder').first().json || {};

const organicResults =
  Array.isArray(searchData.organic)
    ? searchData.organic
    : [];

const gameTitle =
  String(context.game_title || '').trim();

const policyTargetName =
  String(context.policy_target_name || '').trim();

const policySearchQuery =
  String(context.policy_search_query || '').trim();

const officialDomain =
  String(context.official_domain || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/.*$/, '');

// =========================================================
// HELPERS
// =========================================================

function getDomain(url) {
  const value =
    String(url || '').trim();

  if (!value) {
    return '';
  }

  try {
    const parsed =
      new URL(value);

    return parsed.hostname
      .toLowerCase()
      .replace(/^www\./, '');

  } catch {

    const match =
      value.match(
        /^https?:\/\/([^\/?#]+)/i
      );

    if (!match) {
      return '';
    }

    return match[1]
      .toLowerCase()
      .replace(/^www\./, '');
  }
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(
      /[^\p{L}\p{N}\s.-]/gu,
      ' '
    )
    .replace(/\s+/g, ' ')
    .trim();
}

function domainMatches(
  domain,
  baseDomain
) {
  if (
    !domain ||
    !baseDomain
  ) {
    return false;
  }

  return (
    domain === baseDomain ||
    domain.endsWith(
      `.${baseDomain}`
    )
  );
}

// =========================================================
// POLICY-PAGE DOMAIN RULES
//
// IMPORTANT:
// These rules apply ONLY to POLICY EVIDENCE PAGES.
//
// They DO NOT mean YouTube/Reddit/etc. are globally unsafe
// as video or editorial asset sources.
// =========================================================

const blockedPolicyDomains = [
  'reddit.com',
  'youtube.com',
  'youtu.be',
  'facebook.com',
  'instagram.com',
  'threads.net',
  'x.com',
  'twitter.com',
  'tiktok.com',
  'discord.com',
  'discord.gg',
  'steamcommunity.com',
  'fandom.com',
  'quora.com',
  'pinterest.com'
];

function isBlockedPolicyDomain(domain) {
  return blockedPolicyDomains.some(
    base =>
      domainMatches(
        domain,
        base
      )
  );
}

// =========================================================
// ORGANIZATION MATCHING
// =========================================================

function getOrgTokens(name) {

  const ignoredWords =
    new Set([
      'inc',
      'inc.',
      'llc',
      'ltd',
      'ltd.',
      'limited',
      'corporation',
      'corp',
      'corp.',
      'company',
      'co',
      'co.',
      'studios',
      'studio',
      'software',
      'interactive',
      'entertainment'
    ]);

  return normalizeText(name)
    .split(' ')
    .filter(
      token =>
        token.length >= 3 &&
        !ignoredWords.has(token)
    );
}

function matchesTargetOrganization(
  result,
  targetName
) {

  if (!targetName) {
    return false;
  }

  const title =
    normalizeText(
      result.title
    );

  const snippet =
    normalizeText(
      result.snippet
    );

  const domain =
    normalizeText(
      getDomain(
        result.link
      )
    );

  const combined =
    `${title} ${snippet} ${domain}`;

  const targetNormalized =
    normalizeText(
      targetName
    );

  if (
    targetNormalized &&
    combined.includes(
      targetNormalized
    )
  ) {
    return true;
  }

  const tokens =
    getOrgTokens(
      targetName
    );

  if (
    tokens.length === 0
  ) {
    return false;
  }

  const matches =
    tokens.filter(
      token =>
        combined.includes(
          token
        )
    );

  return (
    matches.length >=
    Math.max(
      1,
      Math.ceil(
        tokens.length * 0.6
      )
    )
  );
}

// =========================================================
// POLICY SIGNALS
// =========================================================

function getPolicyText(result) {
  return normalizeText(
    `${result.title || ''} ` +
    `${result.snippet || ''} ` +
    `${result.link || ''}`
  );
}

function hasDirectPolicySignal(
  result
) {

  const text =
    getPolicyText(
      result
    );

  const signals = [
    'video policy',
    'fan video policy',
    'fan content policy',
    'fan content guidelines',
    'content policy',
    'content usage policy',
    'content usage guidelines',
    'content guidelines',
    'game content guidelines',
    'game content usage rules',
    'gameplay usage policy',
    'gameplay guidelines',
    'video guidelines',
    'usage policy',
    'media usage policy',
    'media policy',
    'creator policy',
    'creator guidelines',
    'streaming policy',
    'streaming guidelines'
  ];

  return signals.some(
    signal =>
      text.includes(
        signal
      )
  );
}

function titleHasPolicySignal(
  title
) {

  const text =
    normalizeText(
      title
    );

  const signals = [
    'video policy',
    'fan video',
    'fan content',
    'content policy',
    'content usage',
    'content guidelines',
    'game content guidelines',
    'game content usage',
    'gameplay guidelines',
    'video guidelines',
    'usage policy',
    'media policy',
    'creator policy',
    'creator guidelines',
    'streaming policy',
    'streaming guidelines'
  ];

  return signals.some(
    signal =>
      text.includes(
        signal
      )
  );
}

function mentionsMonetization(
  result
) {

  const text =
    getPolicyText(
      result
    );

  const signals = [
    'monetization',
    'monetisation',
    'monetize',
    'monetise',
    'commercial use',
    'commercially',
    'advertising revenue',
    'ad revenue'
  ];

  return signals.some(
    signal =>
      text.includes(
        signal
      )
  );
}

function mentionsGameplay(
  result
) {

  const text =
    getPolicyText(
      result
    );

  const signals = [
    'gameplay',
    'game footage',
    'game content',
    'screenshots',
    'screen shots',
    'let s play',
    'lets play',
    'streaming',
    'video content'
  ];

  return signals.some(
    signal =>
      text.includes(
        signal
      )
  );
}

function isEula(
  result
) {

  const text =
    getPolicyText(
      result
    );

  return (
    text.includes('eula') ||
    text.includes(
      'end user license agreement'
    )
  );
}

function hasLegalPolicySignal(
  result
) {

  const text =
    getPolicyText(
      result
    );

  const signals = [
    'terms of service',
    'terms of use',
    'legal',
    'license agreement',
    'intellectual property',
    'copyright policy'
  ];

  return signals.some(
    signal =>
      text.includes(
        signal
      )
  );
}

function isCommunityStandards(
  result
) {

  const text =
    normalizeText(
      result.title
    );

  return (
    text.includes(
      'community standards'
    ) ||
    text.includes(
      'community guidelines'
    )
  );
}

// =========================================================
// RANK RESULTS
// =========================================================

const ranked =
  organicResults.map(
    (result, index) => {

      const title =
        String(
          result.title || ''
        );

      const url =
        String(
          result.link || ''
        );

      const snippet =
        String(
          result.snippet || ''
        );

      const domain =
        getDomain(
          url
        );

      const originalPosition =
        Number(
          result.position ||
          index + 1
        );

      const targetOrgMatch =
        matchesTargetOrganization(
          result,
          policyTargetName
        );

      const targetDomainMatch =
        Boolean(
          officialDomain &&
          domainMatches(
            domain,
            officialDomain
          )
        );

      const blockedPolicyDomain =
        isBlockedPolicyDomain(
          domain
        );

      const directPolicySignal =
        hasDirectPolicySignal(
          result
        );

      const policySignalInTitle =
        titleHasPolicySignal(
          title
        );

      const monetizationSignal =
        mentionsMonetization(
          result
        );

      const gameplaySignal =
        mentionsGameplay(
          result
        );

      const eula =
        isEula(
          result
        );

      const legalPolicySignal =
        hasLegalPolicySignal(
          result
        );

      const communityStandards =
        isCommunityStandards(
          result
        );

      let score = 0;

      const rankingReasons = [];

      // ===================================================
      // POLICY-PAGE FILTER
      // ===================================================

      if (
        blockedPolicyDomain
      ) {

        score -= 1000;

        rankingReasons.push(
          'social/video/community domain is not accepted as a primary policy evidence page'
        );
      }

      // ===================================================
      // OFFICIAL DOMAIN
      // ===================================================

      if (
        targetDomainMatch
      ) {

        score += 220;

        rankingReasons.push(
          'matches resolved official domain'
        );
      }

      // ===================================================
      // ORGANIZATION MATCH
      // ===================================================

      if (
        targetOrgMatch
      ) {

        score += 80;

        rankingReasons.push(
          'matches resolved policy target organization'
        );

      } else {

        score -= 80;

        rankingReasons.push(
          'does not match resolved policy target organization'
        );
      }

      // ===================================================
      // DIRECT POLICY LANGUAGE
      // ===================================================

      if (
        directPolicySignal
      ) {

        score += 110;

        rankingReasons.push(
          'contains direct video/fan-content usage-policy language'
        );
      }

      if (
        policySignalInTitle
      ) {

        score += 60;

        rankingReasons.push(
          'policy language appears directly in title'
        );
      }

      if (
        monetizationSignal
      ) {

        score += 25;

        rankingReasons.push(
          'mentions monetization or commercial use'
        );
      }

      if (
        gameplaySignal
      ) {

        score += 15;

        rankingReasons.push(
          'mentions gameplay, streaming, or game footage'
        );
      }

      // ===================================================
      // LEGAL FALLBACK EVIDENCE
      // ===================================================

      if (
        eula
      ) {

        score +=
          targetDomainMatch
            ? 35
            : -10;

        rankingReasons.push(
          targetDomainMatch
            ? 'official EULA can provide secondary usage evidence'
            : 'non-official EULA reference is weaker evidence'
        );
      }

      if (
        legalPolicySignal
      ) {

        score +=
          targetDomainMatch
            ? 25
            : 5;

        rankingReasons.push(
          'contains legal or terms-related policy language'
        );
      }

      if (
        communityStandards &&
        !directPolicySignal
      ) {

        score -= 60;

        rankingReasons.push(
          'community standards alone are not direct footage-reuse permission'
        );
      }

      // ===================================================
      // SEARCH POSITION BONUS
      // ===================================================

      score +=
        Math.max(
          0,
          10 -
          originalPosition
        );

      // ===================================================
      // POLICY PAGE ELIGIBILITY
      // ===================================================

      const officialDirectPolicyCandidate =
        !blockedPolicyDomain &&
        targetDomainMatch &&
        (
          directPolicySignal ||
          policySignalInTitle ||
          eula ||
          legalPolicySignal
        );

      const externalDirectPolicyCandidate =
        !blockedPolicyDomain &&
        !targetDomainMatch &&
        targetOrgMatch &&
        directPolicySignal &&
        policySignalInTitle;

      const eligiblePolicyPage =
        officialDirectPolicyCandidate ||
        externalDirectPolicyCandidate;

      return {

        title,
        url,
        domain,
        snippet,

        original_position:
          originalPosition,

        target_domain_match:
          targetDomainMatch,

        target_org_match:
          targetOrgMatch,

        blocked_policy_domain:
          blockedPolicyDomain,

        has_direct_policy_signal:
          directPolicySignal,

        title_has_policy_signal:
          policySignalInTitle,

        mentions_monetization:
          monetizationSignal,

        mentions_gameplay:
          gameplaySignal,

        is_eula:
          eula,

        has_legal_policy_signal:
          legalPolicySignal,

        eligible_policy_page:
          eligiblePolicyPage,

        policy_score:
          score,

        ranking_reasons:
          rankingReasons
      };
    }
  );

// =========================================================
// SORT
// =========================================================

ranked.sort(
  (a, b) => {

    if (
      b.policy_score !==
      a.policy_score
    ) {

      return (
        b.policy_score -
        a.policy_score
      );
    }

    return (
      a.original_position -
      b.original_position
    );
  }
);

// =========================================================
// SELECT POLICY PAGE
// =========================================================

const eligiblePolicyCandidates =
  ranked.filter(
    result =>
      result
        .eligible_policy_page ===
      true
  );

const officialPolicyCandidates =
  eligiblePolicyCandidates.filter(
    result =>
      result
        .target_domain_match ===
      true
  );

const selectedPolicyCandidate =
  officialPolicyCandidates[0] ||
  eligiblePolicyCandidates[0] ||
  null;

const bestOverallResult =
  ranked[0] || null;

const policyCandidateFound =
  Boolean(
    selectedPolicyCandidate
  );

const policyUrl =
  selectedPolicyCandidate
    ? String(
        selectedPolicyCandidate
          .url || ''
      ).trim()
    : '';

const policyCandidateType =
  selectedPolicyCandidate
    ? (
        selectedPolicyCandidate
          .target_domain_match
          ? 'official_domain_policy'
          : 'external_direct_policy_reference'
      )
    : 'none';

// =========================================================
// FINAL OUTPUT
// =========================================================

return [
  {
    json: {

      game_title:
        gameTitle,

      policy_target_name:
        policyTargetName,

      official_domain:
        officialDomain,

      policy_search_query:
        policySearchQuery,

      candidate_count:
        ranked.length,

      eligible_policy_candidate_count:
        eligiblePolicyCandidates
          .length,

      results:
        ranked,

      // IMPORTANT:
      // This is now ONLY a valid policy candidate.
      // It never falls back to Reddit/YouTube/random result.
      best_result:
        selectedPolicyCandidate,

      // Diagnostic only.
      best_overall_result:
        bestOverallResult,

      policy_url:
        policyUrl,

      policy_candidate_found:
        policyCandidateFound,

      direct_policy_candidate_found:
        policyCandidateFound,

      policy_candidate_type:
        policyCandidateType,

      should_scrape_policy:
        policyCandidateFound &&
        Boolean(
          policyUrl
        ),

      needs_refined_search:
        !policyCandidateFound,

      ranking_rule_version:
        '1.3-policy-page-safe'
    }
  }
];

// Extract Policy Content
// Version: 2.0-serper-scrape-safe

const input = $input.first().json || {};


// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function firstNonEmptyString(values) {
  for (const value of values) {
    if (
      typeof value === 'string' &&
      value.trim()
    ) {
      return value.trim();
    }
  }

  return '';
}

function stripHtml(html) {
  return String(html ?? '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}


// ======================================================
// SERPER SCRAPE RESPONSE
//
// Serper normally returns:
// - text
// - markdown
//
// But we also support a few alternate wrappers so
// this node does not break if response formatting changes.
// ======================================================

const markdown =
  firstNonEmptyString([
    input.markdown,
    input.data?.markdown,
    input.body?.markdown,
    input.response?.markdown
  ]);

const text =
  firstNonEmptyString([
    input.text,
    input.data?.text,
    input.body?.text,
    input.response?.text
  ]);


// ======================================================
// OPTIONAL RAW BODY / HTML FALLBACK
// ======================================================

let rawBody =
  firstNonEmptyString([
    typeof input.data === 'string'
      ? input.data
      : '',

    typeof input.body === 'string'
      ? input.body
      : '',

    typeof input.response === 'string'
      ? input.response
      : ''
  ]);

let extractedFromRawBody = '';

if (rawBody) {

  const looksLikeHtml =
    /<html|<body|<div|<main|<article|<!doctype/i
      .test(rawBody);

  extractedFromRawBody =
    looksLikeHtml
      ? stripHtml(rawBody)
      : rawBody;
}


// ======================================================
// SELECT BEST CONTENT
//
// Prefer Markdown because it normally preserves useful
// headings and policy structure.
// ======================================================

let policyText =
  markdown ||
  text ||
  extractedFromRawBody;


// ======================================================
// FALLBACK SNIPPET
//
// IMPORTANT:
// Do NOT crash the whole workflow just because one
// website cannot be fully scraped.
// ======================================================

const fallbackSnippet =
  firstNonEmptyString([
    input.policy_search_snippet,
    input.snippet,
    input.results?.[0]?.snippet
  ]);

let contentSource = '';

if (markdown) {
  contentSource = 'serper_markdown';
}

else if (text) {
  contentSource = 'serper_text';
}

else if (extractedFromRawBody) {
  contentSource = 'raw_response';
}

else if (fallbackSnippet) {

  policyText =
    fallbackSnippet;

  contentSource =
    'search_snippet_fallback';
}

else {

  policyText = '';

  contentSource =
    'no_content';
}


// ======================================================
// SIZE LIMIT
// ======================================================

const MAX_POLICY_TEXT_LENGTH =
  30000;

const originalLength =
  policyText.length;

const textTruncated =
  originalLength >
  MAX_POLICY_TEXT_LENGTH;

if (textTruncated) {

  policyText =
    policyText.slice(
      0,
      MAX_POLICY_TEXT_LENGTH
    );
}


// ======================================================
// STATUS
// ======================================================

const fullPolicyContentFound =
  (
    contentSource === 'serper_markdown' ||
    contentSource === 'serper_text' ||
    contentSource === 'raw_response'
  ) &&
  policyText.length >= 200;

const policyContentAvailable =
  policyText.length > 0;

let policyContentStatus;

if (fullPolicyContentFound) {

  policyContentStatus =
    'full_content_ready';

}

else if (
  contentSource ===
  'search_snippet_fallback'
) {

  policyContentStatus =
    'snippet_only';

}

else {

  policyContentStatus =
    'content_unavailable';
}


// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      ...input,

      policy_text:
        policyText,

      policy_content_source:
        contentSource,

      policy_content_status:
        policyContentStatus,

      policy_content_available:
        policyContentAvailable,

      full_policy_content_found:
        fullPolicyContentFound,

      raw_response_length:
        rawBody.length,

      extracted_text_length:
        policyText.length,

      original_extracted_length:
        originalLength,

      text_truncated:
        textTruncated,

      extraction_version:
        '2.0-serper-scrape-safe'
    }
  }
];

const input = $input.first().json || {};

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function toNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function toBoolean(value, fallback = false) {
  if (value === true || value === false) {
    return value;
  }

  if (value === 'true') {
    return true;
  }

  if (value === 'false') {
    return false;
  }

  return fallback;
}

// ======================================================
// URL SANITIZER
// ======================================================

function canonicalizeUrl(value) {
  const raw = clean(value);

  if (!raw) {
    return '';
  }

  // YouTube
  const yt = raw.match(
    /(?:youtube\.com\/watch\?(?:[^#\s]*&)?v=|youtu\.be\/)([A-Za-z0-9_-]{6,})/i
  );

  if (yt?.[1]) {
    return `https://www.youtube.com/watch?v=${yt[1]}`;
  }

  // Dailymotion
  const dm = raw.match(
    /https?:\/\/(?:www\.)?dailymotion\.com\/video\/([A-Za-z0-9]+)/i
  );

  if (dm?.[1]) {
    return `https://www.dailymotion.com/video/${dm[1]}`;
  }

  // Generic URL
  const match = raw.match(/https?:\/\/[^\s<>"']+/i);

  if (!match?.[0]) {
    return '';
  }

  try {
    const parsed = new URL(match[0]);
    parsed.hash = '';

    return parsed.toString();
  } catch {
    return match[0];
  }
}

// ======================================================
// CANDIDATE OBJECTS
// CURRENT ITEM ONLY
// ======================================================

const objects = [
  input.current_candidate,
  input.candidate,
  input.selected_candidate,
  input.best_result,
  input.next_source_candidate,
  input.next_candidate,
  input.source_candidate,
  input.policy_result,
  input.policy_analysis,
  input.original_candidate,
  input
].filter(
  obj =>
    obj &&
    typeof obj === 'object' &&
    !Array.isArray(obj)
);

function pick(...keys) {
  for (const obj of objects) {
    for (const key of keys) {
      const value = obj?.[key];

      if (
        value !== undefined &&
        value !== null &&
        clean(value) !== ''
      ) {
        return value;
      }
    }
  }

  return '';
}

// ======================================================
// GAME
// ======================================================

const gameTitle = clean(
  pick(
    'game_title',
    'target_game_title'
  )
);

// ======================================================
// CURRENT CANDIDATE
// ======================================================

const candidateTitle = clean(
  pick(
    'candidate_title',
    'title',
    'source_title'
  )
);

const candidateUrl = canonicalizeUrl(
  pick(
    'candidate_url',
    'url',
    'link',
    'source_url'
  )
);

const candidateChannel = clean(
  pick(
    'candidate_channel',
    'channel',
    'author',
    'source_channel'
  )
);

const candidateSource = clean(
  pick(
    'candidate_source',
    'source',
    'platform',
    'source_platform'
  )
);

const candidateSourceClass = clean(
  pick(
    'candidate_source_class',
    'resolved_source_class',
    'preliminary_source_class',
    'source_class'
  )
);

// ======================================================
// DETECT EXISTING COLLECTED SOURCE STATE
// ======================================================

const hasExistingSourcePackage =
  input.source_package &&
  typeof input.source_package === 'object' &&
  !Array.isArray(input.source_package);

const hasExistingClips =
  Array.isArray(input.clips) &&
  input.clips.length > 0;

const hasExistingSourceId =
  clean(input.source_id) !== '';

const hasCollectedSources =
  Array.isArray(input.source_packages) &&
  input.source_packages.length > 0;

const isCollectionContinuation =
  hasExistingSourcePackage ||
  hasExistingClips ||
  hasExistingSourceId ||
  hasCollectedSources;

// ======================================================
// CURRENT RIGHTS STATE
// ======================================================

let rightsStatus = clean(
  pick('rights_status')
);

let rightsDecision = clean(
  pick('rights_decision')
);

let riskLevel =
  clean(
    pick('risk_level')
  ) || 'medium';

let safeForAutoUse = toBoolean(
  pick('safe_for_auto_use'),
  false
);

let editorialUseAllowed = toBoolean(
  pick('editorial_use_allowed'),
  false
);

let editorialPipelineAllowed = toBoolean(
  pick('editorial_pipeline_allowed'),
  editorialUseAllowed
);

let canDownload = toBoolean(
  pick('can_download'),
  false
);

let requiresPolicyCheck = toBoolean(
  pick('requires_policy_check'),
  false
);

let requiresHumanReview = toBoolean(
  pick('requires_human_review'),
  false
);

let recommendedAction = clean(
  pick('recommended_action')
);

let decisionReason = clean(
  pick('decision_reason')
);

// ======================================================
// POLICY RESULT
// ======================================================

const policyDecision = clean(
  pick(
    'policy_decision',
    'usage_decision',
    'policy_rights_decision',
    'final_policy_decision'
  )
).toLowerCase();

const policyAllowsUse = toBoolean(
  pick(
    'policy_allows_use',
    'usage_allowed',
    'commercial_use_allowed'
  ),
  false
);

const policyAllowsEditorial = toBoolean(
  pick(
    'editorial_use_permitted',
    'editorial_use_allowed_by_policy',
    'transformative_use_allowed'
  ),
  false
);

const policyRequiresReview = toBoolean(
  pick(
    'manual_review_required',
    'policy_requires_human_review'
  ),
  false
);

const policyBlocksUse = toBoolean(
  pick(
    'policy_blocks_use',
    'usage_prohibited'
  ),
  false
);

// ======================================================
// APPLY POLICY RESULT
// ======================================================

if (
  rightsDecision === 'pending_policy_check' ||
  requiresPolicyCheck === true
) {
  // BLOCK
  if (
    policyBlocksUse === true ||
    policyDecision === 'block' ||
    policyDecision === 'blocked' ||
    policyDecision === 'prohibited'
  ) {
    rightsStatus = 'blocked_by_policy';
    rightsDecision = 'block';

    riskLevel = 'high';

    safeForAutoUse = false;
    editorialUseAllowed = false;
    editorialPipelineAllowed = false;
    canDownload = false;

    requiresPolicyCheck = false;
    requiresHumanReview = false;

    recommendedAction =
      'do_not_use_source';

    decisionReason =
      clean(
        pick(
          'policy_reason',
          'policy_analysis_reason',
          'decision_reason'
        )
      ) ||
      'The applicable usage policy does not support automated use of this source.';
  }

  // MANUAL REVIEW
  else if (
    policyRequiresReview === true ||
    policyDecision === 'manual_review' ||
    policyDecision === 'review'
  ) {
    rightsStatus =
      'manual_review_required';

    rightsDecision =
      'manual_review';

    riskLevel =
      'medium';

    safeForAutoUse =
      false;

    editorialUseAllowed =
      false;

    editorialPipelineAllowed =
      false;

    canDownload =
      false;

    requiresPolicyCheck =
      false;

    requiresHumanReview =
      true;

    recommendedAction =
      'manual_review';

    decisionReason =
      clean(
        pick(
          'policy_reason',
          'policy_analysis_reason',
          'decision_reason'
        )
      ) ||
      'The policy result is not sufficiently clear for automatic use.';
  }

  // AUTO USE
  else if (
    policyAllowsUse === true ||
    policyDecision === 'auto_use' ||
    policyDecision === 'allowed'
  ) {
    rightsStatus =
      'policy_allows_use';

    rightsDecision =
      'auto_use';

    riskLevel =
      'low';

    safeForAutoUse =
      true;

    editorialUseAllowed =
      true;

    editorialPipelineAllowed =
      true;

    canDownload =
      true;

    requiresPolicyCheck =
      false;

    requiresHumanReview =
      false;

    recommendedAction =
      'use_source';

    decisionReason =
      clean(
        pick(
          'policy_reason',
          'policy_analysis_reason',
          'decision_reason'
        )
      ) ||
      'The applicable usage policy supports use of the source.';
  }

  // EDITORIAL
  else if (
    policyAllowsEditorial === true ||
    policyDecision === 'editorial_use' ||
    policyDecision === 'editorial'
  ) {
    rightsStatus =
      'editorial_transformative_use';

    rightsDecision =
      'editorial_use';

    riskLevel =
      'medium';

    safeForAutoUse =
      false;

    editorialUseAllowed =
      true;

    editorialPipelineAllowed =
      true;

    canDownload =
      true;

    requiresPolicyCheck =
      false;

    requiresHumanReview =
