    riskLevel =
      'medium';

    safeForAutoUse =
      false;

    editorialUseAllowed =
      false;

    editorialPipelineAllowed =
      false;

    canDownload =
      false;

    requiresPolicyCheck =
      false;

    requiresHumanReview =
      true;

    recommendedAction =
