// ======================================================
// NORMALIZE DIRECT DECISION
// ======================================================

if (rightsDecision === 'editorial_use') {
  rightsStatus =
    rightsStatus ||
    'editorial_transformative_use';

  safeForAutoUse =
    false;

  editorialUseAllowed =
    true;

  editorialPipelineAllowed =
    true;

  canDownload =
    true;

  requiresPolicyCheck =
    false;

  requiresHumanReview =
    false;

  recommendedAction =
    recommendedAction ||
    'download_and_prepare_editorial_excerpt';
