    false;

  editorialUseAllowed =
    false;

  editorialPipelineAllowed =
    false;

  canDownload =
    false;

  requiresPolicyCheck =
    false;

  requiresHumanReview =
    false;
}

// ======================================================
// EDITORIAL RULES
// ======================================================

const editorialRules = {
  short_excerpt_only:
    input.editorial_rules?.short_excerpt_only ?? true,

  whole_trailer_reupload:
    input.editorial_rules?.whole_trailer_reupload ?? false,

  commentary_or_analysis_required:
    input.editorial_rules?.commentary_or_analysis_required ?? true,

  original_audio_preferred:
    input.editorial_rules?.original_audio_preferred ?? false,

  mute_or_replace_music_preferred:
    input.editorial_rules?.mute_or_replace_music_preferred ?? true,

  attribution_recommended:
    input.editorial_rules?.attribution_recommended ?? true,

  crop_zoom_cut_allowed_as_editing:
    input.editorial_rules?.crop_zoom_cut_allowed_as_editing ?? true,

  source_url_must_be_preserved:
    input.editorial_rules?.source_url_must_be_preserved ?? true,

