    input.editorial_rules?.avoid_logos_when_practical ?? true
};

// ======================================================
// SCORES
// ======================================================

const authenticityScore = toNumber(
  pick(
    'source_authenticity_score',
    'preliminary_source_trust_score',
    'resolved_trust_score'
  ),
  0
);

const relevanceScore = toNumber(
  pick('relevance_score'),
  0
);

const editorialCandidateScore = toNumber(
  pick('editorial_candidate_score'),
  authenticityScore
);

// ======================================================
// VALIDATE SOURCE
// ======================================================

const decisionNeedsSource =
  rightsDecision === 'editorial_use' ||
  rightsDecision === 'auto_use';

if (
  decisionNeedsSource &&
  !candidateUrl
) {
  rightsStatus =
    'invalid_missing_source';

  rightsDecision =
    'manual_review';

  riskLevel =
    'high';

  safeForAutoUse =
    false;

  editorialUseAllowed =
    false;

  editorialPipelineAllowed =
    false;

  canDownload =
    false;

  requiresPolicyCheck =
    false;

  requiresHumanReview =
    true;

  recommendedAction =
    'manual_review';

  decisionReason =
    'A usable rights decision existed, but the candidate source URL was missing from the current workflow item.';
}

// ======================================================
// CURRENT CANDIDATE PACKAGE
// ======================================================

const currentCandidate = {
  title:
    candidateTitle,

  url:
    candidateUrl,

  channel:
    candidateChannel,

  source:
    candidateSource,

  source_class:
    candidateSourceClass,

  source_authenticity_score:
    authenticityScore,

  rights_status:
    rightsStatus,

  rights_decision:
    rightsDecision,

  risk_level:
    riskLevel,

  can_download:
    canDownload,

  editorial_use_allowed:
    editorialUseAllowed,

  editorial_pipeline_allowed:
    editorialPipelineAllowed
};

// ======================================================
// OUTPUT
// ======================================================

const output = {
  // Preserve ALL collection/search/retry state
  ...input,

  game_title:
    gameTitle,

  // ==================================================
  // CURRENT CANDIDATE - SAFE FIELDS
  // ==================================================

  candidate_title:
    candidateTitle,

  candidate_url:
    candidateUrl,

  candidate_channel:
    candidateChannel,

  candidate_source:
    candidateSource,

  candidate_source_class:
    candidateSourceClass,

  current_candidate:
    currentCandidate,

  // Dedicated aliases for the NEXT source being processed
  processing_source_title:
    candidateTitle,

  processing_source_url:
    candidateUrl,

  processing_source_channel:
    candidateChannel,

  processing_source_platform:
    candidateSource,

  processing_source_class:
    candidateSourceClass,

  // ==================================================
  // RIGHTS
  // ==================================================

  rights_status:
    rightsStatus,

  rights_decision:
    rightsDecision,

  risk_level:
    riskLevel,

  safe_for_auto_use:
    safeForAutoUse,

  editorial_use_allowed:
    editorialUseAllowed,

  editorial_pipeline_allowed:
    editorialPipelineAllowed,

  can_download:
    canDownload,

  requires_policy_check:
    requiresPolicyCheck,

  requires_human_review:
    requiresHumanReview,

  recommended_action:
    recommendedAction,

  decision_reason:
    decisionReason,

  editorial_rules:
    editorialRules,

  source_authenticity_score:
    authenticityScore,

  relevance_score:
    relevanceScore,

  editorial_candidate_score:
    editorialCandidateScore,

  is_collection_continuation:
    isCollectionContinuation,

  rights_gate_version:
    '3.2-collection-candidate-safe'
};

// ======================================================
// IMPORTANT:
//
// Only create legacy source_* aliases when there is NO
// already-extracted source state.
//
// During collection continuation, source_* must continue
// describing the previously extracted source package.
// ======================================================

if (!isCollectionContinuation) {
  output.source_title =
    candidateTitle;

  output.source_url =
    candidateUrl;

  output.source_channel =
    candidateChannel;

  output.source_platform =
    candidateSource;

  output.source_class =
    candidateSourceClass;
}

// ======================================================
// FINAL
// ======================================================

return [
  {
    json: output
  }
];

