parameters.jsCode:
// ======================================================
// Rank Safer Alternatives
// VERSION: 1.1-request-type-locked-context-safe
// Mode: Run Once for All Items
// ======================================================

const searchData =
  $input.first()?.json || {};

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeAssetType(value) {

  const type =
    normalize(value);

  if (
    type === 'video' ||
    type === 'image'
  ) {
    return type;
  }

  return '';
}

function getDomain(url) {

  const value =
    clean(url);

  if (!value) {
    return '';
  }

  try {

    return new URL(value)
      .hostname
      .toLowerCase()
      .replace(/^www\./, '');

  } catch {

    const match =
      value.match(
        /^https?:\/\/([^\/?#]+)/i
      );

    if (!match) {
      return '';
    }

    return String(match[1])
      .toLowerCase()
      .replace(/^www\./, '');
  }
}

function canonicalizeUrl(url) {

  const value =
    clean(url);

  if (!value) {
    return '';
  }

  try {

    const parsed =
      new URL(value);

    const host =
      parsed.hostname
        .replace(/^www\./i, '')
        .replace(/^m\./i, '')
        .toLowerCase();

    if (
      host === 'youtube.com' ||
      host === 'youtu.be'
    ) {

      let videoId = '';

      if (host === 'youtu.be') {

        videoId =
          parsed.pathname
            .replace(/^\/+/, '')
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams.get('v') ||
          '';

        if (!videoId) {

          const shortsMatch =
            parsed.pathname.match(
              /^\/shorts\/([^/?#]+)/i
            );

          if (shortsMatch?.[1]) {
            videoId =
              shortsMatch[1];
          }
        }

        if (!videoId) {

          const embedMatch =
            parsed.pathname.match(
              /^\/embed\/([^/?#]+)/i
            );

          if (embedMatch?.[1]) {
            videoId =
              embedMatch[1];
          }
        }
      }

      if (videoId) {

        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return value;
  }
}

function includesAny(text, terms) {

  const normalized =
    normalize(text);

  return terms.some(term =>
    normalized.includes(
      normalize(term)
    )
  );
}

function num(value, fallback = 0) {

  const n =
    Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

// ======================================================
// RESTORE THE CORRECT SAFER-SEARCH CONTEXT
//
// IMPORTANT:
// Do NOT blindly use .first() because this branch may
// execute multiple times during one workflow execution.
// ======================================================

let context = {};

const executedQuery =
  clean(
    searchData?.searchParameters?.q
  );

try {

  context =
    $('Prepare Safer Alternative Search')
      .item
      .json || {};

} catch {

  let contexts = [];

  try {

    contexts =
      $('Prepare Safer Alternative Search')
        .all()
        .map(item =>
          item?.json || {}
        );

  } catch {

    contexts = [];
  }

  if (contexts.length > 0) {

    const queryMatch =
      contexts
        .filter(item => {

          const q =
            clean(
              item.alternative_search_query
            );

          return (
            executedQuery &&
            q === executedQuery
          );
        });

    if (queryMatch.length > 0) {

      context =
        queryMatch[
          queryMatch.length - 1
        ];

    } else {

      // Prefer newest context, never the oldest one.
      context =
        contexts[
          contexts.length - 1
        ];
    }
  }
}

// ======================================================
// BASIC CONTEXT
// ======================================================

const gameTitle =
  clean(
    context.game_title
  );

const policyTargetName =
  clean(
    context.policy_target_name
  );

const requestedAssetType =
  normalizeAssetType(
    context.requested_asset_type
  ) ||
  normalizeAssetType(
    context.asset_type
  ) ||
  'video';

const rejectedCandidateUrl =
  canonicalizeUrl(
    context.rejected_candidate_url
  );

const policyUrl =
  clean(
    context.policy_url
  );

const officialPolicyDomain =
  getDomain(
    policyUrl
  );

// ======================================================
// SEARCH RESULTS
// ======================================================

const organic =
  Array.isArray(
    searchData.organic
  )
    ? searchData.organic
    : [];

// ======================================================
// TARGET ORGANIZATION TOKENS
// ======================================================

const ignoredOrgWords =
  new Set([
    'softworks',
    'studios',
    'studio',
    'games',
    'game',
    'company',
    'corporation',
    'corp',
    'inc',
    'llc',
    'ltd',
    'entertainment',
    'interactive'
  ]);

const targetTokens =
  normalize(
    policyTargetName
  )
    .replace(
      /[^a-z0-9 ]/g,
      ' '
    )
    .split(/\s+/)
    .filter(token =>
      token.length >= 3 &&
      !ignoredOrgWords.has(token)
    );

function matchesTargetOrganization(text) {

  const value =
    normalize(text);

  if (
    !value ||
    targetTokens.length === 0
  ) {
    return false;
  }

  return targetTokens.some(
    token =>
      value.includes(token)
  );
}

// ======================================================
// DOMAIN GROUPS
// ======================================================

const socialDomains = [
  'reddit.com',
  'facebook.com',
  'instagram.com',
  'tiktok.com',
  'x.com',
  'twitter.com'
];

const editorialDomains = [
  'ign.com',
  'gamespot.com',
  'polygon.com',
  'kotaku.com',
  'extremetech.com',
  'eurogamer.net',
  'pcgamer.com',
  'gamesradar.com'
];

function domainMatchesList(
  domain,
  list
) {

  return list.some(d =>
    domain === d ||
    domain.endsWith(
      '.' + d
    )
  );
}

// ======================================================
// RANK EACH RESULT
// ======================================================

const ranked =
  organic.map(
    (item, index) => {

      const title =
        clean(
          item.title
        );

      const url =
        canonicalizeUrl(
          item.link
        );

      const snippet =
        clean(
          item.snippet
        );

      const domain =
        getDomain(
          url
        );

      const combined =
        `${title} ${url} ${snippet} ${domain}`;

      let score = 0;

      const reasons = [];

      // =================================================
      // SOURCE IDENTITY
      // =================================================

      const officialDomainMatch =
        Boolean(
          officialPolicyDomain &&
          (
            domain ===
              officialPolicyDomain ||
            domain.endsWith(
              '.' +
              officialPolicyDomain
            )
          )
        );

      const targetOrgMatch =
        matchesTargetOrganization(
          combined
        );

      const targetDomainMatch =
        matchesTargetOrganization(
          domain
        );

      // =================================================
      // LICENSE / PERMISSION SIGNALS
      // =================================================

      const directLicenseSignal =
        includesAny(
          combined,
          [
            'limited license',
            'licensed under',
            'licensed to',
            'license terms',
            'usage license',
            'usage rights',
            'content license',
            'media license',
            'permission to use',
            'permission for use',
            'permissions',
            'terms of use',
            'reuse allowed',
            'may be used',
            'authorized use'
          ]
        );

      // =================================================
      // GENERIC PRESS/MEDIA SIGNALS
      // =================================================

      const pressMediaSignal =
        includesAny(
          combined,
          [
            'press kit',
            'press assets',
            'media kit',
            'media assets',
            'download assets',
            'downloadable assets',
            'asset library',
            'official assets',
            'press center',
            'press centre'
          ]
        );

      // =================================================
      // VIDEO SIGNALS
      // =================================================

      const videoAssetSignal =
        includesAny(
          combined,
          [
            'gameplay footage',
            'video assets',
            'video asset',
            'video download',
            'download video',
            'download footage',
            'b-roll',
            'b roll',
            'press footage',
            'game footage',
            'official gameplay',
            'official trailer',
            'gameplay trailer',
            'gameplay video',
            'video footage',
            'trailer download',
            'mp4'
          ]
        ) ||
        /\.(mp4|webm|mov|m4v)(?:$|\?)/i
          .test(url);

      // =================================================
      // IMAGE SIGNALS
      // =================================================

      const imageAssetSignal =
        includesAny(
          combined,
          [
            'image assets',
            'image asset',
            'screenshots',
            'screen shots',
            'artwork',
            'wallpaper',
            'key art',
            'promotional images',
            'press images',
            'download images',
            'download screenshots'
          ]
        ) ||
        /\.(png|jpg|jpeg|webp)(?:$|\?)/i
          .test(url);

      // =================================================
      // DOWNLOAD SIGNAL
      // =================================================

      const downloadSignal =
        includesAny(
          combined,
          [
            'download',
            'downloads',
            'downloadable'
          ]
        );

      // =================================================
      // SOURCE CLASS
      // =================================================

      const isSocialSource =
        domainMatchesList(
          domain,
          socialDomains
        );

      const isEditorial =
        domainMatchesList(
          domain,
          editorialDomains
        );

      const isYouTube =
        domain ===
          'youtube.com' ||
        domain.endsWith(
          '.youtube.com'
        ) ||
        domain ===
          'youtu.be';

      // =================================================
      // MEDIA TYPE CLASSIFICATION
      // =================================================

      let candidateMediaType =
        'unknown';

      if (
        videoAssetSignal &&
        imageAssetSignal
      ) {

        candidateMediaType =
          'mixed';

      } else if (
        videoAssetSignal ||
        isYouTube
      ) {

        candidateMediaType =
          'video';

      } else if (
        imageAssetSignal
      ) {

        candidateMediaType =
          'image';
      }

      const mediaTypeCompatible =
        requestedAssetType ===
          'video'
          ? (
              candidateMediaType ===
                'video' ||
              candidateMediaType ===
                'mixed'
            )
          : (
              candidateMediaType ===
                'image' ||
              candidateMediaType ===
                'mixed'
            );

      const mediaTypeMismatch =
        candidateMediaType !==
          'unknown' &&
        !mediaTypeCompatible;

      // =================================================
      // SCORE: OFFICIAL SOURCE
      // =================================================

      if (officialDomainMatch) {

        score += 140;

        reasons.push(
          'matches official policy domain'
        );
      }

      if (targetDomainMatch) {

        score += 100;

        reasons.push(
          'domain matches resolved rights target'
        );

      } else if (targetOrgMatch) {

        score += 50;

        reasons.push(
          'page content matches resolved rights target'
        );
      }

      // =================================================
      // SCORE: LICENSE
      // =================================================

      if (directLicenseSignal) {

        score += 120;

        reasons.push(
          'contains direct license or permission language'
        );
      }

      if (pressMediaSignal) {

        score += 25;

        reasons.push(
          'appears to be a press or media asset page'
        );
      }

      if (downloadSignal) {

        score += 20;

        reasons.push(
          'mentions downloadable content'
        );
      }

      // =================================================
      // SCORE: REQUESTED MEDIA TYPE
      // =================================================

      if (
        requestedAssetType ===
          'video'
      ) {

        if (videoAssetSignal) {

          score += 100;

          reasons.push(
            'contains video or gameplay footage signals'
          );
        }

        if (
          imageAssetSignal &&
          !videoAssetSignal
        ) {

          score -= 220;

          reasons.push(
            'image-only asset conflicts with requested video type'
          );
        }

      } else {

        if (imageAssetSignal) {

          score += 100;

          reasons.push(
            'contains image or screenshot asset signals'
          );
        }

        if (
          videoAssetSignal &&
          !imageAssetSignal
        ) {

          score -= 220;

          reasons.push(
            'video-only asset conflicts with requested image type'
          );
        }
      }

      // =================================================
      // SOURCE PENALTIES
      // =================================================

      if (isSocialSource) {

        score -= 160;

        reasons.push(
          'social or community source'
        );
      }

      if (isYouTube) {

        // YouTube can still be a VIDEO candidate,
        // but the video page itself does not prove
        // reuse permission.
        score -=
          requestedAssetType ===
            'video'
            ? 45
            : 180;

        reasons.push(
          'YouTube page alone does not establish reusable asset rights'
        );
      }

      if (isEditorial) {

        score -= 90;

        reasons.push(
          'third-party editorial source'
        );
      }

      // =================================================
      // SAME REJECTED CANDIDATE
      // =================================================

      const sameRejectedCandidate =
        Boolean(
          rejectedCandidateUrl &&
          url &&
          url ===
            rejectedCandidateUrl
        );

      if (sameRejectedCandidate) {

        score -= 300;

        reasons.push(
          'same asset that was already rejected'
        );
      }

      // =================================================
      // HARD MEDIA TYPE MISMATCH
      // =================================================

      if (mediaTypeMismatch) {

        score -= 300;

        reasons.push(
          `candidate media type ${candidateMediaType} does not match requested ${requestedAssetType}`
        );
      }

      // =================================================
      // GENERIC PAGE
      // =================================================

      const genericGamePage =
        !directLicenseSignal &&
        !pressMediaSignal &&
        !videoAssetSignal &&
        !imageAssetSignal;

      if (
        genericGamePage &&
        !officialDomainMatch
      ) {

        score -= 35;

        reasons.push(
          'generic page without clear reusable asset or media signal'
        );
      }

      // =================================================
      // GOOGLE POSITION BONUS
      // =================================================

      const originalPosition =
        num(
          item.position,
          index + 1
        );

      score +=
        Math.max(
          0,
          12 -
          originalPosition
        );

      // =================================================
      // CANDIDATE KIND
      // =================================================

      let candidateKind =
        'unknown';

      if (
        directLicenseSignal &&
        mediaTypeCompatible
      ) {

        candidateKind =
          requestedAssetType ===
            'video'
            ? 'licensed_video_asset_page'
            : 'licensed_image_asset_page';

      } else if (
        pressMediaSignal &&
        candidateMediaType ===
          'mixed'
      ) {

        candidateKind =
          'mixed_press_asset_page';

      } else if (
        pressMediaSignal &&
        candidateMediaType ===
          'video'
      ) {

        candidateKind =
          'video_press_asset_page';

      } else if (
        pressMediaSignal &&
        candidateMediaType ===
          'image'
      ) {

        candidateKind =
          'image_press_asset_page';

      } else if (
        videoAssetSignal
      ) {

        candidateKind =
          'video_asset_page';

      } else if (
        imageAssetSignal
      ) {

        candidateKind =
          'image_asset_page';

      } else if (isYouTube) {

        candidateKind =
          'youtube_video';

      } else if (
        isSocialSource
      ) {

        candidateKind =
          'social_or_community';

      } else if (
        officialDomainMatch
      ) {

        candidateKind =
          'official_generic_page';
      }

      // =================================================
      // SOURCE CONFIDENCE
      // =================================================

      const sourceIdentityStrong =
        officialDomainMatch ||
        targetDomainMatch ||
        directLicenseSignal;

      // =================================================
      // PROMISING FOR AUTO FOLLOW-UP?
      //
      // MEDIA TYPE MATCH IS MANDATORY.
      // =================================================

      const promising =
        Boolean(
          !sameRejectedCandidate &&
          !mediaTypeMismatch &&
          mediaTypeCompatible &&
          !isSocialSource &&
          sourceIdentityStrong &&
          (
            directLicenseSignal ||
            pressMediaSignal ||
            (
              requestedAssetType ===
                'video'
                ? videoAssetSignal
                : imageAssetSignal
            )
          )
        );

      return {

        title,
        url,
        domain,
        snippet,

        requested_asset_type:
          requestedAssetType,

        candidate_media_type:
          candidateMediaType,

        media_type_compatible:
          mediaTypeCompatible,

        media_type_mismatch:
          mediaTypeMismatch,

        original_position:
          originalPosition,

        official_domain_match:
          officialDomainMatch,

        target_org_match:
          targetOrgMatch,

        target_domain_match:
          targetDomainMatch,

        direct_license_signal:
          directLicenseSignal,

        press_media_signal:
          pressMediaSignal,

        video_asset_signal:
          videoAssetSignal,

        image_asset_signal:
          imageAssetSignal,

        download_signal:
          downloadSignal,

        social_source:
          isSocialSource,

        editorial_source:
          isEditorial,

        youtube_source:
          isYouTube,

        same_rejected_candidate:
          sameRejectedCandidate,

        candidate_kind:
          candidateKind,

        promising_candidate:
          promising,

        safer_asset_score:
          score,

        ranking_reasons:
          reasons
      };
    }
  );

// ======================================================
// SORT
// ======================================================

ranked.sort(
  (a, b) => {

    if (
      b.safer_asset_score !==
      a.safer_asset_score
    ) {

      return (
        b.safer_asset_score -
        a.safer_asset_score
      );
    }

    return (
      a.original_position -
      b.original_position
    );
  }
);

// ======================================================
// SELECT ONLY MEDIA-COMPATIBLE PROMISING RESULT
// ======================================================

const promisingCandidates =
  ranked.filter(
    result =>
      result.promising_candidate ===
      true
  );

const bestPromisingCandidate =
  promisingCandidates[0] ||
  null;

const compatibleCandidates =
  ranked.filter(
    result =>
      result.media_type_compatible ===
      true &&
      result.same_rejected_candidate !==
        true
  );

const bestCompatibleOverall =
  compatibleCandidates[0] ||
  null;

const bestOverall =
  ranked[0] ||
  null;

const promisingCandidateFound =
  Boolean(
    bestPromisingCandidate
  );

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      // =================================================
      // KEEP ORIGINAL WORKFLOW / COLLECTION STATE
      // =================================================

      ...context,

      // =================================================
      // REQUEST TYPE MUST NEVER CHANGE HERE
      // =================================================

      requested_asset_type:
        requestedAssetType,

      asset_type:
        requestedAssetType,

      // =================================================
      // SEARCH CONTEXT
      // =================================================

      game_title:
        gameTitle,

      policy_target_name:
        policyTargetName,

      rejected_candidate_title:
        clean(
          context.rejected_candidate_title
        ),

      rejected_candidate_url:
        rejectedCandidateUrl,

      rejection_reason:
        clean(
          context.rejection_reason
        ),

      alternative_search_query:
        clean(
          context.alternative_search_query ||
          executedQuery
        ),

      alternative_strategy:
        clean(
          context.alternative_strategy
        ),

      gameplay_policy_status:
        clean(
          context.gameplay_policy_status
        ),

      screenshot_policy_status:
        clean(
          context.screenshot_policy_status
        ),

      policy_url:
        policyUrl,

      official_policy_domain:
        officialPolicyDomain,

      // =================================================
      // RESULT
      // =================================================

      candidate_count:
        ranked.length,

      compatible_candidate_count:
        compatibleCandidates.length,

      promising_candidate_count:
        promisingCandidates.length,

      results:
        ranked,

      // IMPORTANT:
      // Never use an incompatible bestOverall as the
      // candidate sent to Scrape / Analyze.
      best_result:
        bestPromisingCandidate,

      best_compatible_result:
        bestCompatibleOverall,

      best_overall_result:
        bestOverall,

      promising_candidate_found:
        promisingCandidateFound,

      needs_alternative_fallback:
        !promisingCandidateFound,

      safer_ranking_version:
        '1.1-request-type-locked-context-safe'
    }
  }
];

// ======================================================
// Prepare Final Asset Result
// Mode: Run Once for All Items
// VERSION: 2.2-request-type-locked-multibranch-safe
// ======================================================

const input =
  $input.first()?.json || {};

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {
  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {
  return Number(
    num(value).toFixed(3)
  );
}

function uniqueStrings(values) {
  return [
    ...new Set(
      (
        Array.isArray(values)
          ? values
          : []
      )
        .map(clean)
        .filter(Boolean)
    )
  ];
}

function normalizeAssetType(value) {

  const type =
    clean(value)
      .toLowerCase();

  if (
    type === 'video' ||
    type === 'image'
  ) {
    return type;
  }

  return '';
}

function normalizeMediaType(value) {

  const type =
    clean(value)
      .toLowerCase();

  if (
    type === 'video' ||
    type === 'image' ||
    type === 'mixed' ||
    type === 'unknown'
  ) {
    return type;
  }

  return 'unknown';
}

function normalizeMatchStatus(value) {

  const status =
    clean(value)
      .toLowerCase();

  if (
    status === 'exact_match' ||
    status === 'compatible_mixed' ||
    status === 'mismatch' ||
    status === 'unknown'
  ) {
    return status;
  }

  return '';
}

// ======================================================
// NODE CONTEXT
//
// Prefer paired item.
// If n8n cannot determine item pairing, use the newest
// execution rather than the oldest .first() result.
// ======================================================

function getNodeJsonSafe(nodeName) {

  try {

    const paired =
      $(nodeName).item?.json;

    if (
      paired &&
      typeof paired === 'object'
    ) {
      return paired;
    }

  } catch {
    // continue
  }

  try {

    const items =
      $(nodeName)
        .all();

    if (
      Array.isArray(items) &&
      items.length > 0
    ) {

      return (
        items[
          items.length - 1
        ]?.json || {}
      );
    }

  } catch {
    // continue
  }

  return {};
}

// ======================================================
// CONTEXTS
// ======================================================

const triggerContext =
  getNodeJsonSafe(
    'When Executed by Another Workflow'
  );

const saferRank =
  getNodeJsonSafe(
    'Rank Safer Alternatives'
  );

const saferSearchContext =
  getNodeJsonSafe(
    'Prepare Safer Alternative Search'
  );

const originalRights =
  getNodeJsonSafe(
    'Finalize Rights Gate'
  );

// ======================================================
// ORIGINAL REQUEST TYPE â€” IMMUTABLE
// ======================================================

const requestedAssetType =
  normalizeAssetType(
    input.requested_asset_type
  ) ||
  normalizeAssetType(
    input.original_asset_type
  ) ||
  normalizeAssetType(
    saferSearchContext
      .requested_asset_type
  ) ||
  normalizeAssetType(
    saferSearchContext
      .asset_type
  ) ||
  normalizeAssetType(
    saferRank.requested_asset_type
  ) ||
  normalizeAssetType(
    originalRights
      .requested_asset_type
  ) ||
  normalizeAssetType(
    triggerContext
      .requested_asset_type
  ) ||
  normalizeAssetType(
    triggerContext.asset_type
  ) ||
  normalizeAssetType(
    input.asset_type
  ) ||
  'video';

// ======================================================
// GAME TITLE
// ======================================================

const gameTitle =
  clean(
    input.game_title ||
    saferRank.game_title ||
    saferSearchContext.game_title ||
    originalRights.game_title ||
    triggerContext.game_title
  );

// ======================================================
// MEDIA TYPE MATCH
// ======================================================

function inferMatchStatus(
  mediaType,
  requestedType
) {

  const media =
    normalizeMediaType(
      mediaType
    );

  const requested =
    normalizeAssetType(
      requestedType
    );

  if (!requested) {
    return 'unknown';
  }

  if (
    media === requested
  ) {
    return 'exact_match';
  }

  if (
    media === 'mixed'
  ) {
    return 'compatible_mixed';
  }

  if (
    media === 'unknown'
  ) {
    return 'unknown';
  }

  return 'mismatch';
}

function isMediaTypeCompatible(
  matchStatus
) {

  return (
    matchStatus ===
      'exact_match' ||
    matchStatus ===
      'compatible_mixed'
  );
}

// ======================================================
// STRUCTURED OPENAI OUTPUT PARSER
//
// Supports:
// - direct simplified JSON
// - output object
// - output array
// - content[].text object
// - JSON text string
// ======================================================

function looksLikeSaferAnalysis(
  value
) {

  return Boolean(
    value &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    (
      Object.prototype
        .hasOwnProperty
        .call(
          value,
          'candidate_page_applies_to_game'
        ) ||
      Object.prototype
        .hasOwnProperty
        .call(
          value,
          'requested_type_match_status'
        ) ||
      Object.prototype
        .hasOwnProperty
        .call(
          value,
          'downloadable_asset_urls'
        )
    )
  );
}

function parseJsonString(value) {

  const text =
    clean(value);

  if (!text) {
    return null;
  }

  const unfenced =
    text
      .replace(
        /^```(?:json)?\s*/i,
        ''
      )
      .replace(
        /\s*```$/i,
        ''
      )
      .trim();

  if (
    !unfenced.startsWith('{')
  ) {
    return null;
  }

  try {

    const parsed =
      JSON.parse(
        unfenced
      );

    return parsed;

  } catch {

    return null;
  }
}

function extractSaferAnalysis(
  value,
  depth = 0
) {

  if (
    value == null ||
    depth > 6
  ) {
    return null;
  }

  if (
    looksLikeSaferAnalysis(
      value
    )
  ) {
    return value;
  }

  if (
    typeof value ===
      'string'
  ) {

    const parsed =
      parseJsonString(
        value
      );

    if (
      looksLikeSaferAnalysis(
        parsed
      )
    ) {
      return parsed;
    }

    return null;
  }

  if (
    Array.isArray(value)
  ) {

    for (
      const entry of value
    ) {

      const found =
        extractSaferAnalysis(
          entry,
          depth + 1
        );

      if (found) {
        return found;
      }
    }

    return null;
  }

  if (
    typeof value ===
      'object'
  ) {

    const preferredKeys = [
      'output',
      'content',
      'text',
      'response',
      'result',
      'message',
      'data'
    ];

    for (
      const key of
      preferredKeys
    ) {

      if (
        Object.prototype
          .hasOwnProperty
          .call(
            value,
            key
          )
      ) {

        const found =
          extractSaferAnalysis(
            value[key],
            depth + 1
          );

        if (found) {
          return found;
        }
      }
    }
  }

  return null;
}

// ======================================================
// EDITORIAL INPUT DETECTION
// ======================================================

const editorialTimeline =
  Array.isArray(
    input.editorial_timeline
  )
    ? input.editorial_timeline
    : [];

const assemblyClips =
  Array.isArray(
    input.assembly_clips
  )
    ? input.assembly_clips
    : [];

const isEditorialInput =
  Boolean(
    input.asset_origin ===
      'editorial_collection' ||
    input.selected_asset_source ===
      'editorial_collection' ||
    input.final_timeline_status ||
    input.ready_for_asset_finalize !==
      undefined ||
    assemblyClips.length > 0 ||
    editorialTimeline.length > 0
  );

// ======================================================
// EDITORIAL CASE
// ======================================================

if (isEditorialInput) {

  // Editorial collection is video-only.
  if (
    requestedAssetType !==
      'video'
  ) {

    return [
      {
        json: {

          game_title:
            gameTitle,

          requested_asset_type:
            requestedAssetType,

          asset_type:
            requestedAssetType,

          asset_media_type:
            'video',

          observed_asset_media_type:
            'video',

          requested_type_match_status:
            'mismatch',

          asset_type_mismatch:
            true,

          asset_origin:
            'editorial_collection',

          selected_asset_source:
            'none',

          workflow_outcome:
            'fallback_required',

          final_status:
            'editorial_asset_type_mismatch',

          asset_ready:
            false,

          requires_fallback:
            true,

          safe_for_auto_use:
            false,

          can_download:
            false,

          final_asset_urls:
            [],

          final_asset_paths:
            [],

          recommended_next_action:
            'continue_search_for_requested_asset_type',

          fallback_reason:
            (
              `An editorial video collection was prepared, ` +
              `but the original request requires ${requestedAssetType}.`
            ),

          rights_summary:
            'Editorial video material cannot replace a different requested media type.',

          final_asset_result_version:
            '2.2-request-type-locked-multibranch-safe'
        }
      }
    ];
  }

  const invalidAssemblyClips =
    assemblyClips.filter(
      clip =>
        !clean(
          clip?.path
        ) ||
        num(
          clip?.duration,
          0
        ) <= 0
    );

  const allClipPathsReady =
    assemblyClips.length > 0 &&
    invalidAssemblyClips
      .length === 0;

  const timelineStateReady =
    input.ready_for_asset_finalize ===
      true &&
    input.final_timeline_status ===
      'ready' &&
    input.timeline_all_paths_ready ===
      true;

  const editorialReady =
    timelineStateReady &&
    allClipPathsReady;

  const sourceUrls =
    uniqueStrings(
      Array.isArray(
        input.source_urls
      )
        ? input.source_urls
        : []
    );

  const sourceDistribution =
    Array.isArray(
      input.source_distribution
    )
      ? input.source_distribution
      : [];

  const timelineDuration =
    num(
      input
        .editorial_timeline_duration_seconds,
      assemblyClips.reduce(
        (sum, clip) =>
          sum +
          num(
            clip?.duration,
            0
          ),
        0
      )
    );

  const targetVideoDuration =
    num(
      input
        .target_video_duration_sec,
      0
    );

  const desiredFootage =
    num(
      input
        .desired_footage_seconds,
      0
    );

  const editorialCoverageRatio =
    targetVideoDuration > 0
      ? (
          timelineDuration /
          targetVideoDuration
        )
      : 0;

  const desiredFootageCoverageRatio =
    desiredFootage > 0
      ? (
          timelineDuration /
          desiredFootage
        )
      : 0;

  const localAssetPaths =
    uniqueStrings(
      assemblyClips.map(
        clip =>
          clip?.path
      )
    );

  const requiresVisualSupplement =
    input.requires_visual_supplement ===
      true;

  const realFootageTargetShortfall =
    num(
      input
        .real_footage_target_shortfall_seconds ??
      input
        .footage_shortfall_seconds,
      0
    );

  const recommendedNextAction =
    !editorialReady
      ? 'generate_original_asset_or_rebuild_collection'
      : requiresVisualSupplement
        ? 'supplement_editorial_timeline_then_assemble'
        : 'assemble_editorial_timeline';

  return [
    {
      json: {

        game_title:
          gameTitle,

        requested_asset_type:
          requestedAssetType,

        asset_type:
          requestedAssetType,

        asset_media_type:
          'video',

        observed_asset_media_type:
          'video',

        requested_type_match_status:
          'exact_match',

        asset_type_mismatch:
          false,

        asset_origin:
          'editorial_collection',

        selected_asset_source:
          editorialReady
            ? 'editorial_collection'
            : 'none',

        result_type:
          'editorial_collection',

        workflow_outcome:
          editorialReady
            ? 'asset_ready'
            : 'fallback_required',

        final_status:
          editorialReady
            ? (
                requiresVisualSupplement
                  ? 'editorial_collection_ready_with_shortfall'
                  : 'editorial_collection_ready'
              )
            : 'editorial_collection_invalid',

        asset_ready:
          editorialReady,

        requires_fallback:
          !editorialReady,

        recommended_next_action:
          recommendedNextAction,

        // Editorial footage is intentionally not
        // classified as generic auto-use.
        safe_for_auto_use:
          false,

        rights_use_mode:
          'editorial_transformative_use',

        editorial_use:
          true,

        transformative_edit_required:
          true,

        preserve_source_attribution:
          true,

        source_audio_should_remain_muted:
          true,

        rights_summary:
          (
            'Prepared as an editorial/transformative multi-source video collection. ' +
            'This is a workflow risk classification, not a legal determination.'
          ),

        can_download:
          false,

        local_assets_ready:
          allClipPathsReady,

        final_asset_urls:
          [],

        final_asset_paths:
          localAssetPaths,

        source_urls:
          sourceUrls,

        editorial_timeline:
          editorialTimeline,

        assembly_clips:
          assemblyClips,

        clip_count:
          assemblyClips.length,

        editorial_timeline_clip_count:
          num(
            input
              .editorial_timeline_clip_count,
            assemblyClips.length
          ),

        timeline_duration_seconds:
          round3(
            timelineDuration
          ),

        editorial_timeline_duration_seconds:
          round3(
            timelineDuration
          ),

        total_footage_seconds:
          round3(
            timelineDuration
          ),

        target_video_duration_sec:
          round3(
            targetVideoDuration
          ),

        desired_footage_seconds:
          round3(
            desiredFootage
          ),

        remaining_video_seconds:
          round3(
            Math.max(
              0,
              targetVideoDuration -
              timelineDuration
            )
          ),

        editorial_coverage_ratio:
          round3(
            editorialCoverageRatio
          ),

        desired_footage_coverage_ratio:
          round3(
            desiredFootageCoverageRatio
          ),

        source_count:
          sourceUrls.length,

        source_distribution:
          sourceDistribution,

        collection_status:
          clean(
            input.collection_status
          ),

        sources_exhausted:
          input.sources_exhausted ===
            true,

        partial_collection_ready:
          input.partial_collection_ready ===
            true,

        requires_visual_supplement:
          requiresVisualSupplement,

        real_footage_target_shortfall_seconds:
          round3(
            realFootageTargetShortfall
          ),

        timeline_all_paths_ready:
          allClipPathsReady,

        invalid_assembly_clips:
          invalidAssemblyClips,

        invalid_assembly_clip_count:
          invalidAssemblyClips.length,

        ready_for_assembly:
          editorialReady,

        ready_for_asset_finalize:
          editorialReady,

        ready_for_content_pipeline:
          editorialReady,

        timeline_ordering_strategy:
          clean(
            input
              .timeline_ordering_strategy
          ),

        final_timeline_version:
          clean(
            input
              .final_timeline_version
          ),

        final_clip_rebuild_version:
          clean(
            input
              .final_clip_rebuild_version
          ),

        temporal_dedup_version:
          clean(
            input
              .temporal_dedup_version
          ),

        physical_trim_version:
          clean(
            input
              .physical_trim_version
          ),

        fallback_reason:
          editorialReady
            ? ''
            : (
                clean(
                  input.fallback_reason
                ) ||
                'The editorial timeline was not fully ready for final use.'
              ),

        final_asset_result_version:
          '2.2-request-type-locked-multibranch-safe'
      }
    }
  ];
}

// ======================================================
// ANALYZED SAFER ALTERNATIVE
// ======================================================

const saferAnalysis =
  extractSaferAnalysis(
    input
  );

if (saferAnalysis) {

  const analysis =
    saferAnalysis;

  const bestResult =
    (
      saferRank.best_result &&
      typeof saferRank.best_result ===
        'object'
    )
      ? saferRank.best_result
      : {};

  const analysisRequestedType =
    normalizeAssetType(
      analysis.requested_asset_type
    );

  const assetMediaType =
    normalizeMediaType(
      analysis.asset_media_type
    );

  let requestedTypeMatchStatus =
    normalizeMatchStatus(
      analysis
        .requested_type_match_status
    );

  if (!requestedTypeMatchStatus) {

    requestedTypeMatchStatus =
      inferMatchStatus(
        assetMediaType,
        requestedAssetType
      );
  }

  // If the model itself reports a different requested
  // type than the immutable workflow request, fail safe.
  const analysisRequestMismatch =
    Boolean(
      analysisRequestedType &&
      analysisRequestedType !==
        requestedAssetType
    );

  if (analysisRequestMismatch) {

    requestedTypeMatchStatus =
      'mismatch';
  }

  const typeCompatible =
    isMediaTypeCompatible(
      requestedTypeMatchStatus
    );

  const downloadableUrls =
    uniqueStrings(
      analysis
        .downloadable_asset_urls
    );

  const completeLicenseTermsPresent =
    analysis
      .license_evidence_status ===
    'explicit';

  const appliesToGame =
    analysis
      .candidate_page_applies_to_game ===
    true;

  const downloadableAssetsFound =
    analysis
      .downloadable_assets_found ===
    true &&
    downloadableUrls.length > 0;

  // ====================================================
  // HARD SAFETY GATE
  // ====================================================

  const safeForAutoUse =
    analysis.safe_for_auto_use ===
      true &&
    analysis.requires_fallback !==
      true &&
    appliesToGame &&
    typeCompatible &&
    !analysisRequestMismatch &&
    downloadableAssetsFound &&
    completeLicenseTermsPresent &&
    analysis.reuse_status ===
      'allowed';

  const requiresFallback =
    !safeForAutoUse;

  const workflowOutcome =
    safeForAutoUse
      ? 'asset_ready'
      : 'fallback_required';

  const finalStatus =
    safeForAutoUse
      ? 'safe_alternative_asset_found'
      : (
          requestedTypeMatchStatus ===
            'mismatch'
            ? 'alternative_asset_type_mismatch'
            : 'no_safe_asset_found'
        );

  const selectedAssetSource =
    safeForAutoUse
      ? 'licensed_alternative'
      : 'none';

  const recommendedNextAction =
    safeForAutoUse
      ? 'use_selected_asset'
      : 'generate_original_asset_or_continue_search';

  let fallbackReason =
    clean(
      analysis.fallback_reason
    );

  if (
    requestedTypeMatchStatus ===
      'mismatch'
  ) {

    fallbackReason =
      (
        `The discovered alternative is ${assetMediaType}, ` +
        `but the original request requires ${requestedAssetType}.`
      );

  } else if (
    analysisRequestMismatch
  ) {

    fallbackReason =
      (
        `The rights analysis was produced for ${analysisRequestedType}, ` +
        `but the workflow request requires ${requestedAssetType}.`
      );

  } else if (
    !fallbackReason &&
    !safeForAutoUse
  ) {

    fallbackReason =
      'The alternative asset did not satisfy the automatic-use rights and media-type requirements.';
  }

  return [
    {
      json: {

        game_title:
          gameTitle,

        requested_asset_type:
          requestedAssetType,

        asset_type:
          requestedAssetType,

        policy_target_name:
          clean(
            saferRank
              .policy_target_name ||
            saferSearchContext
              .policy_target_name
          ),

        original_candidate_title:
          clean(
            saferSearchContext
              .rejected_candidate_title ||
            originalRights
              .candidate_title
          ),

        original_candidate_url:
          clean(
            saferSearchContext
              .rejected_candidate_url ||
            originalRights
              .candidate_url
          ),

        original_rejection_reason:
          clean(
            saferSearchContext
              .rejection_reason ||
            originalRights
              .decision_reason
          ),

        alternative_candidate_title:
          clean(
            bestResult.title
          ),

        alternative_candidate_page_url:
          clean(
            bestResult.url
          ),

        alternative_candidate_domain:
          clean(
            bestResult.domain
          ),

        alternative_candidate_kind:
          clean(
            bestResult
              .candidate_kind
          ),

        // Actual observed type of discovered page/assets
        asset_media_type:
          assetMediaType,

        observed_asset_media_type:
          assetMediaType,

        requested_type_match_status:
          requestedTypeMatchStatus,

        asset_type_mismatch:
          requestedTypeMatchStatus ===
            'mismatch',

        candidate_page_applies_to_game:
          appliesToGame,

        downloadable_assets_found:
          downloadableAssetsFound,

        discovered_asset_urls:
          downloadableUrls,

        final_asset_urls:
          safeForAutoUse
            ? downloadableUrls
            : [],

        raw_license_terms_present:
          analysis
            .license_terms_present ===
          true,

        license_evidence_status:
          clean(
            analysis
              .license_evidence_status ||
            'none'
          ),

        complete_license_terms_present:
          completeLicenseTermsPresent,

        reuse_status:
          clean(
            analysis.reuse_status ||
            'unclear'
          ),

        modification_allowed:
          clean(
            analysis
              .modification_allowed ||
            'unclear'
          ),

        redistribution_allowed:
          clean(
            analysis
              .redistribution_allowed ||
            'unclear'
          ),

        monetization_allowed:
          clean(
            analysis
              .monetization_allowed ||
            'unclear'
          ),

        commercial_use_allowed:
          clean(
            analysis
              .commercial_use_allowed ||
            'unclear'
          ),

        attribution_required:
          clean(
            analysis
              .attribution_required ||
            'unclear'
          ),

        workflow_outcome:
          workflowOutcome,

        final_status:
          finalStatus,

        selected_asset_source:
          selectedAssetSource,

        asset_origin:
          safeForAutoUse
            ? 'verified_existing_asset'
            : 'none',

        result_type:
          safeForAutoUse
            ? 'verified_existing_asset'
            : 'no_asset',

        asset_ready:
          safeForAutoUse,

        safe_for_auto_use:
          safeForAutoUse,

        can_download:
          safeForAutoUse,

        requires_fallback:
          requiresFallback,

        ready_for_content_pipeline:
          safeForAutoUse,

        ready_for_assembly:
          safeForAutoUse,

        recommended_next_action:
          recommendedNextAction,

        rights_confidence:
          clean(
            analysis
              .rights_confidence ||
            'low'
          ),

        key_evidence:
          Array.isArray(
            analysis.key_evidence
          )
            ? analysis
                .key_evidence
            : [],

        fallback_reason:
          fallbackReason,

        rights_summary:
          clean(
            analysis
              .rights_summary
          ),

        final_asset_result_version:
          '2.2-request-type-locked-multibranch-safe'
      }
    }
  ];
}

// ======================================================
// DIRECT INITIAL RIGHTS
// ======================================================

if (
  Object.prototype
    .hasOwnProperty
    .call(
      input,
      'rights_decision'
    )
) {

  const candidateMediaType =
    normalizeMediaType(
      input.candidate_asset_type ||
      input.asset_media_type ||
