function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {
  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {
  return Number(
    num(value).toFixed(3)
  );
}

function uniqueStrings(values) {
  return [
    ...new Set(
      (
        Array.isArray(values)
          ? values
          : []
      )
        .map(clean)
        .filter(Boolean)
    )
  ];
}

function normalizeAssetType(value) {

  const type =
    clean(value)
      .toLowerCase();

  if (
    type === 'video' ||
    type === 'image'
  ) {
    return type;
  }

  return '';
}

function inferAssetTypeFromPath(value) {

  const path =
    clean(value)
      .toLowerCase();

  if (!path) {
    return '';
  }

  if (
    /\.(mp4|webm|mov|mkv|m4v)(?:$|\?)/i
      .test(path)
  ) {
    return 'video';
  }

  if (
    /\.(png|jpg|jpeg|webp|gif)(?:$|\?)/i
      .test(path)
  ) {
    return 'image';
  }

  return '';
}

