// ======================================================
// Prepare Editorial Video
// Version: 2.1-canonical-active-candidate-safe
// Mode: Run Once for All Items
// ======================================================

const input = $input.first().json || {};

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function pick(...values) {

  for (const value of values) {

    const v = clean(value);

    if (v) {
      return v;
    }
  }

  return '';
}

function slug(value) {

  return clean(value)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\w\s-]/g, '')
    .replace(/[_\s]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 60);
}

function hashString(value) {

  const str = clean(value);

  let hash = 2166136261;

  for (let i = 0; i < str.length; i++) {

    hash ^= str.charCodeAt(i);

    hash +=
      (hash << 1) +
      (hash << 4) +
      (hash << 7) +
      (hash << 8) +
      (hash << 24);
  }

  return (hash >>> 0).toString(36);
}

// ======================================================
// URL HELPERS
// ======================================================

function unwrapMarkdownUrl(value) {

  const raw = clean(value);

  if (!raw) {
    return '';
  }

  const match = raw.match(
    /^\[(https?:\/\/[^\]]+)\]\((https?:\/\/[^)]+)\)$/i
  );

  if (match) {
    return match[2] || match[1] || '';
  }

  return raw;
}

function canonicalizeUrl(value) {

  const raw = unwrapMarkdownUrl(value);

  if (!raw) {
    return '';
  }

  try {

    const parsed = new URL(raw);

    const host = parsed.hostname
      .replace(/^www\./i, '')
      .replace(/^m\./i, '')
      .toLowerCase();

    // --------------------------------------------------
    // Redirect wrappers (Google search-result redirects, Facebook link
    // shields, etc.) -- unwrap to the real target and re-canonicalize it,
    // so the same underlying video always resolves to one identity
    // regardless of which wrapped URL a search result happened to return.
    // --------------------------------------------------

    const redirectWrapperHosts = new Set([
      'google.com', 'l.facebook.com', 'lm.facebook.com', 'l.instagram.com'
    ]);

    if (redirectWrapperHosts.has(host)) {

      const inner =
        parsed.searchParams.get('url') ||
        parsed.searchParams.get('q') ||
        parsed.searchParams.get('u');

      if (inner) {

        let decoded = inner;

        try {
          decoded = decodeURIComponent(inner);
        } catch {
          decoded = inner;
        }

        return canonicalizeUrl(decoded);
      }
    }

    // --------------------------------------------------
    // YouTube
    // --------------------------------------------------

    if (
      host === 'youtube.com' ||
      host === 'youtu.be'
    ) {

      let videoId = '';

      if (host === 'youtu.be') {

        videoId =
          parsed.pathname
            .replace(/^\/+/, '')
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams.get('v') || '';

        if (!videoId) {

          const shorts =
            parsed.pathname.match(
              /^\/shorts\/([^/?#]+)/i
            );

          if (shorts?.[1]) {
            videoId = shorts[1];
          }
        }

        if (!videoId) {

          const embed =
            parsed.pathname.match(
              /^\/embed\/([^/?#]+)/i
            );

          if (embed?.[1]) {
            videoId = embed[1];
          }
        }
      }

      if (videoId) {

        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    // --------------------------------------------------
    // Dailymotion
    // --------------------------------------------------

    if (host === 'dailymotion.com') {

      const match =
        parsed.pathname.match(
          /\/video\/([A-Za-z0-9]+)/i
        );

      if (match?.[1]) {

        return (
          `https://www.dailymotion.com/video/${match[1]}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return raw;
  }
}

// ======================================================
// EXISTING CURRENT CANDIDATE
// ======================================================

const currentCandidate =
  input.current_candidate &&
  typeof input.current_candidate === 'object' &&
  !Array.isArray(input.current_candidate)
    ? input.current_candidate
    : {};

// ======================================================
// GAME
// ======================================================

const gameTitle =
  clean(input.game_title);

if (!gameTitle) {

  throw new Error(
    'Prepare Editorial Video: game_title is missing.'
  );
}

// ======================================================
// ACTIVE CANDIDATE
//
// IMPORTANT:
// Explicit active-processing fields have priority over
// potentially stale current_candidate/source_* aliases.
// ======================================================

const sourceTitle =
  pick(
    input.processing_source_title,
    input.candidate_title,
    currentCandidate.title,
    input.source_title
  );

const sourceUrl =
  canonicalizeUrl(
    pick(
      input.processing_source_url,
      input.candidate_url,
      currentCandidate.url,
      input.source_url
    )
  );

const sourceChannel =
  pick(
    input.processing_source_channel,
    input.candidate_channel,
    currentCandidate.channel,
    input.source_channel
  );

const sourceClass =
  pick(
    input.processing_source_class,
    input.candidate_source_class,
    currentCandidate.source_class,
    input.source_class
  );

let sourcePlatform =
  pick(
    input.processing_source_platform,
    input.candidate_source,
    currentCandidate.source,
    input.source_platform
  );

if (!sourcePlatform) {

  if (
    sourceUrl.includes('youtube.com') ||
    sourceUrl.includes('youtu.be')
  ) {

    sourcePlatform = 'YouTube';

  } else if (
    sourceUrl.includes('dailymotion.com')
  ) {

    sourcePlatform = 'Dailymotion';
  }
}

const sourceAuthenticityScore =
  num(
    input.source_authenticity_score,
    num(
      currentCandidate.source_authenticity_score,
      num(
        input.preliminary_source_trust_score,
        0
      )
    )
  );

// ======================================================
// RIGHTS STATE
// ======================================================

const rightsDecision =
  pick(
    input.rights_decision,
    currentCandidate.rights_decision
  ).toLowerCase();

const rightsStatus =
  pick(
    input.rights_status,
    currentCandidate.rights_status
  ).toLowerCase();

const requiresHumanReview =
  input.requires_human_review === true ||
  currentCandidate.requires_human_review === true;

const explicitlyBlocked =
  [
    'block',
    'blocked',
    'prohibited'
  ].includes(rightsDecision) ||
  [
    'blocked',
    'blocked_by_policy'
  ].includes(rightsStatus);

const editorialAllowed =
  input.editorial_pipeline_allowed === true ||
  input.editorial_use_allowed === true ||
  currentCandidate.editorial_pipeline_allowed === true ||
  currentCandidate.editorial_use_allowed === true ||
  input.can_download === true ||
  currentCandidate.can_download === true ||
  [
    'auto_use',
    'editorial_use',
    'editorial_transformative_use',
    'allowed'
  ].includes(rightsDecision);

const readyForDownload =
  Boolean(
    sourceUrl &&
    editorialAllowed &&
    !requiresHumanReview &&
    !explicitlyBlocked
  );

// ======================================================
// STABLE SOURCE ID
//
// One canonical URL always receives the same ID.
// Search round / retry count must NOT modify identity.
// ======================================================

const gameSlug =
  slug(gameTitle) || 'game';

const identitySeed =
  sourceUrl
    ? `${gameTitle}|${sourceUrl}`
    : `${gameTitle}|${sourceTitle}`;

const generatedSourceId =
  `${gameSlug}-editorial-${hashString(identitySeed)}-run-${$execution.id}`;

// ======================================================
// STABLE DOWNLOAD IDENTITY (source dedupe)
//
// Deliberately WITHOUT the run suffix: the same canonical URL must always
// resolve to the same downloaded file across executions, so a source that
// is already downloaded and verified in cache is reused instead of
// re-fetched. Scene/clip working-directory identity (sourceId/file_slug
