const fs = require('fs');
const { execFileSync } = require('child_process');

// =====================================================
// CHECK EDITORIAL VIDEO QUALITY
// VERSION: 2.3-codec-aware-bitrate-threshold
// =====================================================

const file =
  String(process.env.FILE || '').trim();

// =====================================================
// HELPERS
// =====================================================

function num(value, fallback = 0) {
  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {
  return Number(
    num(value).toFixed(3)
  );
}

function parseRate(value) {

  const text =
    String(value || '').trim();

  if (!text) {
    return 0;
  }

  if (text.includes('/')) {

    const [a, b] =
      text.split('/')
        .map(Number);

    if (
      Number.isFinite(a) &&
      Number.isFinite(b) &&
      b !== 0
    ) {
      return a / b;
    }

    return 0;
  }

  return num(text, 0);
}

function printResult(result) {

  console.log(
    `QUALITY_STATUS=${result.quality_status}`
  );

  console.log(
    `QUALITY_ACCEPTED=${result.quality_accepted}`
  );

  console.log(
    `SOURCE_EXISTS=${result.source_exists}`
  );

  console.log(
    `SOURCE_FILE_EXISTS=${result.source_exists}`
  );

  console.log(
    `SOURCE_FILE_PATH=${result.source_file_path}`
  );

  console.log(
    `DETECTED_WIDTH=${result.width}`
  );

  console.log(
    `DETECTED_HEIGHT=${result.height}`
  );

  console.log(
    `DETECTED_CODEC=${result.codec}`
  );

  console.log(
    `DETECTED_FPS=${result.fps}`
  );

  console.log(
    `DETECTED_BITRATE_BPS=${result.bitrate_bps}`
  );

  console.log(
    `DETECTED_BITRATE_MBPS=${result.bitrate_mbps}`
  );

  console.log(
    `DETECTED_DURATION=${result.duration}`
  );

  console.log(
    `QUALITY_THRESHOLD_MBPS=${result.threshold_mbps}`
  );

  console.log(
    `QUALITY_REASON=${result.reason}`
  );

  // ==================================================
  // COMPATIBILITY ALIASES
  // ==================================================

  console.log(
    `WIDTH=${result.width}`
  );

  console.log(
    `HEIGHT=${result.height}`
  );

  console.log(
    `CODEC=${result.codec}`
  );

  console.log(
    `FPS=${result.fps}`
  );

  console.log(
    `BITRATE_BPS=${result.bitrate_bps}`
  );

  console.log(
    `BITRATE_MBPS=${result.bitrate_mbps}`
  );

  console.log(
    `DURATION=${result.duration}`
  );

  console.log(
    `QUALITY_CHECK_VERSION=2.3-codec-aware-bitrate-threshold`
  );

  console.log(
    'QUALITY_RESULT_JSON=' +
    JSON.stringify(result)
  );
}

// =====================================================
// SOURCE MISSING
// =====================================================

if (
  !file ||
  !fs.existsSync(file)
) {

  printResult({

    quality_status:
      'source_missing',

    quality_accepted:
      false,

    source_exists:
      false,

    source_file_path:
      file,

    width:
      0,

    height:
      0,

    codec:
      '',

    fps:
      0,

    bitrate_bps:
      0,

    bitrate_mbps:
      0,

    duration:
      0,

    threshold_mbps:
      0,

    reason:
      'source_file_missing'
  });

  process.exit(0);
}

// =====================================================
// FFPROBE
// =====================================================

let probe;

try {

  const raw =
    execFileSync(
      'ffprobe',
      [
        '-v',
        'error',

        '-show_entries',
        [
          'format=duration,bit_rate',
          'stream=codec_type,codec_name,width,height,avg_frame_rate,r_frame_rate,bit_rate'
        ].join(':'),

        '-of',
        'json',

        file
      ],
      {
        encoding:
          'utf8'
      }
    );

  probe =
    JSON.parse(raw);

} catch {

  printResult({

    quality_status:
      'probe_failed',

    quality_accepted:
      false,

    source_exists:
      true,

    source_file_path:
      file,

    width:
      0,

    height:
      0,

    codec:
      '',

    fps:
      0,

    bitrate_bps:
      0,

    bitrate_mbps:
      0,

    duration:
      0,

    threshold_mbps:
      0,

    reason:
      'ffprobe_failed'
  });

  process.exit(0);
}

// =====================================================
// VIDEO STREAM
// =====================================================

const streams =
  Array.isArray(probe.streams)
    ? probe.streams
    : [];

const video =
  streams.find(
    stream =>
      stream.codec_type === 'video'
  ) || {};

const format =
  probe.format || {};

const width =
  num(video.width, 0);

const height =
  num(video.height, 0);

const codec =
  String(
    video.codec_name || ''
  )
    .trim()
    .toLowerCase();

const fps =
  round3(
    parseRate(
      video.avg_frame_rate ||
      video.r_frame_rate
    )
  );

const duration =
  round3(
    format.duration
  );

// =====================================================
// BITRATE
// =====================================================

const bitrateBps =
  num(video.bit_rate, 0) ||
  num(format.bit_rate, 0);

const bitrateMbps =
  round3(
    bitrateBps / 1000000
  );

// =====================================================
// EDITORIAL WEB-VIDEO THRESHOLDS
//
// These are minimum usability thresholds,
// NOT mastering / archival thresholds.
//
// Short editorial excerpts from YouTube and official
// web video should not be rejected just because they
// were efficiently encoded.
// =====================================================

let thresholdMbps = 0;

if (
  height >= 2160 ||
  width >= 3840
) {

  thresholdMbps = 8.0;

} else if (
  height >= 1440 ||
  width >= 2560
) {

  thresholdMbps = 5.0;

} else if (
  height >= 1080 ||
  width >= 1920
) {

  thresholdMbps = 3.0;

} else if (
  height >= 720 ||
  width >= 1280
) {

  thresholdMbps = 1.5;

} else {

  thresholdMbps = 0;
}

// =====================================================
// EFFICIENT CODECS
//
// Real-world bitrate-for-equivalent-quality varies a lot by codec.
// AV1 in particular commonly matches H.264 quality at roughly
// 30-50% of the bitrate (not just ~75%) -- a single 0.75x discount
// for all "efficient" codecs undersells AV1 specifically and wrongly
// rejects genuinely good, officially-published AV1 web video.
// =====================================================

if (
  [
    'hevc',
    'h265',
    'vp9'
  ].includes(codec)
) {

  thresholdMbps =
    thresholdMbps * 0.65;

} else if (
  [
    'av1',
    'av01'
  ].includes(codec)
) {

  thresholdMbps =
    thresholdMbps * 0.4;
}

// =====================================================
// HIGH FRAME RATE
//
// 50/60fps needs somewhat more bitrate than 24/30fps for
// less efficient codecs, but modern codecs (AV1/HEVC/VP9)
// already handle high frame rate motion efficiently via
// better inter-frame prediction, so do not stack this
// penalty on top of the codec-efficiency discount above.
// =====================================================

if (
  fps >= 50 &&
  ![
    'hevc',
    'h265',
    'vp9',
    'av1',
    'av01'
  ].includes(codec)
) {

  thresholdMbps =
    thresholdMbps * 1.15;
}

thresholdMbps =
  round3(
    thresholdMbps
  );

// =====================================================
// QUALITY DECISION
// =====================================================

let qualityStatus =
  'accepted';

let qualityAccepted =
  true;

let reason =
  'quality_ok';

if (
  !width ||
  !height
) {

  qualityStatus =
    'rejected';

  qualityAccepted =
    false;

  reason =
    'missing_video_dimensions';

} else if (
  height < 720 &&
  width < 1280
) {

  qualityStatus =
    'rejected';

  qualityAccepted =
    false;

  reason =
    'resolution_below_720p';

} else if (
  fps > 0 &&
  fps < 23
) {

  qualityStatus =
    'rejected';

  qualityAccepted =
    false;

  reason =
    'fps_below_23';

} else if (
  bitrateMbps > 0 &&
  thresholdMbps > 0 &&
  bitrateMbps < thresholdMbps
) {

  qualityStatus =
    'rejected';

  qualityAccepted =
    false;

  reason =
    'bitrate_below_threshold';

} else if (
  bitrateMbps <= 0
) {

  qualityStatus =
    'accepted';

  qualityAccepted =
    true;

  reason =
    'quality_ok_bitrate_unavailable';
}

// =====================================================
// OUTPUT
// =====================================================

printResult({

  quality_status:
    qualityStatus,

  quality_accepted:
    qualityAccepted,

  source_exists:
    true,

  source_file_path:
    file,

  width,

  height,

  codec,

  fps,

  bitrate_bps:
    bitrateBps,

  bitrate_mbps:
    bitrateMbps,

  duration,

  threshold_mbps:
    thresholdMbps,

  reason
});

