// ======================================================
// Parse Editorial Quality
// Version: 2.1-quality-state-restore-safe
// Mode: Run Once for All Items
// ======================================================

const commandInput =
  $input.first()?.json || {};

// ======================================================
// RESTORE ACTIVE CANDIDATE CONTEXT
// ======================================================

let context = {};

try {

  context =
    $('Prepare Editorial Video').item.json || {};

} catch {

  try {

    context =
      $('Prepare Editorial Video').first().json || {};

  } catch {

    context = {};
  }
}

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function bool(value, fallback = false) {

  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }

  const text =
    clean(value).toLowerCase();

  if (text === 'true') {
    return true;
  }

  if (text === 'false') {
    return false;
  }

  return fallback;
}

// ======================================================
// STDOUT
// ======================================================

const stdout =
  clean(commandInput.stdout);

// ======================================================
// PARSE KEY=VALUE OUTPUT
// ======================================================

const values = {};

for (const line of stdout.split(/\r?\n/)) {

  const index =
    line.indexOf('=');

  if (index <= 0) {
    continue;
  }

  const key =
    line
      .slice(0, index)
      .trim();

  const value =
    line
      .slice(index + 1)
      .trim();

  if (key) {
    values[key] = value;
  }
}

// ======================================================
// PARSE STRUCTURED QUALITY JSON IF AVAILABLE
// ======================================================

let result = {};

if (values.QUALITY_RESULT_JSON) {

  try {

    result =
      JSON.parse(
        values.QUALITY_RESULT_JSON
      );

  } catch {

    result = {};
  }
}

// ======================================================
// NORMALIZED QUALITY RESULT
// ======================================================

const qualityStatus =
  clean(
    result.quality_status ||
    values.QUALITY_STATUS ||
    'unknown'
  );

const qualityAccepted =
  bool(
    result.quality_accepted ??
    values.QUALITY_ACCEPTED,
    false
  );

const sourceExists =
  bool(
    result.source_exists ??
    values.SOURCE_EXISTS ??
    values.SOURCE_FILE_EXISTS,
    false
  );

const sourceFilePath =
  clean(
    result.source_file_path ||
    values.SOURCE_FILE_PATH ||
    context.source_file_path
  );

const width =
  num(
    result.width ??
    values.DETECTED_WIDTH ??
    values.WIDTH,
    0
  );

const height =
  num(
    result.height ??
    values.DETECTED_HEIGHT ??
    values.HEIGHT,
    0
  );

const codec =
  clean(
    result.codec ||
    values.DETECTED_CODEC ||
    values.CODEC
  );

const fps =
  num(
    result.fps ??
    values.DETECTED_FPS ??
    values.FPS,
    0
  );

const bitrateBps =
  num(
    result.bitrate_bps ??
    values.DETECTED_BITRATE_BPS ??
    values.BITRATE_BPS,
    0
  );

const bitrateMbps =
  num(
    result.bitrate_mbps ??
    values.DETECTED_BITRATE_MBPS ??
    values.BITRATE_MBPS,
    0
  );

const duration =
  num(
    result.duration ??
    values.DETECTED_DURATION ??
    values.DURATION,
    0
  );

const thresholdMbps =
  num(
    result.threshold_mbps ??
    values.QUALITY_THRESHOLD_MBPS,
    0
  );

const reason =
  clean(
    result.reason ||
    values.QUALITY_REASON ||
    (
      qualityAccepted
        ? 'quality_ok'
        : 'quality_check_failed'
    )
  );

// ======================================================
// SAFETY NORMALIZATION
// ======================================================

let finalQualityStatus =
  qualityStatus;

let finalQualityAccepted =
  qualityAccepted;

let finalReason =
  reason;

if (!sourceExists) {

  finalQualityStatus =
    'source_missing';

  finalQualityAccepted =
    false;

  finalReason =
    finalReason ||
    'source_file_missing';
}

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      // Restore ALL candidate / collection / retry state
      ...context,

      // Preserve command information for debugging
      quality_command_exit_code:
        num(commandInput.exitCode, 0),

      quality_command_stderr:
        clean(commandInput.stderr),

      quality_command_stdout:
        stdout,

      // =================================================
      // QUALITY
      // =================================================

      quality_status:
        finalQualityStatus,

      quality_accepted:
        finalQualityAccepted,

      quality_rejection_reason:
        finalQualityAccepted
          ? ''
          : finalReason,

      quality_reason:
        finalReason,

      source_file_exists:
        sourceExists,

      source_downloaded:
        sourceExists,

      source_file_path:
        sourceFilePath,

      detected_width:
        width,

      detected_height:
        height,

      detected_codec:
        codec,

      detected_fps:
        fps,

      detected_bitrate:
        bitrateBps,

      detected_bitrate_bps:
        bitrateBps,

      detected_bitrate_mbps:
        bitrateMbps,

      detected_duration:
        duration,

      quality_threshold_mbps:
        thresholdMbps,

      min_required_bitrate:
        Math.round(
          thresholdMbps * 1000000
        ),

      // =================================================
      // NEXT ACTION
      // =================================================

      next_action:
        finalQualityAccepted
          ? 'process_editorial_source'
          : 'select_next_candidate',

      retry_reason:
        finalQualityAccepted
          ? ''
          : finalReason,

      editorial_quality_parse_version:
        '2.1-quality-state-restore-safe'
    }
  }
];

const current = $input.first()?.json || {};

// ======================================================
// SELECT NEXT TRUSTED CANDIDATE
// VERSION: 2.1-current-state-only-adaptive-budget-safe
// Mode: Run Once for All Items
// ======================================================

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function clamp(value, min, max) {

  return Math.min(
    max,
    Math.max(
      min,
      value
    )
  );
}

function canonicalizeUrl(value) {

  const raw =
    clean(value);

  if (!raw) {
    return '';
  }

  try {

    const parsed =
      new URL(raw);

    const host =
      parsed.hostname
        .replace(/^www\./, '')
        .replace(/^m\./, '')
        .toLowerCase();

    if (
      host === 'youtube.com' ||
      host === 'youtu.be'
    ) {

      let videoId = '';

      if (
        host === 'youtu.be'
      ) {

        videoId =
          parsed.pathname
            .replace(/^\/+/, '')
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams.get('v') ||
          '';
      }

      if (videoId) {

        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    if (
      host === 'dailymotion.com'
    ) {

      const match =
        parsed.pathname.match(
          /\/video\/([A-Za-z0-9]+)/i
        );

      if (
        match?.[1]
      ) {

        return (
          `https://www.dailymotion.com/video/${match[1]}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return raw;
  }
}

function uniqueUrls(values) {

  return [
    ...new Set(
      (
        Array.isArray(values)
          ? values
          : []
      )
        .map(
          canonicalizeUrl
        )
        .filter(Boolean)
    )
  ];
}

function candidateUrl(candidate) {

  return canonicalizeUrl(
    candidate?.url ||
    candidate?.link ||
    candidate?.candidate_url ||
    candidate?.source_url
  );
}

// ======================================================
// REQUEST TYPE
// ======================================================

const requestedAssetType =
  clean(
    current.requested_asset_type ||
    current.asset_type ||
    'video'
  )
    .toLowerCase() === 'image'
    ? 'image'
    : 'video';

// ======================================================
// CURRENT FAILED CANDIDATE
// ======================================================

const currentUrl =
  canonicalizeUrl(
    current.current_candidate_url ||
    current.current_candidate?.url ||
    current.processing_source_url ||
    current.candidate_url ||
    current.source_url
  );

const currentTitle =
  clean(
    current.current_candidate?.title ||
    current.processing_source_title ||
    current.candidate_title ||
    current.source_title
  );

const failureReason =
  clean(
    current.quality_rejection_reason ||
    current.retry_reason ||
    current.quality_reason ||
    current.previous_failure_reason ||
    current.quality_status ||
    'candidate_failed'
  );

// ======================================================
// FAILED URLS
// ======================================================

const failedSet =
  new Set(
    uniqueUrls(
      current.failed_candidate_urls
    )
  );

if (currentUrl) {

  failedSet.add(
    currentUrl
  );
}

const failedCandidateUrls =
  [...failedSet];

// ======================================================
// USED SOURCE URLS
// ======================================================

const usedSet =
  new Set(
    uniqueUrls(
      current.used_source_urls
    )
  );

for (
  const url
  of uniqueUrls(
    current.source_urls
  )
) {

  usedSet.add(
    url
  );
}

const sourcePackages =
  Array.isArray(
    current.source_packages
  )
    ? current.source_packages
    : [];

for (
  const pkg
  of sourcePackages
) {

  const url =
    canonicalizeUrl(
      pkg?.source_url ||
      pkg?.url
    );

  if (url) {

    usedSet.add(
      url
    );
  }
}

const usedSourceUrls =
  [...usedSet];

// ======================================================
// EXCLUDED URLS
// ======================================================

const excludedSet =
  new Set(
    uniqueUrls(
      current.excluded_candidate_urls
    )
  );

for (
  const url
  of failedCandidateUrls
) {

  excludedSet.add(
    url
  );
}

for (
  const url
  of usedSourceUrls
) {

  excludedSet.add(
    url
  );
}

const excludedCandidateUrls =
  [...excludedSet];

// ======================================================
// FAILED HISTORY
// ======================================================

const failedCandidateHistory =
  Array.isArray(
    current.failed_candidate_history
  )
    ? [
        ...current.failed_candidate_history
      ]
    : [];

if (
  currentUrl &&
  !failedCandidateHistory.some(
    item =>
      canonicalizeUrl(
        item?.url
      ) ===
      currentUrl
  )
) {

  failedCandidateHistory.push({

    url:
      currentUrl,

    title:
      currentTitle,

    reason:
      failureReason,

    quality_status:
      clean(
        current.quality_status
      ),

    width:
      num(
        current.detected_width,
        0
      ),

    height:
      num(
        current.detected_height,
        0
      ),

    fps:
      num(
        current.detected_fps,
        0
      ),

    bitrate_bps:
      num(
        current.detected_bitrate_bps ??
        current.detected_bitrate,
        0
      ),

    bitrate_mbps:
      num(
        current.detected_bitrate_mbps,
        0
      ),

    codec:
      clean(
        current.detected_codec
      )
  });
}

// ======================================================
// ADAPTIVE CANDIDATE SAFETY BUDGET
//
// This is a HARD safety ceiling only.
//
// 1 desired source -> 12 attempts
// 2 desired sources -> 14
// 3 desired sources -> 17
// 4+ -> up to 20
// ======================================================

const desiredSourceCount =
  Math.max(
    1,
    num(
      current.desired_source_count,
      1
    )
  );

const automaticCandidateBudget =
  clamp(
    8 +
    (
      desiredSourceCount * 3
    ),
    12,
    20
  );

const explicitCandidateBudget =
  num(
    current.max_unique_candidate_attempts,
    0
  );

const maxUniqueCandidateAttempts =
  explicitCandidateBudget > 0
    ? clamp(
        Math.round(
          explicitCandidateBudget
        ),
        6,
        30
      )
    : automaticCandidateBudget;

// ======================================================
// UNIQUE ATTEMPT COUNT
// ======================================================

const attemptedSet =
  new Set([
    ...failedCandidateUrls,
    ...usedSourceUrls
  ]);

const processedUniqueCandidateCount =
  Math.max(
    attemptedSet.size,
    num(
      current.processed_unique_candidate_count,
      0
    )
  );

const remainingCandidateBudget =
  Math.max(
    0,
    maxUniqueCandidateAttempts -
    processedUniqueCandidateCount
  );

const candidateLimitReached =
  remainingCandidateBudget <= 0;

// ======================================================
// CANDIDATE POOL
//
// IMPORTANT:
// CURRENT STATE ONLY.
//
// No $('Assess Video Rights').first()
// No stale cross-loop lookup.
// ======================================================

const possiblePools = [
  current.results,
  current.assessed_results,
  current.trusted_candidates,
  current.video_candidates,
  current.candidate_pool
];

let rawCandidates = [];

for (
  const pool
  of possiblePools
) {

  if (
    Array.isArray(pool) &&
    pool.length > 0
  ) {

    rawCandidates =
      pool;

    break;
  }
}

// ======================================================
// TRUST FILTER
// ======================================================

function isTrustedCandidate(
  candidate
) {

  if (
    !candidate ||
    typeof candidate !==
      'object'
  ) {

    return false;
  }

  const url =
    candidateUrl(
      candidate
    );

  if (!url) {
    return false;
  }

  if (
    excludedSet.has(
      url
    )
  ) {

    return false;
  }

  const rightsStatus =
    clean(
      candidate.rights_status
    )
      .toLowerCase();

  const rightsDecision =
    clean(
      candidate.rights_decision
    )
      .toLowerCase();

  if (
    [
      'blocked',
      'block'
    ].includes(
      rightsStatus
    ) ||
    [
      'blocked',
      'block'
    ].includes(
      rightsDecision
    )
  ) {

    return false;
  }

  if (
    candidate.requires_human_review ===
      true
  ) {

    return false;
  }

  const editorialAllowed =
    (
      candidate.editorial_pipeline_allowed ===
        true ||

      candidate.editorial_use_allowed ===
        true ||

      candidate.can_download ===
        true ||

      [
        'editorial_use',
        'editorial_transformative_use',
        'auto_use',
        'allowed'
      ].includes(
        rightsDecision
      )
    );

  if (
    !editorialAllowed
  ) {

    return false;
  }

  const authenticity =
    num(
      candidate.source_authenticity_score ??
      candidate.preliminary_source_trust_score,
      0
    );

  if (
    authenticity < 75
  ) {

    return false;
  }

  return true;
}

// ======================================================
// DEDUPE CURRENT POOL
// ======================================================

const candidateMap =
  new Map();

for (
  const candidate
  of rawCandidates
) {

  const url =
    candidateUrl(
      candidate
    );

  if (!url) {
    continue;
  }

  if (
    !candidateMap.has(
      url
    )
  ) {

    candidateMap.set(
      url,
      candidate
    );
  }
}

const uniqueCandidates =
  [...candidateMap.values()];

const trustedCandidates =
  uniqueCandidates.filter(
    isTrustedCandidate
  );

// Existing ranking order is retained.

const nextCandidate =
  (
    !candidateLimitReached &&
    trustedCandidates.length > 0
  )
    ? trustedCandidates[0]
    : null;

// ======================================================
// SEARCH STATE
// ======================================================

const searchRound =
  Math.max(
    0,
    num(
      current.search_round,
      0
    )
  );

const expandedSearchRound =
  Math.max(
    0,
    num(
      current.expanded_search_round,
      searchRound
    )
  );

const maxSearchRounds =
  Math.max(
    1,
    num(
      current.max_search_rounds,
      4
    )
  );

// ======================================================
// NO NEXT CANDIDATE
// ======================================================

if (!nextCandidate) {

  return [
    {
      json: {

        ...current,

        requested_asset_type:
          requestedAssetType,

        asset_type:
          requestedAssetType,

        failed_candidate_urls:
          failedCandidateUrls,

        failed_candidate_history:
          failedCandidateHistory,

        failed_candidate_count:
          failedCandidateUrls.length,

        used_source_urls:
          usedSourceUrls,

        excluded_candidate_urls:
          excludedCandidateUrls,

        excluded_candidate_count:
          excludedCandidateUrls.length,

        processed_unique_candidate_count:
          processedUniqueCandidateCount,

        max_unique_candidate_attempts:
          maxUniqueCandidateAttempts,

        remaining_candidate_budget:
          remainingCandidateBudget,

        candidate_limit_reached:
          candidateLimitReached,

        search_round:
          searchRound,

        expanded_search_round:
          expandedSearchRound,

        max_search_rounds:
          maxSearchRounds,

        retry_available:
          false,

        trusted_candidates_total:
          uniqueCandidates.filter(
            candidate =>
              candidate &&
              typeof candidate ===
                'object'
          ).length,

        trusted_candidates_remaining:
          0,

        previous_candidate_url:
          currentUrl,

        previous_candidate_quality_status:
          clean(
            current.quality_status
          ),

        previous_candidate_rejection_reason:
          failureReason,

        retry_reason:
          candidateLimitReached
            ? 'unique_candidate_safety_budget_reached'
            : 'no_non_excluded_trusted_candidate_remaining',

        next_action:
          'expand_video_search',

        candidate_retry_version:
          '2.1-current-state-only-adaptive-budget-safe'
      }
    }
  ];
}

// ======================================================
// NEXT CANDIDATE
// ======================================================

const nextUrl =
  candidateUrl(
    nextCandidate
  );

const nextTitle =
  clean(
    nextCandidate.title ||
    nextCandidate.candidate_title ||
    nextCandidate.source_title
  );

const nextChannel =
  clean(
    nextCandidate.channel ||
    nextCandidate.channel_name ||
    nextCandidate.author ||
    nextCandidate.source_channel
  );

const nextPlatform =
  clean(
    nextCandidate.source ||
    nextCandidate.platform ||
    nextCandidate.source_platform ||
    (
      nextUrl.includes(
        'youtube.com'
      )
        ? 'youtube'
        : ''
    )
  );

const nextSourceClass =
  clean(
    nextCandidate.source_class ||
    nextCandidate.preliminary_source_class ||
    nextCandidate.candidate_source_class
  );

const nextRightsDecision =
  clean(
    nextCandidate.rights_decision ||
    'editorial_use'
  );

const nextRightsStatus =
  clean(
    nextCandidate.rights_status
  );

const nextEditorialAllowed =
  (
    nextCandidate.editorial_pipeline_allowed ===
      true ||

    nextCandidate.editorial_use_allowed ===
      true ||

    nextCandidate.can_download ===
      true ||

    [
      'editorial_use',
      'editorial_transformative_use',
      'auto_use',
      'allowed'
    ].includes(
      nextRightsDecision.toLowerCase()
    )
  );

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      // Preserve ALL collection/search/request state.
      ...current,

      requested_asset_type:
        requestedAssetType,

      asset_type:
        requestedAssetType,

      // =================================================
      // HISTORY / EXCLUSION
      // =================================================

      failed_candidate_urls:
        failedCandidateUrls,

      failed_candidate_history:
        failedCandidateHistory,

      failed_candidate_count:
        failedCandidateUrls.length,

      used_source_urls:
        usedSourceUrls,

      excluded_candidate_urls:
        excludedCandidateUrls,

      excluded_candidate_count:
        excludedCandidateUrls.length,

      // =================================================
      // ADAPTIVE SAFETY
      // =================================================

      processed_unique_candidate_count:
        processedUniqueCandidateCount,

      max_unique_candidate_attempts:
        maxUniqueCandidateAttempts,

      remaining_candidate_budget:
        remainingCandidateBudget,

      candidate_limit_reached:
        false,

      // =================================================
      // ACTIVE CANDIDATE
      // =================================================

      candidate_title:
        nextTitle,

      candidate_url:
        nextUrl,

      candidate_channel:
        nextChannel,

      candidate_source:
        nextPlatform,

      candidate_source_class:
        nextSourceClass,

      source_title:
        nextTitle,

      source_url:
        nextUrl,

      source_channel:
        nextChannel,

      source_platform:
        nextPlatform,

      source_class:
        nextSourceClass,

      processing_source_title:
        nextTitle,

      processing_source_url:
        nextUrl,

      processing_source_channel:
        nextChannel,

      processing_source_platform:
        nextPlatform,

      processing_source_class:
        nextSourceClass,

      current_candidate: {
        ...nextCandidate,

        title:
          nextTitle,

        url:
          nextUrl,

        channel:
          nextChannel,

        source:
          nextPlatform,

        source_class:
          nextSourceClass
      },

      current_candidate_url:
        nextUrl,

      // =================================================
      // RIGHTS
      // =================================================

      rights_status:
        nextRightsStatus,

      rights_decision:
        nextRightsDecision,

      risk_level:
        clean(
          nextCandidate.risk_level ||
          'medium'
        ),

      safe_for_auto_use:
        nextCandidate.safe_for_auto_use ===
          true,

      editorial_use_allowed:
        nextEditorialAllowed,

      editorial_pipeline_allowed:
        nextEditorialAllowed,

      can_download:
        nextCandidate.can_download !==
          false &&
        nextEditorialAllowed,

      requires_policy_check:
        nextCandidate.requires_policy_check ===
          true,

      requires_human_review:
        false,

      source_authenticity_score:
        num(
          nextCandidate.source_authenticity_score ??
          nextCandidate.preliminary_source_trust_score,
          0
        ),

      relevance_score:
        num(
          nextCandidate.game_match_score ??
          nextCandidate.relevance_score,
          0
        ),

      editorial_candidate_score:
        num(
          nextCandidate.editorial_candidate_score,
          0
        ),

      // =================================================
      // CLEAR PREVIOUS CANDIDATE PROCESSING STATE
      // =================================================

      quality_status:
        'pending',

      quality_accepted:
        null,

      quality_rejection_reason:
        '',

      quality_reason:
        '',

      source_file_exists:
        false,

      source_downloaded:
        false,

      source_file_path:
        '',

      detected_width:
        0,

      detected_height:
        0,

      detected_fps:
        0,

      detected_bitrate:
        0,

      detected_bitrate_bps:
        0,

      detected_bitrate_mbps:
        0,

      detected_duration:
        0,

      // =================================================
      // RETRY
      // =================================================

      retry_available:
        true,

      previous_candidate_url:
        currentUrl,

      previous_candidate_quality_status:
        clean(
          current.quality_status
        ),

      previous_candidate_rejection_reason:
        failureReason,

      retry_candidate_number:
        num(
          current.retry_candidate_number,
          0
        ) + 1,

      trusted_candidates_remaining:
        trustedCandidates.length,

      next_action:
        'retry_candidate',

      candidate_retry_version:
        '2.1-current-state-only-adaptive-budget-safe'
    }
  }
];

const input = $input.first()?.json || {};

// ======================================================
// PREPARE EXPANDED VIDEO SEARCH
// VERSION: 2.1-adaptive-progress-aware-state-safe
// Mode: Run Once for All Items
// ======================================================

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {
  return Number(
    num(value).toFixed(3)
  );
}

function clamp(value, min, max) {

  return Math.min(
    max,
    Math.max(
      min,
      value
    )
  );
}

function canonicalizeUrl(value) {

  const raw =
    clean(value);

  if (!raw) {
    return '';
  }

  try {

    const parsed =
      new URL(raw);

    const host =
      parsed.hostname
        .replace(/^www\./, '')
        .replace(/^m\./, '')
        .toLowerCase();

    if (
      host === 'youtube.com' ||
      host === 'youtu.be'
    ) {

      let videoId = '';

      if (
        host === 'youtu.be'
      ) {

        videoId =
          parsed.pathname
            .replace(/^\/+/, '')
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams.get('v') ||
          '';
      }

      if (videoId) {

        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return raw;
  }
}

function uniqueUrls(values) {

  return [
    ...new Set(
      (
        Array.isArray(values)
          ? values
          : []
      )
        .map(
          canonicalizeUrl
        )
        .filter(Boolean)
    )
  ];
}

function getClipDuration(clip) {

  const direct =
    num(
      clip?.actual_duration ??
      clip?.duration,
      0
    );

  if (direct > 0) {
    return direct;
  }

  const start =
    num(
      clip?.start_time,
      0
    );

  const end =
    num(
      clip?.end_time,
      0
    );

  return (
    end > start
      ? end - start
      : 0
  );
}

// ======================================================
// REQUEST
// ======================================================

const gameTitle =
  clean(
    input.game_title
  );

const requestedAssetType =
  clean(
    input.requested_asset_type ||
    input.asset_type ||
    'video'
  )
    .toLowerCase() === 'image'
    ? 'image'
    : 'video';

// ======================================================
// DURATION / TARGETS
// ======================================================

const targetVideoDurationSec =
  Math.max(
    1,
    num(
      input.target_video_duration_sec,
      120
    )
  );

const visualCoverageRatio =
  clamp(
    num(
      input.visual_coverage_ratio,
      0.70
    ),
    0.10,
    1
  );

const desiredFootageSeconds =
  num(
    input.desired_footage_seconds,
    targetVideoDurationSec *
    visualCoverageRatio
  );

const automaticDesiredSourceCount =
  clamp(
    Math.ceil(
      desiredFootageSeconds /
      35
    ),
    1,
    6
  );

const desiredSourceCount =
  num(
    input.desired_source_count,
    automaticDesiredSourceCount
  );

// ======================================================
// CURRENT USABLE COLLECTION
// ======================================================

const rawSourcePackages =
  Array.isArray(
    input.source_packages
  )
    ? input.source_packages
    : [];

const sourceMap =
  new Map();

let calculatedFootageSeconds =
  0;

for (
  const pkg
  of rawSourcePackages
) {

  if (
    !pkg ||
    typeof pkg !==
      'object'
  ) {
    continue;
  }

  const clips =
    Array.isArray(
      pkg.clips
    )
      ? pkg.clips.filter(
          clip =>
            clean(
              clip?.path ||
              clip?.final_path ||
              clip?.final_clip_path
            ) &&
            getClipDuration(
              clip
            ) > 0.05
        )
      : [];

  if (
    clips.length === 0
  ) {
    continue;
  }

  const sourceKey =
    canonicalizeUrl(
      pkg.source_url
    ) ||
    clean(
      pkg.source_id
    );

  if (!sourceKey) {
    continue;
  }

  if (
    sourceMap.has(
      sourceKey
    )
  ) {
    continue;
  }

  sourceMap.set(
    sourceKey,
    pkg
  );

  calculatedFootageSeconds +=
    clips.reduce(
      (sum, clip) =>
        sum +
        getClipDuration(
          clip
        ),
      0
    );
}

const actualSourceCount =
  Math.max(
    sourceMap.size,
    num(
      input.actual_source_count,
      0
    )
  );

const totalFootageSeconds =
  Math.max(
    calculatedFootageSeconds,
    num(
      input.collection_total_footage_seconds ??
      input.total_footage_seconds,
      0
    )
  );

const enoughSources =
  actualSourceCount >=
  desiredSourceCount;

const enoughFootage =
  totalFootageSeconds >=
  desiredFootageSeconds;

const collectionSatisfied =
  enoughSources &&
  enoughFootage;

// ======================================================
// URL HISTORY
// ======================================================

const failedCandidateUrls =
  uniqueUrls(
    input.failed_candidate_urls
  );

const usedSourceUrls =
  uniqueUrls([
    ...(
      Array.isArray(
        input.used_source_urls
      )
        ? input.used_source_urls
        : []
    ),

    ...(
      Array.isArray(
        input.source_urls
      )
        ? input.source_urls
        : []
    ),

    ...[
      ...sourceMap.values()
    ].map(
      pkg =>
        pkg.source_url
    )
  ]);

const excludedCandidateUrls =
  uniqueUrls([
    ...(
      Array.isArray(
        input.excluded_candidate_urls
      )
        ? input.excluded_candidate_urls
        : []
    ),

    ...failedCandidateUrls,

    ...usedSourceUrls
  ]);

const processedCandidateUrls =
  uniqueUrls([
    ...failedCandidateUrls,
    ...usedSourceUrls
  ]);

const processedUniqueCandidateCount =
  Math.max(
    processedCandidateUrls.length,
    num(
      input.processed_unique_candidate_count,
      0
    )
  );

// ======================================================
// ADAPTIVE CANDIDATE SAFETY BUDGET
// ======================================================

const automaticCandidateBudget =
  clamp(
    8 +
    (
      desiredSourceCount * 3
    ),
    12,
    20
  );

const explicitCandidateBudget =
  num(
    input.max_unique_candidate_attempts,
    0
  );

const maxUniqueCandidateAttempts =
  explicitCandidateBudget > 0
    ? clamp(
        Math.round(
          explicitCandidateBudget
        ),
        6,
        30
      )
    : automaticCandidateBudget;

const remainingCandidateBudget =
  Math.max(
    0,
    maxUniqueCandidateAttempts -
    processedUniqueCandidateCount
  );

const candidateLimitReached =
  remainingCandidateBudget <= 0;

// ======================================================
// SEARCH ROUND STATE
//
// search_round / expanded_search_round represents
// the LAST search actually performed.
//
// We increment ONLY if another search WILL run.
// ======================================================

const previousExpandedRound =
  Math.max(
    0,
    num(
      input.expanded_search_round,
      num(
        input.search_round,
        0
      )
    )
  );

// ======================================================
// ADAPTIVE ROUND LIMIT
//
// Short request still gets several expansion attempts.
//
// Bigger collection receives more potential rounds,
// but no-progress and candidate-budget guards still apply.
// ======================================================

let automaticMaxSearchRounds =
  4;

if (
  desiredSourceCount >= 2 &&
  desiredSourceCount <= 3
) {

  automaticMaxSearchRounds =
    5;

} else if (
  desiredSourceCount >= 4
) {

  automaticMaxSearchRounds =
    6;
}

const explicitMaxSearchRounds =
  num(
    input.max_search_rounds,
    0
  );

const maxSearchRounds =
  explicitMaxSearchRounds > 0
    ? clamp(
        Math.round(
          explicitMaxSearchRounds
        ),
        3,
        8
      )
    : automaticMaxSearchRounds;

// ======================================================
// PROGRESS GUARD
//
// Progress = additional usable source or footage.
//
// If THREE completed expanded searches in a row add
// nothing useful, search is considered exhausted.
//
// Finding a useful source resets the counter.
// ======================================================

const currentProgressSignature =
  [
    actualSourceCount,
    round3(
      totalFootageSeconds
    )
  ].join('|');

const previousProgressSignature =
  clean(
    input.search_progress_signature
  );

let noProgressRounds =
  Math.max(
    0,
    num(
      input.no_progress_search_rounds,
      0
    )
  );

if (
  previousExpandedRound > 0 &&
  previousProgressSignature
) {

  if (
    currentProgressSignature ===
    previousProgressSignature
  ) {

    noProgressRounds++;

  } else {

    noProgressRounds =
      0;
  }
}

const maxNoProgressRounds =
  clamp(
    num(
      input.max_no_progress_search_rounds,
      3
    ),
    2,
    5
  );

const noProgressLimitReached =
  noProgressRounds >=
  maxNoProgressRounds;

// ======================================================
// ROUND LIMIT
// ======================================================

const roundLimitReached =
  previousExpandedRound >=
  maxSearchRounds;

// ======================================================
// SHOULD EXPAND?
// ======================================================

let shouldExpandSearch =
  true;

let searchExhaustionReason =
  '';

if (
  requestedAssetType !==
    'video'
) {

  shouldExpandSearch =
    false;

  searchExhaustionReason =
    'not_a_video_request';

} else if (
  !gameTitle
) {

  shouldExpandSearch =
    false;

  searchExhaustionReason =
    'game_title_missing';

} else if (
  collectionSatisfied
) {

  shouldExpandSearch =
    false;

  searchExhaustionReason =
    'collection_target_met';

} else if (
  candidateLimitReached
) {

  shouldExpandSearch =
    false;

  searchExhaustionReason =
    'unique_candidate_safety_budget_reached';

} else if (
  noProgressLimitReached
) {

  shouldExpandSearch =
    false;

  searchExhaustionReason =
    'expanded_search_no_progress_limit_reached';

} else if (
  roundLimitReached
) {

  shouldExpandSearch =
    false;

  searchExhaustionReason =
    'expanded_search_round_limit_reached';
}

// ======================================================
// NEXT ROUND
//
// Do NOT increment when no new search will execute.
// ======================================================

const nextRound =
  shouldExpandSearch
    ? previousExpandedRound + 1
    : previousExpandedRound;

// ======================================================
// QUERY STRATEGY
//
// No game/publisher is hardcoded.
// ======================================================

const rightsHolder =
  clean(
    input.policy_target_name ||
    input.rights_holder ||
    input.rights_holder_name ||
    input.publisher_name ||
    input.developer_name
  );

const previousFailureReason =
  clean(
    input.quality_rejection_reason ||
    input.retry_reason ||
    input.previous_failure_reason ||
    input.previous_candidate_rejection_reason
  );

let expandedQuery =
  '';

if (
  shouldExpandSearch
) {

  if (
    nextRound === 1
  ) {

    expandedQuery =
      [
        gameTitle,
        rightsHolder,
        'official gameplay',
        'official trailer',
        'gameplay footage',
        '1080p'
      ]
        .filter(Boolean)
        .join(' ');

  } else if (
    nextRound === 2
  ) {

    expandedQuery =
      [
        gameTitle,
        rightsHolder,
        'publisher developer gameplay',
        'official showcase',
        'gameplay trailer',
        '1080p 60fps'
      ]
        .filter(Boolean)
        .join(' ');

  } else if (
    nextRound === 3
  ) {

    expandedQuery =
      [
        gameTitle,
        'gameplay walkthrough',
        'preview gameplay',
        'official showcase',
        'high quality gameplay',
        'reputable editorial'
      ]
        .filter(Boolean)
        .join(' ');

  } else if (
    nextRound === 4
  ) {

    expandedQuery =
      [
        gameTitle,
        rightsHolder,
        'gameplay footage',
        'review preview gameplay',
        'IGN GameSpot Digital Foundry',
        'high quality 1080p'
      ]
        .filter(Boolean)
        .join(' ');

  } else {

    expandedQuery =
      [
        gameTitle,
        'gameplay video',
        'gameplay footage',
        'trailer',
        'walkthrough',
        'review',
        'preview',
        '1080p 60fps'
      ]
        .filter(Boolean)
        .join(' ');
  }

  // ==================================================
  // QUALITY-AWARE QUERY BOOST
  // ==================================================

  if (
    [
      'bitrate_below_threshold',
      'resolution_below_720p',
      'fps_below_23'
    ].includes(
      previousFailureReason
    )
  ) {

    expandedQuery +=
      ' high quality HD high bitrate';
  }
}

// ======================================================
// RESULT BATCH SIZE
//
// Search pool broadens gradually.
//
// The number returned by search is NOT the same as
// candidate attempts.
// ======================================================

let nextMaxResults =
  0;

if (
  shouldExpandSearch
) {

  if (
    nextRound === 1
  ) {

    nextMaxResults =
      6;

  } else if (
    nextRound === 2
  ) {

    nextMaxResults =
      8;

  } else {

    nextMaxResults =
      10;
  }

  nextMaxResults =
    Math.min(
      nextMaxResults,
      Math.max(
        1,
        remainingCandidateBudget
      )
    );
}

// ======================================================
// FINAL EXHAUSTION STATE
// ======================================================

const searchExhausted =
  (
    !collectionSatisfied &&
    !shouldExpandSearch
  );

const sourcesExhausted =
  searchExhausted;

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      // Preserve ALL collection/search/retry state.
      ...input,

      requested_asset_type:
        requestedAssetType,

      asset_type:
        requestedAssetType,

      // =================================================
      // TARGET
      // =================================================

      target_video_duration_sec:
        round3(
          targetVideoDurationSec
        ),

      visual_coverage_ratio:
        round3(
          visualCoverageRatio
        ),

      desired_footage_seconds:
        round3(
          desiredFootageSeconds
        ),

      desired_source_count:
        desiredSourceCount,

      actual_source_count:
        actualSourceCount,

      total_footage_seconds:
        round3(
          totalFootageSeconds
        ),

      enough_sources:
        enoughSources,

      enough_footage:
        enoughFootage,

      collection_ready:
        collectionSatisfied,

      needs_more_sources:
        !collectionSatisfied,

      // =================================================
      // URL HISTORY
      // =================================================

      failed_candidate_urls:
        failedCandidateUrls,

      used_source_urls:
        usedSourceUrls,

      excluded_candidate_urls:
        excludedCandidateUrls,

      processed_candidate_urls:
        processedCandidateUrls,

      processed_unique_candidate_count:
        processedUniqueCandidateCount,

      // =================================================
      // CANDIDATE SAFETY
      // =================================================

      max_unique_candidate_attempts:
        maxUniqueCandidateAttempts,

      remaining_candidate_budget:
        remainingCandidateBudget,

      candidate_limit_reached:
        candidateLimitReached,

      // =================================================
      // SEARCH PROGRESS
      // =================================================

      previous_search_round:
        previousExpandedRound,

      search_round:
        nextRound,

      expanded_search_round:
        nextRound,

      max_search_rounds:
        maxSearchRounds,

      search_progress_signature:
        currentProgressSignature,

      no_progress_search_rounds:
        noProgressRounds,

      max_no_progress_search_rounds:
        maxNoProgressRounds,

      no_progress_limit_reached:
        noProgressLimitReached,

      round_limit_reached:
        roundLimitReached,

      // =================================================
      // SEARCH ACTION
      // =================================================

      search_query:
        shouldExpandSearch
          ? expandedQuery
          : clean(
              input.search_query
            ),

      actual_serper_query:
        shouldExpandSearch
          ? expandedQuery
          : '',

      max_results:
        nextMaxResults,

      expanded_search:
        true,

      should_expand_search:
        shouldExpandSearch,

      search_exhausted:
        searchExhausted,

      sources_exhausted:
        sourcesExhausted,

      expanded_search_exhausted:
        searchExhausted,

      search_exhaustion_reason:
        searchExhaustionReason,

      // =================================================
      // CURRENT FAILED CANDIDATE
      // =================================================

      previous_candidate_url:
        canonicalizeUrl(
          input.current_candidate_url ||
          input.current_candidate?.url ||
          input.candidate_url ||
          input.source_url ||
          input.previous_candidate_url
        ),

      previous_failure_reason:
        previousFailureReason,

      // =================================================
      // CLEAR ACTIVE CANDIDATE ONLY
      // =================================================

      current_candidate:
        null,

      current_candidate_url:
        '',

      candidate_title:
        '',

      candidate_url:
        '',

      candidate_channel:
        '',

      candidate_source:
        '',

      candidate_source_class:
        '',

      source_title:
        '',

      source_url:
        '',

      source_channel:
        '',

      source_platform:
        '',

      source_class:
        '',

      processing_source_title:
        '',

      processing_source_url:
        '',

      processing_source_channel:
        '',

      processing_source_platform:
        '',

      processing_source_class:
        '',

      source_package:
        null,

      // NEVER clear:
      // source_packages
      // failed_candidate_urls
      // used_source_urls
      // excluded_candidate_urls

      next_collection_action:
        collectionSatisfied
          ? 'collection_ready'
          : (
              shouldExpandSearch
                ? 'search_expanded_video_sources'
                : 'source_search_exhausted'
            ),

      next_action:
        collectionSatisfied
          ? 'collection_ready'
          : (
              shouldExpandSearch
                ? 'search_expanded_video_sources'
                : 'source_search_exhausted'
            ),

      expanded_search_version:
        '2.1-adaptive-progress-aware-state-safe'
    }
  }
];

const raw = $input.first().json || {};

// ======================================================
// GET EXACT CURRENT EXPANDED-SEARCH CONTEXT
// ======================================================

let context = {};

try {

  context =
    $('Route Expanded Search Limit').item.json || {};

} catch (error) {

  throw new Error(
    'Normalize Expanded Video Results: current expanded-search ' +
    'context could not be resolved from Route Expanded Search Limit.'
  );
}

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function toNumber(value, fallback = 0) {

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function canonicalizeUrl(value) {

  const rawUrl = clean(value);

  if (!rawUrl) {
    return '';
  }

  // --------------------------------------------------
  // YouTube
  // --------------------------------------------------

  const yt =
    rawUrl.match(
      /(?:youtube\.com\/watch\?(?:[^#\s]*&)?v=|youtu\.be\/)([A-Za-z0-9_-]{6,})/i
    );

  if (yt?.[1]) {

    return (
      `https://www.youtube.com/watch?v=${yt[1]}`
    );
  }

  // --------------------------------------------------
  // Dailymotion
  // --------------------------------------------------

  const dm =
    rawUrl.match(
      /https?:\/\/(?:www\.)?dailymotion\.com\/video\/([A-Za-z0-9]+)/i
    );

  if (dm?.[1]) {

    return (
      `https://www.dailymotion.com/video/${dm[1]}`
    );
  }

  // --------------------------------------------------
  // Generic URL
  // --------------------------------------------------

  const http =
    rawUrl.match(
      /https?:\/\/[^\s<>"']+/i
    );

  if (!http?.[0]) {
    return '';
  }

  try {

    const parsed =
      new URL(http[0]);

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return http[0];
  }
}

// ======================================================
// VERIFY SERPER QUERY
// ======================================================

const actualSearchQuery =
  clean(
    raw.searchParameters?.q ||
    raw.search_parameters?.q ||
    ''
  );

const expectedSearchQuery =
  clean(
    context.search_query
  );

if (
  actualSearchQuery &&
  expectedSearchQuery &&
  actualSearchQuery !== expectedSearchQuery
) {

  throw new Error(
    'Normalize Expanded Video Results: search context mismatch.\n' +
    `Expected: ${expectedSearchQuery}\n` +
    `Received: ${actualSearchQuery}`
  );
}

// ======================================================
// RAW SERPER RESULTS
// ======================================================

let rawVideos = [];

if (Array.isArray(raw.videos)) {

  rawVideos = raw.videos;

} else if (Array.isArray(raw.results)) {

  rawVideos = raw.results;

} else if (Array.isArray(raw.videoResults)) {

  rawVideos = raw.videoResults;

} else if (Array.isArray(raw.items)) {

  rawVideos = raw.items;
}

// ======================================================
// NORMALIZE RESULTS
// ======================================================

const normalizedResults =
  rawVideos.map((video, index) => {

    const originalUrl =
      clean(
        video.link ||
        video.url
      );

    const url =
      canonicalizeUrl(
        originalUrl
      );

    let youtubeVideoId = '';

    if (url) {

      const match =
        url.match(
          /youtube\.com\/watch\?v=([A-Za-z0-9_-]+)/i
        );

      youtubeVideoId =
        match?.[1] || '';
    }

    return {

      asset_type:
        'video',

      title:
        clean(
          video.title ||
          video.name
        ),

      url,

      original_url:
        originalUrl,

      youtube_video_id:
        youtubeVideoId,

      preview_image_url:
        clean(
          video.imageUrl ||
          video.thumbnail ||
          video.thumbnailUrl ||
          video.preview_image_url
        ),

      preview_video_url:
        clean(
          video.videoUrl ||
          video.previewVideoUrl ||
          video.preview_video_url
        ),

      source:
        clean(
          video.source ||
          video.platform
        ),

      channel:
        clean(
          video.channel ||
          video.channelName ||
          video.author
        ),

      duration:
        clean(
          video.duration
        ),

      date:
        clean(
          video.date ||
          video.publishedDate ||
          video.published_at
        ),

      snippet:
        clean(
          video.snippet ||
          video.description
        ),

      original_position:
        toNumber(
          video.position ||
          video.rank ||
          index + 1,
          index + 1
        )
    };
  });

// ======================================================
// REMOVE DUPLICATES
// ======================================================

const seen =
  new Set();

const uniqueResults =
  normalizedResults.filter(result => {

    if (!result.url) {
      return false;
    }

    if (seen.has(result.url)) {
      return false;
    }

    seen.add(result.url);

    return true;
  });

// ======================================================
// PRESERVE FAILED URL STATE
// ======================================================

const failedCandidateUrls =
  Array.isArray(
    context.failed_candidate_urls
  )
    ? [
        ...new Set(
          context.failed_candidate_urls
            .map(canonicalizeUrl)
            .filter(Boolean)
        )
      ]
    : [];

// ======================================================
// PRESERVE USED SOURCE STATE
// ======================================================

const usedSourceUrls =
  Array.isArray(
    context.used_source_urls
  )
    ? [
        ...new Set(
          context.used_source_urls
            .map(canonicalizeUrl)
            .filter(Boolean)
        )
      ]
    : [];

// ======================================================
// PRESERVE GLOBAL EXCLUSION STATE
// ======================================================

const excludedSet =
  new Set();

if (
  Array.isArray(
    context.excluded_candidate_urls
  )
) {

  for (
    const url of
    context.excluded_candidate_urls
  ) {

    const normalized =
      canonicalizeUrl(url);

    if (normalized) {
      excludedSet.add(normalized);
    }
  }
}

for (const url of failedCandidateUrls) {
  excludedSet.add(url);
}

for (const url of usedSourceUrls) {
  excludedSet.add(url);
}

const excludedCandidateUrls =
  [...excludedSet];

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      // Keep ALL collection/search state
      ...context,

      game_title:
        clean(context.game_title),

      asset_type:
        'video',

      search_query:
        actualSearchQuery ||
        expectedSearchQuery,

      max_results:
        toNumber(
          raw.searchParameters?.num ||
          raw.search_parameters?.num ||
          context.max_results,
          uniqueResults.length
        ),

      aspect_ratio:
        clean(
          context.aspect_ratio
        ) || '16:9',

      source_preference:
        clean(
          context.source_preference
        ) || 'official',

      // ------------------------------------------
      // SEARCH STATE
      // ------------------------------------------

      previous_search_round:
        toNumber(
          context.previous_search_round,
          0
        ),

      search_round:
        toNumber(
          context.search_round,
          1
        ),

      max_search_rounds:
        toNumber(
          context.max_search_rounds,
          3
        ),

      search_exhausted:
        context.search_exhausted === true,

      should_expand_search:
        context.should_expand_search === true,

      expanded_search:
        true,

      expanded_search_version:
        clean(
          context.expanded_search_version
        ),

      // ------------------------------------------
      // COLLECTION STATE
      // ------------------------------------------

      source_packages:
        Array.isArray(context.source_packages)
          ? context.source_packages
          : [],

      source_package_count:
        toNumber(
          context.source_package_count,
          0
        ),

      desired_source_count:
        toNumber(
          context.desired_source_count,
          3
        ),

      used_source_urls:
        usedSourceUrls,

      collection_total_footage_seconds:
        toNumber(
          context.collection_total_footage_seconds,
          0
        ),

      needs_more_sources:
        context.needs_more_sources === true,

      collection_ready:
        context.collection_ready === true,

      // ------------------------------------------
      // FAILED STATE
      // ------------------------------------------

      failed_candidate_urls:
        failedCandidateUrls,

      failed_candidate_history:
        Array.isArray(
          context.failed_candidate_history
        )
          ? context.failed_candidate_history
          : [],

      failed_candidate_count:
        failedCandidateUrls.length,

      // ------------------------------------------
      // GLOBAL EXCLUSIONS
      // ------------------------------------------

      excluded_candidate_urls:
        excludedCandidateUrls,

      excluded_candidate_count:
        excludedCandidateUrls.length,

      // ------------------------------------------

      actual_serper_query:
        actualSearchQuery,

      context_source:
        'expanded_search',

      result_count:
        uniqueResults.length,

      results:
        uniqueResults,

      normalize_video_version:
        'expanded-3.2-collection-state-safe'
    }
  }
];

const input = $input.first().json || {};

function toNumber(value, fallback) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function clampInt(value, min, max) {
  return Math.round(
    clamp(
      toNumber(value, min),
      min,
      max
    )
  );
}

// ======================================================
// FINAL VIDEO PLAN
// ======================================================

const targetVideoDuration =
  clamp(
    toNumber(
      input.target_video_duration_sec ??
      input.final_video_duration_sec ??
      input.final_video_duration,
      120
    ),
    15,
    1800
  );

const visualCoverageRatio =
  clamp(
    toNumber(
      input.visual_coverage_ratio,
      0.70
    ),
    0.35,
    1.00
  );

const avgClipDuration =
  clamp(
    toNumber(
      input.avg_clip_duration_sec,
      4.5
    ),
    3,
    7
  );

const minClipDuration = 1.8;
const maxClipDuration = 6;

// ======================================================
// FOOTAGE BUDGET
// ======================================================

const desiredFootageSeconds =
  Math.round(
    targetVideoDuration *
    visualCoverageRatio *
    10
  ) / 10;

const totalClipTarget =
  Math.max(
    1,
    Math.ceil(
      desiredFootageSeconds /
      avgClipDuration
    )
  );

// ======================================================
// MULTI-SOURCE PLAN
// ======================================================

// IMPORTANT:
// Default is 3, not 1.
const desiredSourceCount =
  clampInt(
    input.desired_source_count ?? 3,
    1,
    6
  );

const rawClipsPerSource =
  Math.max(
    1,
    Math.ceil(
      totalClipTarget /
      desiredSourceCount
    )
  );

// ======================================================
// CURRENT SOURCE CAPACITY
// ======================================================

const sourceDuration =
  Math.max(
    0,
    toNumber(
      input.detected_duration,
      0
    )
  );

const edgeMarginSeconds = 3;

const usableSourceSeconds =
  Math.max(
    0,
    sourceDuration -
    edgeMarginSeconds * 2
  );

const maxReasonableClipsFromSource =
  Math.max(
    1,
    Math.floor(
      usableSourceSeconds /
      (avgClipDuration + 0.25)
    )
  );

const clipTargetPerSource =
  Math.max(
    1,
    Math.min(
      rawClipsPerSource + 5,
      maxReasonableClipsFromSource
    )
  );

// Roughly 3 candidate scenes for every clip we need.
const candidateSceneTarget =
  Math.min(
    30,
    Math.max(
      12,
      clipTargetPerSource * 3
    )
  );

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {
      ...input,

      target_video_duration_sec:
        targetVideoDuration,

      visual_coverage_ratio:
        visualCoverageRatio,

      desired_footage_seconds:
        desiredFootageSeconds,

      avg_clip_duration_sec:
        avgClipDuration,

      min_clip_duration_sec:
        minClipDuration,

      max_clip_duration_sec:
        maxClipDuration,

      total_clip_target:
        totalClipTarget,

      desired_source_count:
        desiredSourceCount,

      clip_target_per_source:
        clipTargetPerSource,

      candidate_scene_target:
        candidateSceneTarget,

      source_duration_sec:
        sourceDuration,

      source_usable_seconds:
        usableSourceSeconds,

      scene_threshold:
        0.28,

      scene_min_gap_sec:
        1.75,

      scene_thumbnail_offset_sec:
        0.45,

      edge_margin_seconds:
        edgeMarginSeconds,

      ready_for_scene_detection:
        true,

      clip_plan_version:
        '1.1-adaptive-multi-source'
    }
  }
];

const input = $input.first().json || {};

// ======================================================
// FIND FINAL AI MESSAGE
// ======================================================

const outputs =
  Array.isArray(input.output)
    ? input.output
    : [];

let rawText = '';

for (const output of outputs) {

  if (
    output.type !== 'message' ||
    !Array.isArray(output.content)
  ) {
    continue;
  }

  for (const content of output.content) {

    if (
      content.type === 'output_text' &&
      typeof content.text === 'string'
    ) {

      rawText =
        content.text.trim();

      break;
    }
  }

  if (rawText) {
    break;
  }
}

// ======================================================
// VALIDATE AI OUTPUT
// ======================================================

if (!rawText) {

  throw new Error(
    'AI scene selection output text was not found.'
  );
}

// ======================================================
// PARSE STRUCTURED JSON
// ======================================================

let selection = {};

try {

  selection =
    JSON.parse(rawText);

} catch {

  throw new Error(
    `AI scene selection returned invalid JSON:\n${rawText}`
  );
}

// ======================================================
// NORMALIZE SELECTED IDS
// ======================================================

const selectedIds =
  Array.isArray(
    selection.selected_scene_ids
  )
    ? selection.selected_scene_ids
        .map(id =>
          String(id)
            .trim()
            .padStart(2, '0')
        )
        .filter(id =>
          /^[0-9]{2}$/.test(id)
        )
    : [];

const uniqueIds =
  [...new Set(selectedIds)];

// ======================================================
// VALIDATE SCENE COUNT
// ======================================================

if (!uniqueIds.length) {

  throw new Error(
    'AI did not return any valid scene IDs.'
  );
}

// ======================================================
// GET THE CORRECT LOOP ITEM
// ======================================================

let plan = {};

try {

  plan =
    $('Plan Clip Budget')
      .item
      .json || {};

} catch (error) {

  throw new Error(
    'Could not resolve the matching Plan Clip Budget item for this AI selection.'
  );
}

// ======================================================
// SOURCE / SCENE PATHS
// ======================================================

const slug =
  String(
    plan.file_slug || ''
  ).trim();

if (!slug) {

  throw new Error(
    'file_slug is missing from the matching Plan Clip Budget item.'
  );
}

const sceneDirectory =
  `/home/node/.n8n-files/editorial-scenes/${slug}`;

const manifestPath =
  `${sceneDirectory}/manifest.csv`;

// ======================================================
// OUTPUT
// Preserve the entire current source/collection state.
// ======================================================

return [
  {
    json: {

      ...plan,
      scene_annotations: Array.isArray(selection.scene_annotations) ? selection.scene_annotations.filter(a=>uniqueIds.includes(String(a.scene_id).padStart(2,"0"))) : [],

      scene_directory:
        sceneDirectory,

      scene_manifest_path:
        manifestPath,

      selected_scene_ids:
        uniqueIds,

      selected_scene_count:
        uniqueIds.length,

      selection_summary:
        String(
          selection.selection_summary ||
          ''
        ).trim(),

      min_clip_duration_sec:
        Number(
          plan.min_clip_duration_sec ??
          3
        ),

      avg_clip_duration_sec:
        Number(
          plan.avg_clip_duration_sec ??
          4.5
        ),

      max_clip_duration_sec:
        Number(
          plan.max_clip_duration_sec ??
          7
        ),

      output_directory:
        plan.output_directory ||
        '/home/node/.n8n-files/editorial-clips',

      mute_original_audio:
        plan.mute_original_audio !== false,

      ai_scene_selection_ready:
        true,

      ai_scene_selection_version:
        '1.1-loop-safe'
    }
  }
];

parameters.command:
=SRC="{{$json.source_file_path}}"
MANIFEST="{{$json.scene_manifest_path}}"

OUT_BASE="{{$json.output_directory}}"
SLUG="{{$json.file_slug}}"

SELECTED_IDS="{{$json.selected_scene_ids.join(',')}}"

MIN_DUR="{{$json.min_clip_duration_sec}}"
AVG_DUR="{{$json.avg_clip_duration_sec}}"
MAX_DUR="{{$json.max_clip_duration_sec}}"

MUTE_AUDIO="{{$json.mute_original_audio ? '1' : '0'}}"

OUT_DIR="$OUT_BASE/$SLUG-selected"
PLAN_FILE="$OUT_DIR/extract-plan.csv"

# =====================================================
# VALIDATE
# =====================================================

if [ ! -f "$SRC" ]; then
  echo "EXTRACT_SELECTED_STATUS=source_missing"
  exit 0
fi

if [ ! -f "$MANIFEST" ]; then
  echo "EXTRACT_SELECTED_STATUS=manifest_missing"
  exit 0
fi

# Preserve existing files; source folders are execution-specific.
mkdir -p "$OUT_DIR"

# =====================================================
# SOURCE DURATION
# =====================================================

SOURCE_DURATION=$(ffprobe \
  -v error \
  -show_entries format=duration \
  -of default=noprint_wrappers=1:nokey=1 \
  "$SRC")

export SRC
export MANIFEST
export PLAN_FILE
export SELECTED_IDS
export MIN_DUR
export AVG_DUR
export MAX_DUR
export SOURCE_DURATION

# =====================================================
# MAP AI IDS TO REAL TIMESTAMPS, THEN VALIDATE EACH
# CANDIDATE WINDOW FOR INTERNAL HARD CUTS (shot-boundary-
# aware extraction: never blindly extract a fixed-duration
# window that silently crosses unrelated cuts).
# =====================================================

node <<'NODE'

const fs = require('fs');
const { spawnSync } = require('child_process');

function num(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

// ---- shot-boundary-aware stable-segment computation ----
// (developed and unit-tested standalone in phase1-lib.cjs before being transplanted here verbatim)
function computeStableSegment({ cuts, anchorTime, requestedStart, requestedDuration, minDuration, maxDuration, windowStart, windowEnd }) {
  const sorted = [...new Set(cuts)].filter(c => c > windowStart + 1e-6 && c < windowEnd - 1e-6).sort((a, b) => a - b);
  let shotStart = windowStart;
  let shotEnd = windowEnd;
  for (const c of sorted) {
    if (c <= anchorTime + 1e-9) shotStart = c;
    else { shotEnd = c; break; }
  }
  const requestedEnd = requestedStart + requestedDuration;
  const start = Math.max(shotStart, requestedStart);
  let end = Math.min(shotEnd, requestedEnd);
  end = Math.min(end, start + maxDuration);
  const duration = Math.max(0, end - start);
  const internalCutsInRequestedWindow = sorted.filter(c => c > requestedStart + 1e-9 && c < requestedEnd - 1e-9).length;
  return { ok: duration + 1e-6 >= minDuration, start, end, duration, internalCutsInRequestedWindow };
}

// IMPORTANT: `-v error` must NOT be used here -- it silently suppresses showinfo's info-level
// pts_time log lines, which would make this detector report zero cuts every time. Verified live
// against a real cached source file before shipping this. pts_time after `-ss` (input seeking) is
// relative to the seek point, not absolute -- also verified live -- so windowStart is added back.
function detectCutsInWindow(source, windowStart, windowEnd, threshold) {
  const start = Math.max(0, windowStart);
  const dur = Math.max(0.2, windowEnd - start);
  const result = spawnSync('ffmpeg', [
    '-hide_banner', '-ss', String(start), '-i', source, '-t', String(dur),
    '-an', '-vf', `select='gt(scene,${threshold})',showinfo`, '-f', 'null', '-'
  ], { encoding: 'utf8', maxBuffer: 20 * 1024 * 1024 });
  const stderr = result.stderr || '';
  const cuts = [];
  const re = /pts_time:([0-9.]+)/g;
  let m;
  while ((m = re.exec(stderr))) {
    const relTime = Number(m[1]);
    if (Number.isFinite(relTime)) cuts.push(start + relTime);
  }
  return cuts;
}

const source = process.env.SRC;
const manifestPath = process.env.MANIFEST;
const planPath = process.env.PLAN_FILE;

const selectedIds =
  String(process.env.SELECTED_IDS || '')
    .split(',')
    .map(value => value.trim().padStart(2, '0'))
    .filter(Boolean);

const minDuration = Math.max(1, num(process.env.MIN_DUR, 3));
const maxDuration = Math.max(minDuration, num(process.env.MAX_DUR, 7));
const avgDuration = clamp(num(process.env.AVG_DUR, 4.5), minDuration, maxDuration);
const sourceDuration = Math.max(0, num(process.env.SOURCE_DURATION, 0));

const SCENE_CUT_THRESHOLD = 0.28; // same threshold as initial candidate-scene detection
const WINDOW_PAD_SECONDS = 1.5;   // how far past the requested window to look for a bounding cut

// ---- READ MANIFEST ----
const manifestText = fs.readFileSync(manifestPath, 'utf8');
const lines = manifestText.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
const sceneMap = new Map();
for (const line of lines.slice(1)) {
  const parts = line.split(',');
  if (parts.length < 2) continue;
  const id = String(parts[0]).trim().padStart(2, '0');
  const timestamp = Number(parts[1]);
  if (!Number.isFinite(timestamp)) continue;
  sceneMap.set(id, timestamp);
}

// ---- BUILD + VALIDATE EXTRACTION PLAN ----
const plan = [];
let discardedUnstable = 0;

for (let i = 0; i < selectedIds.length; i++) {
  const id = selectedIds[i];
  if (!sceneMap.has(id)) continue;

  const anchorTime = sceneMap.get(id);
  const requestedStart = Math.max(0, anchorTime - 0.20);
  let requestedDuration = avgDuration;

  if (sourceDuration > 0 && requestedStart + requestedDuration > sourceDuration - 0.10) {
    const available = sourceDuration - requestedStart - 0.10;
    if (available >= minDuration) {
      requestedDuration = Math.min(maxDuration, available);
    } else {
      requestedDuration = Math.min(minDuration, sourceDuration);
    }
  }

  const windowStart = Math.max(0, requestedStart - WINDOW_PAD_SECONDS);
  const windowEnd = sourceDuration > 0
    ? Math.min(sourceDuration - 0.05, requestedStart + maxDuration + WINDOW_PAD_SECONDS)
    : requestedStart + maxDuration + WINDOW_PAD_SECONDS;

  const cuts = detectCutsInWindow(source, windowStart, windowEnd, SCENE_CUT_THRESHOLD);
  const seg = computeStableSegment({
    cuts, anchorTime, requestedStart, requestedDuration,
    minDuration, maxDuration, windowStart, windowEnd,
  });

  if (!seg.ok) {
    discardedUnstable++;
    plan.push({
      order: i + 1, id, anchorTime,
      start: seg.start, duration: seg.duration,
      unstable: 1, internalCuts: seg.internalCutsInRequestedWindow,
    });
    continue;
  }

  plan.push({
    order: i + 1, id, anchorTime,
    start: seg.start, duration: seg.duration,
    unstable: 0, internalCuts: seg.internalCutsInRequestedWindow,
  });
}

// ---- WRITE PLAN ----
const csv = ['order,scene_id,anchor_time,start_time,duration,unstable,internal_cuts_trimmed'];
for (const item of plan) {
  csv.push([
    item.order, item.id, item.anchorTime.toFixed(3),
    item.start.toFixed(3), item.duration.toFixed(3),
    item.unstable, item.internalCuts,
  ].join(','));
}
fs.writeFileSync(planPath, csv.join('\n') + '\n');

console.log('SHOT_BOUNDARY_VALIDATION_VERSION=1.0-internal-cut-aware');
console.log('DISCARDED_UNSTABLE_COUNT=' + discardedUnstable);

NODE

# =====================================================
# REQUESTED COUNT
# =====================================================

REQUESTED_COUNT=$(echo "$SELECTED_IDS" |
  tr ',' '\n' |
  sed '/^[[:space:]]*$/d' |
  wc -l |
  tr -d ' ')

# =====================================================
# EXTRACT SELECTED (STABLE) CLIPS
# Candidates flagged unstable by the shot-boundary check above are
# skipped entirely rather than extracted with a hidden internal cut.
# =====================================================

while IFS=',' read -r ORDER SCENE_ID ANCHOR START DURATION UNSTABLE CUTS_TRIMMED
do

  # Skip CSV header
  if [ "$ORDER" = "order" ]; then
    continue
  fi

  [ -z "$ORDER" ] && continue
  [ -z "$SCENE_ID" ] && continue
  [ -z "$START" ] && continue
  [ -z "$DURATION" ] && continue

  NUM=$(printf "%02d" "$ORDER")

  if [ "$UNSTABLE" = "1" ]; then
    echo "CLIP_${NUM}_SCENE_ID=$SCENE_ID"
    echo "CLIP_${NUM}_UNSTABLE=1"
    echo "CLIP_${NUM}_DISCARD_REASON=no_stable_continuous_segment_at_least_${MIN_DUR}s"
    continue
  fi

  OUTPUT_FILE="$OUT_DIR/${SLUG}-scene-${SCENE_ID}-clip-${NUM}.mp4"

  # ===================================================
  # MUTED VIDEO
  # ===================================================

  if [ "$MUTE_AUDIO" = "1" ]; then

    ffmpeg \
      -nostdin \
      -hide_banner \
      -loglevel error \
      -y \
      -ss "$START" \
      -i "$SRC" \
      -t "$DURATION" \
      -map 0:v:0 \
      -an \
      -c:v libx264 \
      -preset medium \
      -crf 18 \
      -pix_fmt yuv420p \
      -movflags +faststart \
      "$OUTPUT_FILE"

  # ===================================================
  # VIDEO WITH AUDIO
  # ===================================================

  else

    ffmpeg \
      -nostdin \
      -hide_banner \
      -loglevel error \
      -y \
      -ss "$START" \
      -i "$SRC" \
      -t "$DURATION" \
      -map 0:v:0 \
      -map 0:a? \
      -c:v libx264 \
      -preset medium \
      -crf 18 \
      -c:a aac \
      -b:a 192k \
      -pix_fmt yuv420p \
      -movflags +faststart \
      "$OUTPUT_FILE"

  fi

  if [ -f "$OUTPUT_FILE" ]; then

    echo "CLIP_${NUM}_SCENE_ID=$SCENE_ID"
    echo "CLIP_${NUM}_ANCHOR=$ANCHOR"
    echo "CLIP_${NUM}_START=$START"
    echo "CLIP_${NUM}_DURATION=$DURATION"
    echo "CLIP_${NUM}_PATH=$OUTPUT_FILE"
    echo "CLIP_${NUM}_INTERNAL_CUTS_TRIMMED=$CUTS_TRIMMED"

  else

    echo "CLIP_${NUM}_FAILED=1"

  fi

done < "$PLAN_FILE"

# =====================================================
# COUNT FINAL CLIPS
# =====================================================

EXTRACTED_COUNT=$(find "$OUT_DIR" \
  -maxdepth 1 \
  -type f \
  -name '*.mp4' \
  | wc -l \
  | tr -d ' ')

# =====================================================
# FINAL STATUS
#
# A candidate deliberately discarded for failing shot-boundary
# validation is NOT a failure -- it is a quality decision. Success
# now means "at least one clean stable clip was produced", not
# "every requested candidate produced a clip".
# =====================================================

if [ "$EXTRACTED_COUNT" -gt 0 ]; then

  STATUS="success"

else

  STATUS="failed"

fi

echo "EXTRACT_SELECTED_STATUS=$STATUS"
echo "REQUESTED_CLIP_COUNT=$REQUESTED_COUNT"
echo "EXTRACTED_CLIP_COUNT=$EXTRACTED_COUNT"

echo "SELECTED_SCENE_IDS=$SELECTED_IDS"

echo "SOURCE_PATH=$SRC"
echo "EXTRACT_PLAN=$PLAN_FILE"
echo "CLIP_OUTPUT_DIRECTORY=$OUT_DIR"

echo "EXTRACT_SELECTED_VERSION=2.0-shot-boundary-aware"

parameters.jsCode:
const commandResult =
  $input.first()?.json || {};

// ======================================================
// PARSE EDITORIAL SOURCE PACKAGE
// VERSION: 2.0-authoritative-target-state-safe
// Mode: Run Once for All Items
// ======================================================

// ======================================================
// CONTEXT RECOVERY
// ======================================================

let selectionContext = {};

try {

  selectionContext =
    $('Parse AI Scene Selection')
      .item
      .json || {};

} catch {

  try {

    const items =
      $('Parse AI Scene Selection')
        .all();

    selectionContext =
      items.length
        ? items[
            items.length - 1
          ].json || {}
        : {};

  } catch {

    selectionContext = {};
  }
}


let planContext = {};

try {

  planContext =
    $('Plan Clip Budget')
      .item
      .json || {};

} catch {

  try {

    const items =
      $('Plan Clip Budget')
        .all();

    planContext =
      items.length
        ? items[
            items.length - 1
          ].json || {}
        : {};

  } catch {

    planContext = {};
  }
}


// ======================================================
// ROOT REQUEST CONTEXT
//
// IMPORTANT:
//
// Prepare Asset Search is the authoritative source
// for immutable request/target fields.
//
// We intentionally do NOT trust old defaults that may
// exist in Plan Clip Budget or other downstream nodes.
// ======================================================

let requestContext = {};

try {

  requestContext =
    $('Prepare Asset Search')
      .first()
      .json || {};

} catch {

  requestContext = {};
}


// ======================================================
// ACTIVE PIPELINE STATE
//
// Plan = broader pipeline state.
// Selection = newest scene-selection state.
// ======================================================

const state = {

  ...planContext,
  ...selectionContext
};


// ======================================================
// HELPERS
// ======================================================

function clean(value) {

  return String(
    value ?? ''
  ).trim();
}


function numberValue(
  value,
  fallback = 0
) {

  const n =
    Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}


function round3(value) {

  return Number(
    numberValue(
      value,
      0
    ).toFixed(3)
  );
}


function clamp(
  value,
  min,
  max
) {

  return Math.min(
    max,
    Math.max(
      min,
      value
    )
  );
}


function readValue(
  stdout,
  key
) {

  const prefix =
    `${key}=`;

  const line =
    String(
      stdout || ''
    )
      .split(/\r?\n/)
      .find(
        line =>
          line.startsWith(
            prefix
          )
      );

  if (!line) {

    return '';
  }

  return line
    .slice(
      prefix.length
    )
    .trim();
}


function canonicalizeUrl(
  value
) {

  const raw =
    clean(value);

  if (!raw) {

    return '';
  }

  try {

    const parsed =
      new URL(raw);

    const host =
      parsed.hostname
        .replace(
          /^www\./i,
          ''
        )
        .replace(
          /^m\./i,
          ''
        )
        .toLowerCase();

    // --------------------------------------------------
    // YOUTUBE
    // --------------------------------------------------

    if (
      host ===
        'youtube.com' ||
      host ===
        'youtu.be'
    ) {

      let videoId = '';

      if (
        host ===
        'youtu.be'
      ) {

        videoId =
          parsed.pathname
            .replace(
              /^\/+/,
              ''
            )
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams
            .get('v') ||
          '';
      }

      if (videoId) {

        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    // --------------------------------------------------
    // DAILYMOTION
    // --------------------------------------------------

    if (
      host ===
      'dailymotion.com'
    ) {

      const match =
        parsed.pathname.match(
          /\/video\/([A-Za-z0-9]+)/i
        );

      if (
        match?.[1]
      ) {

        return (
          `https://www.dailymotion.com/video/${match[1]}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return raw;
  }
}


function uniqueUrls(
  values
) {

  const result =
    new Set();

  for (
    const value
    of (
      Array.isArray(values)
        ? values
        : []
    )
  ) {

    const url =
      canonicalizeUrl(
        value
      );

    if (url) {

      result.add(
        url
      );
    }
  }

  return [
    ...result
  ];
}


// ======================================================
// AUTHORITATIVE REQUEST TYPE
// ======================================================

const requestedAssetTypeRaw =
  clean(
    requestContext
      .requested_asset_type ||
    requestContext
      .asset_type ||
    state
      .requested_asset_type ||
    state
      .asset_type ||
    'video'
  )
    .toLowerCase();


const requestedAssetType =
  requestedAssetTypeRaw ===
    'image'
    ? 'image'
    : 'video';


// ======================================================
// AUTHORITATIVE TARGET STATE
//
// These values come from Prepare Asset Search.
//
// If that node is unavailable, we derive safe adaptive
// values instead of falling back to old fixed 120/84/3.
// ======================================================

const targetVideoDurationSec =
  Math.max(
    1,
    numberValue(
      requestContext
        .target_video_duration_sec ??
      state
        .target_video_duration_sec,
      120
    )
  );


const visualCoverageRatio =
  clamp(
    numberValue(
      requestContext
        .visual_coverage_ratio ??
      state
        .visual_coverage_ratio,
      0.7
    ),
    0.1,
    1
  );


// ------------------------------------------------------
// DESIRED FOOTAGE
// ------------------------------------------------------

const requestDesiredFootage =
  numberValue(
    requestContext
      .desired_footage_seconds,
    0
  );


const desiredFootageSeconds =
  requestDesiredFootage > 0
    ? round3(
        requestDesiredFootage
      )
    : round3(
        targetVideoDurationSec *
        visualCoverageRatio
      );


// ------------------------------------------------------
// DESIRED SOURCE COUNT
//
// Explicit Prepare Asset Search value wins.
//
// Otherwise:
// roughly one independent source per 35 seconds of
// desired footage.
// ------------------------------------------------------

const requestDesiredSourceCount =
  numberValue(
    requestContext
      .desired_source_count,
    0
  );


const desiredSourceCount =
  requestDesiredSourceCount > 0
    ? clamp(
        Math.round(
          requestDesiredSourceCount
        ),
        1,
        8
      )
    : clamp(
        Math.ceil(
          desiredFootageSeconds /
          35
        ),
        1,
        6
      );


// ------------------------------------------------------
// CANDIDATE SAFETY BUDGET
// ------------------------------------------------------

const automaticCandidateBudget =
  clamp(
    8 +
    (
      desiredSourceCount * 3
    ),
    12,
    20
  );


const configuredCandidateBudget =
  numberValue(
    requestContext
      .max_unique_candidate_attempts ??
    state
      .max_unique_candidate_attempts,
    0
  );


const maxUniqueCandidateAttempts =
  configuredCandidateBudget > 0
    ? clamp(
        Math.round(
          configuredCandidateBudget
        ),
        6,
        30
      )
    : automaticCandidateBudget;


// ------------------------------------------------------
// MAX SEARCH ROUNDS
// ------------------------------------------------------

let automaticMaxSearchRounds =
  4;

if (
  desiredSourceCount >= 2 &&
  desiredSourceCount <= 3
) {

  automaticMaxSearchRounds =
    5;

} else if (
  desiredSourceCount >= 4
) {

  automaticMaxSearchRounds =
    6;
}


const configuredMaxSearchRounds =
  numberValue(
    requestContext
      .max_search_rounds ??
    state
      .max_search_rounds,
    0
  );


const maxSearchRounds =
  configuredMaxSearchRounds > 0
    ? clamp(
        Math.round(
          configuredMaxSearchRounds
        ),
        3,
        8
      )
    : automaticMaxSearchRounds;


// ======================================================
// PARSE EXECUTE COMMAND OUTPUT
// ======================================================

const stdout =
  clean(
    commandResult.stdout
  );


const stderr =
  clean(
    commandResult.stderr
  );


const extractionStatus =
  readValue(
    stdout,
    'EXTRACT_SELECTED_STATUS'
  );


const requestedClipCount =
  numberValue(
    readValue(
      stdout,
      'REQUESTED_CLIP_COUNT'
    ),
    0
  );


const extractedClipCount =
  numberValue(
    readValue(
      stdout,
      'EXTRACTED_CLIP_COUNT'
    ),
    0
  );


const selectedSceneIdsRaw =
  readValue(
    stdout,
    'SELECTED_SCENE_IDS'
  );


const selectedSceneIds =
  selectedSceneIdsRaw
    ? [
        ...new Set(
          selectedSceneIdsRaw
            .split(',')
            .map(
              id =>
                id
                  .trim()
                  .padStart(
                    2,
                    '0'
                  )
            )
            .filter(Boolean)
        )
      ]
    : [];


// ======================================================
// PARSE CLIP METADATA
// ======================================================

const clipMap =
  new Map();


for (
  const line
  of stdout.split(
    /\r?\n/
  )
) {

  const match =
    line.match(
      /^CLIP_(\d{2})_(SCENE_ID|ANCHOR|START|DURATION|PATH)=(.*)$/
    );

  if (!match) {

    continue;
  }

  const order =
    numberValue(
      match[1],
      0
    );

  const field =
    match[2];

  const value =
    clean(
      match[3]
    );


  if (
    !clipMap.has(
      order
    )
  ) {

    clipMap.set(
      order,
      {
        order
      }
    );
  }


  const clip =
    clipMap.get(
      order
    );


  switch (field) {

    case 'SCENE_ID':

      clip.scene_id =
        value.padStart(
          2,
          '0'
        );

      break;


    case 'ANCHOR':

      clip.anchor_time =
        numberValue(
          value,
          0
        );

      break;


    case 'START':

      clip.start_time =
        numberValue(
          value,
          0
        );

      break;


    case 'DURATION':

      clip.duration =
        numberValue(
          value,
          0
        );

      break;


    case 'PATH':

      clip.path =
        value;

      break;
  }
}


// ======================================================
// CLEAN CLIP ARRAY
// ======================================================

const clips =
  [
    ...clipMap.values()
  ]
    .filter(
      clip =>
        clean(
          clip.path
        ) &&
        numberValue(
          clip.duration,
          0
        ) > 0.05
    )
    .sort(
      (a, b) =>
        numberValue(
          a.order
        ) -
        numberValue(
          b.order
        )
    )
    .map(
      clip => {

        const startTime =
          numberValue(
            clip.start_time,
            0
          );

        const duration =
          numberValue(
            clip.duration,
            0
          );

        return {

          ...clip,

          anchor_time:
            round3(
              clip.anchor_time
            ),

          start_time:
            round3(
              startTime
            ),

          duration:
            round3(
              duration
            ),

          end_time:
            round3(
              startTime +
              duration
            ),

          path:
            clean(
              clip.path
            ),

          muted:
            state
              .mute_original_audio !==
            false
        };
      }
    );


const currentSourceFootageSeconds =
  round3(
    clips.reduce(
      (
        sum,
        clip
      ) =>
        sum +
        numberValue(
          clip.duration,
          0
        ),
      0
    )
  );


// ======================================================
// CURRENT SOURCE PACKAGE
// ======================================================

const currentSourceUrl =
  canonicalizeUrl(
    state
      .source_url ||
    state
      .candidate_url ||
    state
      .processing_source_url
  );


const sourceAssetReady =
  (
    extractionStatus ===
      'success' &&

    extractedClipCount > 0 &&

    clips.length ===
      extractedClipCount &&

    Boolean(
      currentSourceUrl
    )
  );


const currentPackage = {

  source_id:
    clean(
      state.file_slug ||
      state.source_id
    ),

  game_title:
    clean(
      state.game_title ||
      requestContext.game_title
    ),

  source_title:
    clean(
      state.source_title ||
      state.candidate_title ||
      state.processing_source_title
    ),

  source_url:
    currentSourceUrl,

  source_file_path:
    clean(
      state.source_file_path
    ),

  source_channel:
    clean(
      state.source_channel ||
      state.candidate_channel ||
      state.processing_source_channel
    ),

  source_platform:
    clean(
      state.source_platform ||
      state.candidate_source ||
      state.processing_source_platform
    ),

  source_class:
    clean(
      state.source_class ||
      state.candidate_source_class ||
      state.processing_source_class
    ),

  source_authenticity_score:
    numberValue(
      state
        .source_authenticity_score ??
      state
        .preliminary_source_trust_score,
      0
    ),

  selection_summary:
    clean(
      state.selection_summary
    ),

  selected_scene_ids:
    selectedSceneIds,

  clip_count:
    clips.length,

  extracted_clip_count:
    clips.length,

  total_footage_seconds:
    currentSourceFootageSeconds,

  clips,

  source_asset_ready:
    sourceAssetReady
};


// ======================================================
// EXISTING COLLECTION
// ======================================================

let sourcePackages =
  Array.isArray(
    state.source_packages
  )
    ? [
        ...state.source_packages
      ]
    : [];


// ------------------------------------------------------
// REMOVE INVALID PACKAGES
// ------------------------------------------------------

sourcePackages =
  sourcePackages.filter(
    pkg =>
      pkg &&
      typeof pkg ===
        'object'
  );


// ------------------------------------------------------
// MANUAL RE-RUN SAFETY
//
// Replace old copy of current URL rather than duplicate.
// ------------------------------------------------------

if (
  currentSourceUrl
) {

  sourcePackages =
    sourcePackages.filter(
      pkg =>
        canonicalizeUrl(
          pkg?.source_url
        ) !==
        currentSourceUrl
    );
}


// ------------------------------------------------------
// ONLY ADD VALID CURRENT PACKAGE
// ------------------------------------------------------

if (
  sourceAssetReady
) {

  sourcePackages.push(
    currentPackage
  );
}


// ======================================================
// DEDUPE COLLECTION BY SOURCE URL / SOURCE ID
// ======================================================

const sourcePackageMap =
  new Map();


for (
  const pkg
  of sourcePackages
) {

  const packageUrl =
    canonicalizeUrl(
      pkg.source_url
    );

  const packageId =
    clean(
      pkg.source_id
    );

  const key =
    packageUrl ||
    packageId;

  if (!key) {

    continue;
  }

  sourcePackageMap.set(
    key,
    {
      ...pkg,

      source_url:
        packageUrl,

      clips:
        Array.isArray(
          pkg.clips
        )
          ? pkg.clips
          : []
    }
  );
}


sourcePackages =
  [
    ...sourcePackageMap.values()
  ];


sourcePackages.forEach(
  (
    pkg,
    index
  ) => {

    pkg.source_index =
      index + 1;
  }
);


// ======================================================
// USED SOURCE URLS
// ======================================================

const usedSourceUrls =
  uniqueUrls([
    ...(
      Array.isArray(
        state.used_source_urls
      )
        ? state.used_source_urls
        : []
    ),

    ...sourcePackages
      .map(
        pkg =>
          pkg.source_url
      )
  ]);


// ======================================================
// COLLECTION TOTALS
// ======================================================

const sourcePackageCount =
  sourcePackages.length;


const actualSourceCount =
  sourcePackageCount;


const collectionTotalFootageSeconds =
  round3(
    sourcePackages.reduce(
      (
        sum,
        pkg
      ) =>
        sum +
        numberValue(
          pkg.total_footage_seconds,
          0
        ),
      0
    )
  );


const totalClipCount =
  sourcePackages.reduce(
    (
      sum,
      pkg
    ) =>
      sum +
      (
        Array.isArray(
          pkg.clips
        )
          ? pkg.clips.length
          : 0
      ),
    0
  );


const enoughSources =
  actualSourceCount >=
  desiredSourceCount;


const enoughFootage =
  collectionTotalFootageSeconds >=
  desiredFootageSeconds;


const collectionReady =
  enoughSources &&
  enoughFootage;


const needsMoreSourceCount =
  !enoughSources;


const needsMoreFootage =
  !enoughFootage;


// Backwards-compatible field.
//
// Means "collection is not complete yet", not merely
// "source count is insufficient".
const needsMoreSources =
  !collectionReady;


const sourceCountShortfall =
  Math.max(
    0,
    desiredSourceCount -
    actualSourceCount
  );


const footageShortfallSeconds =
  round3(
    Math.max(
      0,
      desiredFootageSeconds -
      collectionTotalFootageSeconds
    )
  );


const footageCoverageRatio =
  desiredFootageSeconds > 0
    ? round3(
        collectionTotalFootageSeconds /
        desiredFootageSeconds
      )
    : 1;


// ======================================================
// CURRENT SEARCH STATE
//
// Dynamic counters come from the active pipeline state.
// Root Prepare Asset Search is used only for immutable
// configuration, never to reset live counters.
// ======================================================

const searchRound =
  Math.max(
    0,
    numberValue(
      state.search_round,
      0
    )
  );


const expandedSearchRound =
  Math.max(
    0,
    numberValue(
      state.expanded_search_round,
      searchRound
    )
  );


const searchExhausted =
  state.search_exhausted ===
    true;


const sourcesExhausted =
  (
    state.sources_exhausted ===
      true ||

    state.expanded_search_exhausted ===
      true
  );


const expandedSearch =
  state.expanded_search ===
    true;


// ======================================================
// FAILED / EXCLUDED CANDIDATE STATE
// ======================================================

const failedCandidateUrls =
  uniqueUrls(
    state.failed_candidate_urls
  );


const failedCandidateHistory =
  Array.isArray(
    state.failed_candidate_history
  )
    ? [
        ...state.failed_candidate_history
      ]
    : [];


const excludedCandidateUrls =
  uniqueUrls([
    ...(
      Array.isArray(
        state.excluded_candidate_urls
      )
        ? state.excluded_candidate_urls
        : []
    ),

    ...failedCandidateUrls,

    ...usedSourceUrls
  ]);


// ======================================================
// RECOVER EDITORIAL CANDIDATE POOL
// ======================================================

let candidatePool =
  Array.isArray(
    state.candidate_pool
  )
    ? [
        ...state.candidate_pool
      ]
    : [];


// ------------------------------------------------------
// First source may not carry candidate_pool.
// Recover best Assess Video Rights execution.
// ------------------------------------------------------

if (
  candidatePool.length ===
  0
) {

  try {

    const assessRuns =
      $('Assess Video Rights')
        .all()
        .map(
          item =>
            item.json || {}
        )
        .filter(
          run =>
            Array.isArray(
              run.results
            ) &&
            run.results.length > 0 &&
            (
              !currentPackage
                .game_title ||

              clean(
                run.game_title
              ) ===
              currentPackage
                .game_title
            )
        );


    assessRuns.sort(
      (
        a,
        b
      ) => {

        const expandedDifference =
          Number(
            b.expanded_search ===
              true
          ) -
          Number(
            a.expanded_search ===
              true
          );

        if (
          expandedDifference !==
          0
        ) {

          return (
            expandedDifference
          );
        }


        const roundDifference =
          numberValue(
            b.search_round,
            0
          ) -
          numberValue(
            a.search_round,
            0
          );

        if (
          roundDifference !==
          0
        ) {

          return (
            roundDifference
          );
        }


        return (
          b.results.length -
          a.results.length
        );
      }
    );


    if (
      assessRuns.length
    ) {

      candidatePool =
        assessRuns[0]
          .results;
    }

  } catch {

    candidatePool = [];
  }
}


// ======================================================
// NORMALIZE / DEDUPE CANDIDATE POOL
// ======================================================

const candidateMap =
  new Map();


for (
  const candidate
  of candidatePool
) {

  if (
    !candidate ||
    typeof candidate !==
      'object'
  ) {

    continue;
  }

  const url =
    canonicalizeUrl(
      candidate.url ||
      candidate.original_url ||
      candidate.candidate_url ||
      candidate.source_url
    );

  if (!url) {

    continue;
  }

  if (
    !candidateMap.has(
      url
    )
  ) {

    candidateMap.set(
      url,
      {
        ...candidate,

        url
      }
    );
  }
}


candidatePool =
  [
    ...candidateMap.values()
  ];


// ======================================================
// COLLECTION STATUS
// ======================================================

let collectionStatus =
  'incomplete';


if (
  collectionReady
) {

  collectionStatus =
    'ready';

} else if (
  sourcePackageCount === 0
) {

  collectionStatus =
    'empty';

} else if (
  sourcesExhausted &&
  !enoughSources &&
  !enoughFootage
) {

  collectionStatus =
    'ready_with_source_and_footage_shortfall';

} else if (
  sourcesExhausted &&
  !enoughSources
) {

  collectionStatus =
    'ready_with_source_shortfall';

} else if (
  sourcesExhausted &&
  !enoughFootage
) {

  collectionStatus =
    'ready_with_footage_shortfall';
}


// ======================================================
// NEXT COLLECTION ACTION
// ======================================================

let nextCollectionAction =
  'select_next_source';


if (
  collectionReady
) {

  nextCollectionAction =
    'collection_ready';

} else if (
  sourcesExhausted ||
  searchExhausted
) {

  nextCollectionAction =
    'source_search_exhausted';
}


// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      // =================================================
      // PRESERVE COMPLETE ACTIVE PIPELINE STATE
      // =================================================

      ...state,

      // =================================================
      // REQUEST LOCK
      // =================================================

      requested_asset_type:
        requestedAssetType,

      asset_type:
        requestedAssetType,

      game_title:
        currentPackage.game_title,

      // =================================================
      // AUTHORITATIVE TARGET STATE
      // =================================================

      target_video_duration_sec:
        round3(
          targetVideoDurationSec
        ),

      visual_coverage_ratio:
        round3(
          visualCoverageRatio
        ),

      desired_footage_seconds:
        round3(
          desiredFootageSeconds
        ),

      desired_source_count:
        desiredSourceCount,

      max_unique_candidate_attempts:
        maxUniqueCandidateAttempts,

      max_search_rounds:
        maxSearchRounds,

      // =================================================
      // CURRENT SOURCE
      // =================================================

      source_title:
        currentPackage.source_title,

      source_url:
        currentPackage.source_url,

      source_id:
        currentPackage.source_id,

      source_file_path:
        currentPackage.source_file_path,

      source_channel:
        currentPackage.source_channel,

      source_platform:
        currentPackage.source_platform,

      source_class:
        currentPackage.source_class,

      source_authenticity_score:
        currentPackage
          .source_authenticity_score,

      extraction_status:
        extractionStatus,

      requested_clip_count:
        requestedClipCount,

      extracted_clip_count:
        extractedClipCount,

      selected_scene_ids:
        selectedSceneIds,

      clips,

      current_source_footage_seconds:
        currentSourceFootageSeconds,

      source_asset_ready:
        sourceAssetReady,

      source_package:
        sourceAssetReady
          ? currentPackage
          : null,

      // =================================================
      // COLLECTION
      // =================================================

      source_packages:
        sourcePackages,

      source_package_count:
        sourcePackageCount,

      actual_source_count:
        actualSourceCount,

      source_count_shortfall:
        sourceCountShortfall,

      used_source_urls:
        usedSourceUrls,

      collection_total_footage_seconds:
        collectionTotalFootageSeconds,

      total_footage_seconds:
        collectionTotalFootageSeconds,

      total_clip_count:
        totalClipCount,

      footage_shortfall_seconds:
        footageShortfallSeconds,

      real_footage_target_shortfall_seconds:
        footageShortfallSeconds,

      footage_coverage_ratio:
        footageCoverageRatio,

      enough_sources:
        enoughSources,

      enough_footage:
        enoughFootage,

      collection_ready:
        collectionReady,

      needs_more_source_count:
        needsMoreSourceCount,

      needs_more_footage:
        needsMoreFootage,

      needs_more_sources:
        needsMoreSources,

      collection_status:
        collectionStatus,

      next_collection_action:
        nextCollectionAction,

      next_source_action:
        collectionReady
          ? 'collection_ready'
          : (
              sourcesExhausted ||
              searchExhausted
                ? 'source_search_exhausted'
                : state.next_source_action
          ),

      // =================================================
      // CANDIDATES
      // =================================================

      candidate_pool:
        candidatePool,

      candidate_pool_count:
        candidatePool.length,

      // =================================================
      // SEARCH / RETRY STATE
      // =================================================

      search_round:
        searchRound,

      expanded_search_round:
        expandedSearchRound,

      max_search_rounds:
        maxSearchRounds,

      search_exhausted:
        searchExhausted,

      sources_exhausted:
        sourcesExhausted,

      expanded_search:
        expandedSearch,

      failed_candidate_urls:
        failedCandidateUrls,

      failed_candidate_history:
        failedCandidateHistory,

      failed_candidate_count:
        failedCandidateUrls.length,

      excluded_candidate_urls:
        excludedCandidateUrls,

      max_unique_candidate_attempts:
        maxUniqueCandidateAttempts,

      no_progress_search_rounds:
        Math.max(
          0,
          numberValue(
            state
              .no_progress_search_rounds,
            0
          )
        ),

      // =================================================
      // DEBUG
      // =================================================

      stderr_warning:
        stderr,

      editorial_source_package_version:
        '2.0-authoritative-target-state-safe'
    }
  }
];

const input = $input.first()?.json || {};

// ======================================================
// PREPARE NEXT EDITORIAL SOURCE
// VERSION: 2.0-adaptive-collection-package-merge-safe
// Mode: Run Once for All Items
// ======================================================

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {
  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {
  return Number(
    num(value).toFixed(3)
  );
}

function clamp(value, min, max) {
  return Math.min(
    max,
    Math.max(
      min,
      value
    )
  );
}

function uniqueStrings(values = []) {
  return [
    ...new Set(
      values
        .map(clean)
        .filter(Boolean)
    )
  ];
}

// ======================================================
// URL CLEANUP
// ======================================================

function unwrapMarkdownUrl(value) {

  const raw =
    clean(value);

  if (!raw) {
    return '';
  }

  const match =
    raw.match(
      /^\[(https?:\/\/[^\]]+)\]\((https?:\/\/[^)]+)\)$/i
    );

  if (match) {
    return (
      match[2] ||
      match[1] ||
      ''
    );
  }

  return raw;
}

function canonicalizeUrl(value) {

  const raw =
    unwrapMarkdownUrl(value);

  if (!raw) {
    return '';
  }

  try {

    const parsed =
      new URL(raw);

    const host =
      parsed.hostname
        .replace(/^www\./i, '')
        .replace(/^m\./i, '')
        .toLowerCase();

    if (
      host === 'youtube.com' ||
      host === 'youtu.be'
    ) {

      let videoId = '';

      if (
        host === 'youtu.be'
      ) {

        videoId =
          parsed.pathname
            .replace(/^\/+/, '')
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams.get('v') ||
          '';
      }

      if (videoId) {
        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    if (
      host === 'dailymotion.com'
    ) {

      const match =
        parsed.pathname.match(
          /\/video\/([A-Za-z0-9]+)/i
        );

      if (match?.[1]) {
        return (
          `https://www.dailymotion.com/video/${match[1]}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return raw;
  }
}

// ======================================================
// TEXT NORMALIZATION
// ======================================================

function normalizeText(value) {

  return clean(value)
    .toLowerCase()
    .normalize('NFKD')
    .replace(
      /[^\p{L}\p{N}\s]/gu,
      ' '
    )
    .replace(
      /\s+/g,
      ' '
    )
    .trim();
}

// ======================================================
// CLIP HELPERS
// ======================================================

function getClipPath(clip) {

  return clean(
    clip?.final_clip_path ||
    clip?.final_path ||
    clip?.path ||
    clip?.clip_path ||
    clip?.local_path
  );
}

function getClipDuration(clip) {

  const direct =
    num(
      clip?.actual_duration ??
      clip?.duration ??
      clip?.duration_seconds,
      0
    );

  if (direct > 0) {
    return direct;
  }

  const start =
    num(
      clip?.start_time ??
      clip?.start ??
      clip?.start_sec,
      0
    );

  const end =
    num(
      clip?.end_time ??
      clip?.end ??
      clip?.end_sec,
      0
    );

  if (end > start) {
    return end - start;
  }

  return 0;
}

function packageClips(pkg) {

  if (
    Array.isArray(pkg?.clips)
  ) {
    return pkg.clips;
  }

  if (
    Array.isArray(
      pkg?.selected_clips
    )
  ) {
    return pkg.selected_clips;
  }

  if (
    Array.isArray(
      pkg?.editorial_clips
    )
  ) {
    return pkg.editorial_clips;
  }

  if (
    Array.isArray(
      pkg?.extracted_clips
    )
  ) {
    return pkg.extracted_clips;
  }

  return [];
}

// ======================================================
// REQUEST
// ======================================================

const gameTitle =
  clean(
    input.game_title
  );

const requestedAssetType =
  clean(
    input.requested_asset_type ||
    input.asset_type ||
    'video'
  )
    .toLowerCase() === 'image'
    ? 'image'
    : 'video';

// ======================================================
// TARGET DURATION / COVERAGE
// ======================================================

const targetVideoDurationSec =
  Math.max(
    1,
    num(
      input.target_video_duration_sec,
      120
    )
  );

const visualCoverageRatio =
  clamp(
    num(
      input.visual_coverage_ratio,
      0.70
    ),
    0.10,
    1
  );

const desiredFootageSeconds =
  round3(
    num(
      input.desired_footage_seconds,
      targetVideoDurationSec *
      visualCoverageRatio
    )
  );

const automaticDesiredSourceCount =
  clamp(
    Math.ceil(
      desiredFootageSeconds / 35
    ),
    1,
    6
  );

const explicitDesiredSourceCount =
  num(
    input.desired_source_count,
    0
  );

const desiredSourceCount =
  explicitDesiredSourceCount > 0
    ? clamp(
        Math.round(
          explicitDesiredSourceCount
        ),
        1,
        8
      )
    : automaticDesiredSourceCount;

// ======================================================
// EXISTING + NEW SOURCE PACKAGES
//
// CRITICAL FIX:
// Merge input.source_package into input.source_packages.
// ======================================================

const rawPackages = [];

if (
  Array.isArray(
    input.source_packages
  )
) {

  rawPackages.push(
    ...input.source_packages
  );
}

if (
  input.source_package &&
  typeof input.source_package ===
    'object' &&
  !Array.isArray(
    input.source_package
  )
) {

  rawPackages.push(
    input.source_package
  );
}

// ======================================================
// CURRENT ITEM MAY ITSELF BE THE NEW SOURCE PACKAGE
// ======================================================

const currentClips =
  Array.isArray(input.clips)
    ? input.clips
    : [];

const currentHasUsableClips =
  currentClips.some(
    clip =>
      getClipPath(clip) &&
      getClipDuration(clip) > 0.05
  );

if (
  currentHasUsableClips &&
  (
    input.source_id ||
    input.source_url
  )
) {

  rawPackages.push({
    source_id:
      clean(
        input.source_id
      ),

    game_title:
      gameTitle,

    source_title:
      clean(
        input.source_title
      ),

    source_url:
      canonicalizeUrl(
        input.source_url
      ),

    source_file_path:
      clean(
        input.source_file_path
      ),

    source_channel:
      clean(
        input.source_channel
      ),

    source_platform:
      clean(
        input.source_platform
      ),

    source_class:
      clean(
        input.source_class
      ),

    source_authenticity_score:
      num(
        input.source_authenticity_score,
        0
      ),

    selected_scene_ids:
      Array.isArray(
        input.selected_scene_ids
      )
        ? input.selected_scene_ids
        : [],

    clips:
      currentClips,

    total_footage_seconds:
      num(
        input.total_footage_seconds,
        0
      )
  });
}

// ======================================================
// NORMALIZE + REMOVE EMPTY PACKAGES
// ======================================================

function normalizePackage(
  pkg,
  fallbackIndex
) {

  if (
    !pkg ||
    typeof pkg !== 'object'
  ) {

    return null;
  }

  const sourceUrl =
    canonicalizeUrl(
      pkg.source_url ||
      pkg.url
    );

  const sourceId =
    clean(
      pkg.source_id
    ) ||
    (
      sourceUrl
        ? `source-${fallbackIndex + 1}`
        : ''
    );

  const rawClips =
    packageClips(
      pkg
    );

  const usableClips =
    rawClips.filter(
      clip =>
        getClipPath(clip) &&
        getClipDuration(clip) > 0.05
    );

  if (
    usableClips.length === 0
  ) {

    return null;
  }

  const totalFootage =
    usableClips.reduce(
      (sum, clip) =>
        sum +
        getClipDuration(
          clip
        ),
      0
    );

  return {

    ...pkg,

    source_id:
      sourceId,

    source_url:
      sourceUrl,

    source_title:
      clean(
        pkg.source_title ||
        pkg.title
      ),

    source_channel:
      clean(
        pkg.source_channel ||
        pkg.channel
      ),

    source_platform:
      clean(
        pkg.source_platform ||
        pkg.source
      ),

    source_class:
      clean(
        pkg.source_class
      ),

    clips:
      usableClips,

    extracted_clip_count:
      usableClips.length,

    total_footage_seconds:
      round3(
        totalFootage
      )
  };
}

const normalizedPackages =
  rawPackages
    .map(
      (pkg, index) =>
        normalizePackage(
          pkg,
          index
        )
    )
    .filter(Boolean);

// ======================================================
// DEDUPE PACKAGES
//
// Same URL/source must only count once.
// Unique clips are merged.
// ======================================================

const sourceMap =
  new Map();

for (
  const pkg
  of normalizedPackages
) {

  const key =
    pkg.source_url ||
    pkg.source_id;

  if (!key) {
    continue;
  }

  if (
    !sourceMap.has(
      key
    )
  ) {

    sourceMap.set(
      key,
      {
        ...pkg,
        clips:
          [...pkg.clips]
      }
    );

    continue;
  }

  const existing =
    sourceMap.get(
      key
    );

  const clipKeys =
    new Set(
      existing.clips.map(
        clip =>
          [
            getClipPath(
              clip
            ),
            round3(
              clip.start_time
            ),
            round3(
              getClipDuration(
                clip
              )
            )
          ].join('|')
      )
    );

  for (
    const clip
    of pkg.clips
  ) {

    const clipKey =
      [
        getClipPath(
          clip
        ),
        round3(
          clip.start_time
        ),
        round3(
          getClipDuration(
            clip
          )
        )
      ].join('|');

    if (
      clipKeys.has(
        clipKey
      )
    ) {
      continue;
    }

    clipKeys.add(
      clipKey
    );

    existing.clips.push(
      clip
    );
  }

  existing.extracted_clip_count =
    existing.clips.length;

  existing.total_footage_seconds =
    round3(
      existing.clips.reduce(
        (sum, clip) =>
          sum +
          getClipDuration(
            clip
          ),
        0
      )
    );
}

const sourcePackages =
  [...sourceMap.values()];

sourcePackages.forEach(
  (pkg, index) => {

    pkg.source_index =
      index + 1;
  }
);

// ======================================================
// COLLECTION TOTALS
// ======================================================

const sourcePackageCount =
  sourcePackages.length;

const collectionTotalFootageSeconds =
  round3(
    sourcePackages.reduce(
      (sum, pkg) =>
        sum +
        num(
          pkg.total_footage_seconds,
          0
        ),
      0
    )
  );

const enoughSources =
  sourcePackageCount >=
  desiredSourceCount;

const minimumRealFootageSeconds = targetVideoDurationSec * 1.05;
const enoughFootage = collectionTotalFootageSeconds >= minimumRealFootageSeconds;

// IMPORTANT:
// Both requirements must be met.

const collectionReady =
  enoughSources &&
  enoughFootage;

const sourceCountShortfall =
  Math.max(
    0,
    desiredSourceCount -
    sourcePackageCount
  );

const footageShortfallSeconds =
  Math.max(
    0,
    desiredFootageSeconds -
    collectionTotalFootageSeconds
  );

// ======================================================
// USED SOURCE URLS
// ======================================================

const usedSourceUrls =
  uniqueStrings([
    ...(
      Array.isArray(
        input.used_source_urls
      )
        ? input.used_source_urls
        : []
    ),

    ...sourcePackages
      .map(
        pkg =>
          canonicalizeUrl(
            pkg.source_url
          )
      )
      .filter(Boolean)
  ]);

// ======================================================
// FAILED / EXCLUDED URLS
// ======================================================

const failedCandidateUrls =
  uniqueStrings(
    (
      Array.isArray(
        input.failed_candidate_urls
      )
        ? input.failed_candidate_urls
        : []
    )
      .map(
        canonicalizeUrl
      )
      .filter(Boolean)
  );

const excludedCandidateUrls =
  uniqueStrings([
    ...(
      Array.isArray(
        input.excluded_candidate_urls
      )
        ? input.excluded_candidate_urls
        : []
    )
      .map(
        canonicalizeUrl
      ),

    ...failedCandidateUrls,

    ...usedSourceUrls
  ]);

const usedSourceUrlSet =
  new Set(
    usedSourceUrls
  );

const failedCandidateUrlSet =
  new Set(
    failedCandidateUrls
  );

const excludedCandidateUrlSet =
  new Set(
    excludedCandidateUrls
  );

// ======================================================
// TITLE / CONTENT DIVERSITY HELPERS
// ======================================================

const gameBase =
  normalizeText(
    input.target_game_base ||
    gameTitle.replace(
      /\(\s*\d{4}\s*\)/g,
      ''
    )
  );

const gameTokens =
  new Set(
    gameBase
      .split(' ')
      .filter(Boolean)
  );

function normalizedTitleTokens(title) {

  const ignored =
    new Set([
      ...gameTokens,
      'official',
      'video',
      'hd',
      'uhd',
      '4k',
      '1080p',
      '60fps',
      '60',
      'fps',
      'pegi',
      'gog',
      'xbox',
      'playstation',
      'ps4',
      'ps5',
      'pc'
    ]);

  return normalizeText(
    title
  )
    .split(' ')
    .filter(
      token =>
        token &&
        !ignored.has(
          token
        )
    );
}

function jaccardSimilarity(
  aTitle,
  bTitle
) {

  const a =
    new Set(
      normalizedTitleTokens(
        aTitle
      )
    );

  const b =
    new Set(
      normalizedTitleTokens(
        bTitle
      )
    );

  if (
    !a.size ||
    !b.size
  ) {

    return 0;
  }

  let intersection =
    0;

  for (
    const token
    of a
  ) {

    if (
      b.has(
        token
      )
    ) {
      intersection++;
    }
  }

  const union =
    new Set([
      ...a,
      ...b
    ]).size;

  return (
    union > 0
      ? intersection / union
      : 0
  );
}

function detectContentSignature(title) {

  const t =
    normalizeText(
      title
    );

  if (
    (
      t.includes('e3') ||
      t.includes('showcase')
    ) &&
    (
      t.includes('reveal') ||
      t.includes('gameplay')
    )
  ) {

    return 'showcase_reveal';
  }

  if (
    t.includes('launch') &&
    t.includes('trailer')
  ) {

    return 'launch_trailer';
  }

  if (
    t.includes('tech analysis') ||
    t.includes('technical analysis') ||
    t.includes('performance analysis') ||
    t.includes('graphics analysis')
  ) {

    return 'editorial_analysis';
  }

  if (
    t.includes('review')
  ) {

    return 'review';
  }

  if (
    t.includes('all trailers') ||
    t.includes('trailers')
  ) {

    return 'trailer_compilation';
  }

  if (
    t.includes('trailer')
  ) {

    return 'general_trailer';
  }

  if (
    t.includes('let s play') ||
    t.includes('lets play') ||
    t.includes("let's play")
  ) {

    return 'lets_play';
  }

  if (
    t.includes('gameplay')
  ) {

    return 'gameplay';
  }

  return 'general_video';
}

function signatureFamily(signature) {

  switch (signature) {

    case 'showcase_reveal':
      return 'reveal';

    case 'launch_trailer':
    case 'general_trailer':
    case 'trailer_compilation':
      return 'trailer';

    case 'editorial_analysis':
    case 'review':
      return 'editorial_analysis';

    case 'lets_play':
    case 'gameplay':
      return 'gameplay';

    default:
      return 'general';
  }
}

// ======================================================
// USED CONTENT STATE
// ======================================================

const usedTitles =
  sourcePackages
    .map(
      pkg =>
        clean(
          pkg.source_title
        )
    )
    .filter(Boolean);

const usedSignatures =
  usedTitles.map(
    detectContentSignature
  );

const usedFamilies =
  usedSignatures.map(
    signatureFamily
  );

const usedSourceClasses =
  sourcePackages
    .map(
      pkg =>
        clean(
          pkg.source_class
        )
    )
    .filter(Boolean);

const usedChannels =
  sourcePackages
    .map(
      pkg =>
        normalizeText(
          pkg.source_channel
        )
    )
    .filter(Boolean);

// ======================================================
// CANDIDATE POOL
// ======================================================

let candidatePool = [];

if (
  Array.isArray(
    input.candidate_pool
  )
) {

  candidatePool =
    input.candidate_pool;

} else if (
  Array.isArray(
    input.ranked_results
  )
) {

  candidatePool =
    input.ranked_results;

} else if (
  Array.isArray(
    input.results
  )
) {

  candidatePool =
    input.results;

} else if (
  Array.isArray(
    input.trusted_candidates
  )
) {

  candidatePool =
    input.trusted_candidates;
}

// ======================================================
// NORMALIZE CANDIDATES
// ======================================================

const candidates =
  candidatePool
    .map(
      (candidate, index) => {

        const url =
          canonicalizeUrl(
            candidate?.url ||
            candidate?.original_url ||
            candidate?.candidate_url ||
            candidate?.source_url
          );

        const title =
          clean(
            candidate?.title ||
            candidate?.candidate_title ||
            candidate?.source_title
          );

        const sourceClass =
          clean(
            candidate?.resolved_source_class ||
            candidate?.preliminary_source_class ||
            candidate?.source_class
          );

        const trustScore =
          num(
            candidate?.resolved_trust_score ??
            candidate?.preliminary_source_trust_score ??
            candidate?.source_authenticity_score,
            0
          );

        const verified =
          (
            candidate?.resolved_verified ===
              true ||

            candidate?.preliminary_source_verified ===
              true ||

            candidate?.source_verified ===
              true
          );

        const gameMatchScore =
          num(
            candidate?.resolved_game_match_score ??
            candidate?.game_match_score ??
            candidate?.relevance_score,
            0
          );

        const originalRank =
          num(
            candidate?.resolved_original_rank ??
            candidate?.original_rank ??
            candidate?.original_position,
            index + 1
          );

        const signature =
          detectContentSignature(
            title
          );

        return {

          ...candidate,

          url,

          title,

          resolved_source_class:
            sourceClass,

          resolved_trust_score:
            trustScore,

          resolved_verified:
            verified,

          resolved_game_match_score:
            gameMatchScore,

          resolved_original_rank:
            originalRank,

          content_signature:
            signature,

          content_family:
            signatureFamily(
              signature
            )
        };
      }
    )
    .filter(
      candidate =>
        Boolean(
          candidate.url
        )
    );

// ======================================================
// REMOVE USED / FAILED / EXCLUDED
// ======================================================

const availableCandidates =
  candidates.filter(
    candidate => {

      if (
        usedSourceUrlSet.has(
          candidate.url
        )
      ) {
        return false;
      }

      if (
        failedCandidateUrlSet.has(
          candidate.url
        )
      ) {
        return false;
      }

      if (
        excludedCandidateUrlSet.has(
          candidate.url
        )
      ) {
        return false;
      }

      return true;
    }
  );

// ======================================================
// TRUSTED CANDIDATES
// ======================================================

const trustedClasses =
  new Set([
    'official_first_party',
    'official_publisher',
    'official_platform',
    'official_platform_distribution',
    'official_store',
    'established_editorial_media',
    'official_gaming_event',
    'gaming_event'
  ]);

const trustedCandidates =
  availableCandidates.filter(
    candidate => {

      const trust =
        candidate
          .resolved_trust_score;

      const verified =
        candidate
          .resolved_verified ===
        true;

      const trustedClass =
        trustedClasses.has(
          candidate
            .resolved_source_class
        );

      return (
        trust >= 75 &&
        verified &&
        trustedClass
      );
    }
  );

// ======================================================
// CONTENT DIVERSITY ANALYSIS
// ======================================================

const analyzedTrustedCandidates =
  trustedCandidates.map(
    candidate => {

      let maxTitleSimilarity =
        0;

      let mostSimilarUsedTitle =
        '';

      for (
        const usedTitle
        of usedTitles
      ) {

        const similarity =
          jaccardSimilarity(
            candidate.title,
            usedTitle
          );

        if (
          similarity >
          maxTitleSimilarity
        ) {

          maxTitleSimilarity =
            similarity;

          mostSimilarUsedTitle =
            usedTitle;
        }
      }

      const signature =
        candidate
          .content_signature;

      const family =
        candidate
          .content_family;

      const sameSignatureAlreadyUsed =
        usedSignatures.includes(
          signature
        );

      const sameFamilyAlreadyUsed =
        usedFamilies.includes(
          family
        );

      const sameSourceClassAlreadyUsed =
        usedSourceClasses.includes(
          candidate
            .resolved_source_class
        );

      const sameChannelAlreadyUsed =
        usedChannels.includes(
          normalizeText(
            candidate.channel
          )
        );

      let hardDuplicate =
        false;

      let duplicateReason =
        '';

      if (
        maxTitleSimilarity >=
        0.82
      ) {

        hardDuplicate =
          true;

        duplicateReason =
          'very_high_title_similarity';

      } else if (
        signature ===
          'showcase_reveal' &&
        sameSignatureAlreadyUsed
      ) {

        hardDuplicate =
          true;

        duplicateReason =
          'showcase_reveal_already_used';

      } else if (
        signature ===
          'launch_trailer' &&
        sameSignatureAlreadyUsed
      ) {

        hardDuplicate =
          true;

        duplicateReason =
          'launch_trailer_already_used';

      } else if (
        family === 'trailer' &&
        sameFamilyAlreadyUsed &&
        maxTitleSimilarity >=
          0.55
      ) {

        hardDuplicate =
          true;

        duplicateReason =
          'likely_duplicate_trailer';
      }

      let diversityScore =
        (
          candidate
            .resolved_trust_score *
          1.20
        ) +
        (
          candidate
            .resolved_game_match_score *
          0.35
        );

      const reasons =
        [];

      if (
        !sameFamilyAlreadyUsed
      ) {

        diversityScore +=
          30;

        reasons.push(
          'new_content_family_bonus'
        );
      }

      if (
        !sameSignatureAlreadyUsed
      ) {

        diversityScore +=
          20;

        reasons.push(
          'new_content_signature_bonus'
        );
      }

      if (
        !sameSourceClassAlreadyUsed
      ) {

        diversityScore +=
          25;

        reasons.push(
          'new_source_class_bonus'
        );
      }

      if (
        !sameChannelAlreadyUsed
      ) {

        diversityScore +=
          10;

        reasons.push(
          'new_channel_bonus'
        );
      }

      if (
        signature ===
          'editorial_analysis' ||
        signature ===
          'review'
      ) {

        diversityScore +=
          20;

        reasons.push(
          'editorial_analysis_bonus'
        );
      }

      if (
        sameFamilyAlreadyUsed
      ) {

        if (
          family ===
          'trailer'
        ) {

          diversityScore -=
            65;

          reasons.push(
            'existing_trailer_family_penalty'
          );

        } else {

          diversityScore -=
            20;

          reasons.push(
            'existing_content_family_penalty'
          );
        }
      }

      if (
        sameSourceClassAlreadyUsed
      ) {

        diversityScore -=
          12;

        reasons.push(
          'existing_source_class_penalty'
        );
      }

      if (
        sameChannelAlreadyUsed
      ) {

        diversityScore -=
          10;

        reasons.push(
          'same_channel_penalty'
        );
      }

      diversityScore -=
        maxTitleSimilarity * 70;

      if (
        maxTitleSimilarity > 0
      ) {

        reasons.push(
          'title_similarity_penalty'
        );
      }

      if (
        signature ===
          'general_trailer' &&
        usedFamilies.includes(
          'trailer'
        )
      ) {

        diversityScore -=
          20;

        reasons.push(
          'generic_trailer_redundancy_penalty'
        );
      }

      return {

        ...candidate,

        max_used_title_similarity:
          Number(
            maxTitleSimilarity
              .toFixed(4)
          ),

        most_similar_used_title:
          mostSimilarUsedTitle,

        same_signature_already_used:
          sameSignatureAlreadyUsed,

        same_family_already_used:
          sameFamilyAlreadyUsed,

        same_source_class_already_used:
          sameSourceClassAlreadyUsed,

        same_channel_already_used:
          sameChannelAlreadyUsed,

        likely_content_duplicate:
          hardDuplicate,

        content_duplicate_reason:
          duplicateReason,

        diversity_score:
          Number(
            diversityScore
              .toFixed(3)
          ),

        diversity_score_reasons:
          reasons
      };
    }
  );

// ======================================================
// REMOVE HARD DUPLICATES + RANK
// ======================================================

const nonDuplicateTrustedCandidates =
  analyzedTrustedCandidates
    .filter(
      candidate =>
        !candidate
          .likely_content_duplicate
    )
    .sort(
      (a, b) => {

        if (
          b.diversity_score !==
          a.diversity_score
        ) {

          return (
            b.diversity_score -
            a.diversity_score
          );
        }

        if (
          b.resolved_trust_score !==
          a.resolved_trust_score
        ) {

          return (
            b.resolved_trust_score -
            a.resolved_trust_score
          );
        }

        if (
          b.resolved_game_match_score !==
          a.resolved_game_match_score
        ) {

          return (
            b.resolved_game_match_score -
            a.resolved_game_match_score
          );
        }

        return (
          a.resolved_original_rank -
          b.resolved_original_rank
        );
      }
    );

// ======================================================
// NEXT SOURCE
// ======================================================

const nextCandidate =
  (
    !collectionReady &&
    nonDuplicateTrustedCandidates.length >
      0
  )
    ? nonDuplicateTrustedCandidates[0]
    : null;

const nextSourceAvailable =
  Boolean(
    nextCandidate
  );

// ======================================================
// NEXT ACTION
// ======================================================

const searchExhausted =
  (
    input.search_exhausted ===
      true ||
    input.sources_exhausted ===
      true ||
    input.expanded_search_exhausted ===
      true
  );

let nextSourceAction =
  '';

if (
  collectionReady
) {

  nextSourceAction =
    'collection_ready';

} else if (
  nextSourceAvailable
) {

  nextSourceAction =
    'assess_next_source';

} else if (
  searchExhausted
) {

  nextSourceAction =
    'source_search_exhausted';

} else {

  nextSourceAction =
    'expand_search_for_more_sources';
}

// ======================================================
// OUTPUT BASE
// ======================================================

const output = {

  ...input,

  requested_asset_type:
    requestedAssetType,

  asset_type:
    requestedAssetType,

  // ==================================================
  // MERGED COLLECTION
  // ==================================================

  source_packages:
    sourcePackages,

  source_package:
    null,

  source_package_count:
    sourcePackageCount,

  desired_source_count:
    desiredSourceCount,

  actual_source_count:
    sourcePackageCount,

  source_count_shortfall:
    sourceCountShortfall,

  target_video_duration_sec:
    round3(
      targetVideoDurationSec
    ),

  visual_coverage_ratio:
    round3(
      visualCoverageRatio
    ),

  desired_footage_seconds:
    round3(
      desiredFootageSeconds
    ),

  collection_total_footage_seconds:
    round3(
      collectionTotalFootageSeconds
    ),

  total_footage_seconds:
    round3(
      collectionTotalFootageSeconds
    ),

  footage_shortfall_seconds:
    round3(
      footageShortfallSeconds
    ),

  enough_sources:
    enoughSources,

  enough_footage:
    enoughFootage,

  collection_ready:
    collectionReady,

  // ==================================================
  // HISTORY
  // ==================================================

  used_source_urls:
    usedSourceUrls,

  failed_candidate_urls:
    failedCandidateUrls,

  excluded_candidate_urls:
    excludedCandidateUrls,

  // ==================================================
  // CANDIDATES
  // ==================================================

  available_candidate_count:
    availableCandidates.length,

  trusted_candidate_count:
    trustedCandidates.length,

  non_duplicate_trusted_candidate_count:
    nonDuplicateTrustedCandidates.length,

  available_candidates:
    availableCandidates,

  trusted_candidates:
    analyzedTrustedCandidates,

  rejected_content_duplicates:
    analyzedTrustedCandidates.filter(
      candidate =>
        candidate
          .likely_content_duplicate
    ),

  rejected_content_duplicate_count:
    analyzedTrustedCandidates.filter(
      candidate =>
        candidate
          .likely_content_duplicate
    ).length,

  ranked_diverse_candidates:
    nonDuplicateTrustedCandidates,

  next_source_available:
    nextSourceAvailable,

  next_source_action:
    nextSourceAction,

  next_source_candidate:
    nextCandidate,

  prepare_next_source_version:
    '2.0-adaptive-collection-package-merge-safe'
};

// ======================================================
// NEXT CANDIDATE FIELDS
// ======================================================

if (
  nextCandidate
) {

  const nextUrl =
    canonicalizeUrl(
      nextCandidate.url
    );

  const nextTitle =
    clean(
      nextCandidate.title
    );

  const nextChannel =
    clean(
      nextCandidate.channel
    );

  const nextSource =
    clean(
      nextCandidate.source ||
      nextCandidate.platform
    );

  const nextSourceClass =
    clean(
      nextCandidate
        .resolved_source_class
    );

  output.best_result =
    nextCandidate;

  output.candidate_title =
    nextTitle;

  output.candidate_url =
    nextUrl;

  output.candidate_channel =
    nextChannel;

  output.candidate_source =
    nextSource;

  output.candidate_source_class =
    nextSourceClass;

  output.current_candidate = {
    ...nextCandidate,

    title:
      nextTitle,

    url:
      nextUrl,

    channel:
      nextChannel,

    source:
      nextSource,

    source_class:
      nextSourceClass
  };

  output.current_candidate_url =
    nextUrl;

  output.processing_source_title =
    nextTitle;

  output.processing_source_url =
    nextUrl;

  output.processing_source_channel =
    nextChannel;

  output.processing_source_platform =
    nextSource;

  output.processing_source_class =
    nextSourceClass;

  output.source_authenticity_score =
    num(
      nextCandidate
        .resolved_trust_score,
      0
    );

  output.preliminary_source_trust_score =
    num(
      nextCandidate
        .resolved_trust_score,
      0
    );

  output.preliminary_source_verified =
    nextCandidate
      .resolved_verified === true;

  output.rights_status =
    'pending_reassessment';

  output.rights_decision =
    'pending';

  output.requires_rights_reassessment =
    true;

  output.recommended_action =
    'assess_next_source_rights';

} else {

  // There is deliberately NO active candidate.
  // Do not create a fake URL.

  output.best_result =
    null;

  output.current_candidate =
    null;

  output.current_candidate_url =
    '';

  output.candidate_title =
    '';

  output.candidate_url =
    '';

  output.candidate_channel =
    '';

  output.candidate_source =
    '';

  output.candidate_source_class =
    '';

  output.processing_source_title =
    '';

  output.processing_source_url =
    '';

  output.processing_source_channel =
    '';

  output.processing_source_platform =
    '';

  output.processing_source_class =
    '';

  output.requires_rights_reassessment =
    false;

  if (
    collectionReady
  ) {

    output.rights_status =
      'collection_ready';

    output.rights_decision =
      'complete';

    output.recommended_action =
      'continue_with_collected_sources';

  } else {

    output.rights_status =
      'no_candidate';

    output.rights_decision =
      'pending';

    output.recommended_action =
      nextSourceAction;
  }
}

return [
  {
    json:
      output
  }
];

const input = $input.first()?.json || {};

// ======================================================
// PREPARE EDITORIAL COLLECTION
// VERSION: 2.1-adaptive-duration-empty-guard-state-safe
// Mode: Run Once for All Items
// ======================================================

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {
  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {
  return Number(
    num(value).toFixed(3)
  );
}

function clamp(value, min, max) {
  return Math.min(
    max,
    Math.max(
      min,
      value
    )
  );
}

function canonicalizeUrl(value) {

  const raw =
    clean(value);

  if (!raw) {
    return '';
  }

  try {

    const parsed =
      new URL(raw);

    const host =
      parsed.hostname
        .replace(/^www\./, '')
        .replace(/^m\./, '')
        .toLowerCase();

    if (
      host === 'youtube.com' ||
      host === 'youtu.be'
    ) {

      let videoId = '';

      if (
        host === 'youtu.be'
      ) {

        videoId =
          parsed.pathname
            .replace(/^\/+/, '')
            .split('/')[0];

      } else {

        videoId =
          parsed.searchParams.get('v') ||
          '';
      }

      if (videoId) {

        return (
          `https://www.youtube.com/watch?v=${videoId}`
        );
      }
    }

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return raw;
  }
}

function uniqueStrings(values) {

  return [
    ...new Set(
      (
        Array.isArray(values)
          ? values
          : []
      )
        .map(clean)
        .filter(Boolean)
    )
  ];
}

function getClipPath(clip) {

  return clean(
    clip?.final_clip_path ||
    clip?.final_path ||
    clip?.path ||
    clip?.clip_path ||
    clip?.local_path
  );
}

function getClipDuration(clip) {

  const direct =
    num(
      clip?.actual_duration ??
      clip?.duration ??
      clip?.clip_duration ??
      clip?.duration_seconds,
      0
    );

  if (direct > 0) {
    return direct;
  }

  const start =
    num(
      clip?.start_time ??
      clip?.start ??
      clip?.start_sec,
      0
    );

  const end =
    num(
      clip?.end_time ??
      clip?.end ??
      clip?.end_sec,
      0
    );

  if (end > start) {
    return end - start;
  }

  return 0;
}

function getPackageClips(pkg) {

  if (
    Array.isArray(pkg?.clips)
  ) {
    return pkg.clips;
  }

  if (
    Array.isArray(
      pkg?.selected_clips
    )
  ) {
    return pkg.selected_clips;
  }

  if (
    Array.isArray(
      pkg?.editorial_clips
    )
  ) {
    return pkg.editorial_clips;
  }

  if (
    Array.isArray(
      pkg?.extracted_clips
    )
  ) {
    return pkg.extracted_clips;
  }

  return [];
}

// ======================================================
// REQUEST TYPE
// ======================================================

const requestedAssetType =
  clean(
    input.requested_asset_type ||
    input.asset_type ||
    'video'
  )
    .toLowerCase() === 'image'
    ? 'image'
    : 'video';

// ======================================================
// TARGET DURATION
//
// Explicit request always wins.
// 120 seconds remains only the fallback.
// ======================================================

const targetVideoDurationSec =
  Math.max(
    1,
    num(
      input.target_video_duration_sec ??
      input.video_duration_sec ??
      input.requested_duration_sec ??
      input.target_duration_sec,
      120
    )
  );

// ======================================================
// VISUAL COVERAGE
// ======================================================

const visualCoverageRatio =
  clamp(
    num(
      input.visual_coverage_ratio,
      0.70
    ),
    0.10,
    1.00
  );

const desiredFootageSeconds =
  round3(
    num(
      input.desired_footage_seconds,
      targetVideoDurationSec *
      visualCoverageRatio
    )
  );

// ======================================================
// ADAPTIVE SOURCE TARGET
//
// Roughly one independent source per ~35 seconds
// of desired real footage.
//
// 20 sec final @ 70% -> 14 sec -> 1 source
// 120 sec final @ 70% -> 84 sec -> 3 sources
// 180 sec final @ 70% -> 126 sec -> 4 sources
//
// Explicit desired_source_count always wins.
// ======================================================

const SECONDS_PER_DESIRED_SOURCE =
  35;

const automaticDesiredSourceCount =
  clamp(
    Math.ceil(
      desiredFootageSeconds /
      SECONDS_PER_DESIRED_SOURCE
    ),
    1,
    6
  );

const explicitDesiredSourceCount =
  num(
    input.desired_source_count,
    0
  );

const desiredSourceCount =
  explicitDesiredSourceCount > 0
    ? clamp(
        Math.round(
          explicitDesiredSourceCount
        ),
        1,
        8
      )
    : automaticDesiredSourceCount;

// ======================================================
// ADAPTIVE CANDIDATE SAFETY BUDGET
//
// IMPORTANT:
//
// This is NOT a normal stopping target.
// It only protects against runaway loops.
//
// Short videos may still inspect many candidates if
// early candidates fail.
// ======================================================

const automaticCandidateSafetyBudget =
  clamp(
    8 +
    (
      desiredSourceCount * 3
    ),
    12,
    20
  );

const explicitCandidateSafetyBudget =
  num(
    input.max_unique_candidate_attempts,
    0
  );

const maxUniqueCandidateAttempts =
  explicitCandidateSafetyBudget > 0
    ? clamp(
        Math.round(
          explicitCandidateSafetyBudget
        ),
        6,
        30
      )
    : automaticCandidateSafetyBudget;

// ======================================================
// NORMALIZE ONE PACKAGE
// ======================================================

function normalizePackage(
  pkg,
  fallbackIndex = 0
) {

  if (
    !pkg ||
    typeof pkg !== 'object'
  ) {
    return null;
  }

  const sourceUrl =
    canonicalizeUrl(
      pkg.source_url ||
      pkg.candidate_url ||
      pkg.url
    );

  const sourceId =
    clean(
      pkg.source_id ||
      pkg.file_slug ||
      (
        sourceUrl
          ? `source-${fallbackIndex + 1}`
          : ''
      )
    );

  const sourceTitle =
    clean(
      pkg.source_title ||
      pkg.candidate_title ||
      pkg.title
    );

  const sourceChannel =
    clean(
      pkg.source_channel ||
      pkg.candidate_channel ||
      pkg.channel
    );

  const sourceFilePath =
    clean(
      pkg.source_file_path
    );

  const rawClips =
    getPackageClips(
      pkg
    );

  const clips = [];

  for (
    let i = 0;
    i < rawClips.length;
    i++
  ) {

    const clip =
      rawClips[i] || {};

    const path =
      getClipPath(
        clip
      );

    const duration =
      getClipDuration(
        clip
      );

    if (!path) {
      continue;
    }

    if (
      duration <= 0.05
    ) {
      continue;
    }

    const startTime =
      num(
        clip.start_time ??
        clip.start ??
        clip.start_sec,
        0
      );

    const explicitEnd =
      num(
        clip.end_time ??
        clip.end ??
        clip.end_sec,
        NaN
      );

    const endTime =
      Number.isFinite(
        explicitEnd
      )
        ? explicitEnd
        : startTime +
          duration;

    clips.push({

      ...clip,

      source_id:
        clean(
          clip.source_id ||
          sourceId
        ),

      source_url:
        canonicalizeUrl(
          clip.source_url ||
          sourceUrl
        ),

      source_title:
        clean(
          clip.source_title ||
          sourceTitle
        ),

      source_channel:
        clean(
          clip.source_channel ||
          sourceChannel
        ),

      source_file_path:
        clean(
          clip.source_file_path ||
          sourceFilePath
        ),

      order:
        num(
          clip.order,
          i + 1
        ),

      scene_id:
        clean(
          clip.scene_id
        ),

      anchor_time:
        num(
          clip.anchor_time,
          startTime
        ),

      start_time:
        round3(
          startTime
        ),

      duration:
        round3(
          duration
        ),

      end_time:
        round3(
          Math.max(
            startTime,
            endTime
          )
        ),

      path,

      muted:
        clip.muted !== false
    });
  }

  if (
    clips.length === 0
  ) {

    return null;
  }

  const totalFootageSeconds =
    clips.reduce(
      (sum, clip) =>
        sum +
        num(
          clip.duration,
          0
        ),
      0
    );

  return {

    ...pkg,

    source_index:
      fallbackIndex + 1,

    source_id:
      sourceId,

    source_title:
      sourceTitle,

    source_url:
      sourceUrl,

    source_channel:
      sourceChannel,

    source_platform:
      clean(
        pkg.source_platform ||
        pkg.candidate_source ||
        pkg.platform
      ),

    source_class:
      clean(
        pkg.source_class ||
        pkg.candidate_source_class
      ),

    source_file_path:
      sourceFilePath,

    extraction_status:
      clean(
        pkg.extraction_status ||
        'success'
      ),

    clips,

    extracted_clip_count:
      clips.length,

    total_footage_seconds:
      round3(
        totalFootageSeconds
      )
  };
}

// ======================================================
// COLLECT PACKAGE CANDIDATES
// ======================================================

const rawPackages = [];

if (
  Array.isArray(
    input.source_packages
  )
) {

  rawPackages.push(
    ...input.source_packages
  );
}

if (
  rawPackages.length === 0 &&
  Array.isArray(
    input.editorial_source_packages
  )
) {

  rawPackages.push(
    ...input.editorial_source_packages
  );
}

if (
  rawPackages.length === 0 &&
  Array.isArray(
    input.collected_sources
  )
) {

  rawPackages.push(
    ...input.collected_sources
  );
}

if (
  rawPackages.length === 0 &&
  Array.isArray(
    input.sources
  )
) {

  rawPackages.push(
    ...input.sources
  );
}

if (
  input.source_package &&
  typeof input.source_package ===
    'object' &&
  !Array.isArray(
    input.source_package
  )
) {

  rawPackages.push(
    input.source_package
  );
}

// ======================================================
// CURRENT ITEM AS PACKAGE
//
// Critical old bug fix:
//
// clips: [] + source_id/source_url is NOT a source.
// ======================================================

const currentRawClips =
  Array.isArray(
    input.clips
  )
    ? input.clips
    : [];

const currentHasUsableClip =
  currentRawClips.some(
    clip =>
      Boolean(
        getClipPath(
          clip
        )
      ) &&
      getClipDuration(
        clip
      ) > 0.05
  );

if (
  currentHasUsableClip &&
  (
    input.source_id ||
    input.source_url ||
    input.source_title
  )
) {

  rawPackages.push(
    input
  );
}

// ======================================================
// FALLBACK:
// TOP-LEVEL CLIPS MAY ALREADY BE A FLATTENED COLLECTION
// ======================================================

if (
  rawPackages.length === 0 &&
  currentRawClips.length > 0
) {

  const grouped =
    new Map();

  for (
    const clip
    of currentRawClips
  ) {

    const path =
      getClipPath(
        clip
      );

    const duration =
      getClipDuration(
        clip
      );

    if (
      !path ||
      duration <= 0.05
    ) {
      continue;
    }

    const sourceKey =
      canonicalizeUrl(
        clip.source_url
      ) ||
      clean(
        clip.source_id
      ) ||
      `unknown-source-${clip.source_index || 0}`;

    if (
      !grouped.has(
        sourceKey
      )
    ) {

      grouped.set(
        sourceKey,
        {
          source_id:
            clean(
              clip.source_id
            ) ||
            sourceKey,

          source_url:
            canonicalizeUrl(
              clip.source_url
            ),

          source_title:
            clean(
              clip.source_title
            ),

          source_channel:
            clean(
              clip.source_channel
            ),

          source_platform:
            clean(
              clip.source_platform
            ),

          source_class:
            clean(
              clip.source_class
            ),

          source_file_path:
            clean(
              clip.source_file_path
            ),

          clips:
            []
        }
      );
    }

    grouped
      .get(
        sourceKey
      )
      .clips
      .push(
        clip
      );
  }

  rawPackages.push(
    ...grouped.values()
  );
}

// ======================================================
// NORMALIZE
// ======================================================

const normalizedPackages =
  rawPackages
    .map(
      (pkg, index) =>
        normalizePackage(
          pkg,
          index
        )
    )
    .filter(Boolean);

// ======================================================
// DEDUPE SOURCES + MERGE UNIQUE CLIPS
// ======================================================

const sourceMap =
  new Map();

for (
  const pkg
  of normalizedPackages
) {

  const sourceKey =
    pkg.source_url ||
    clean(
      pkg.source_id
    );

  if (!sourceKey) {
    continue;
  }

  if (
    !sourceMap.has(
      sourceKey
    )
  ) {

    sourceMap.set(
      sourceKey,
      {
        ...pkg,
        clips:
          [...pkg.clips]
      }
    );

    continue;
  }

  const existing =
    sourceMap.get(
      sourceKey
    );

  const existingClipKeys =
    new Set(
      existing.clips.map(
        clip =>
          [
            clean(
              clip.path
            ),

            round3(
              clip.start_time
            ),

            round3(
              clip.duration
            )
          ].join('|')
      )
    );

  for (
    const clip
    of pkg.clips
  ) {

    const clipKey =
      [
        clean(
          clip.path
        ),

        round3(
          clip.start_time
        ),

        round3(
          clip.duration
        )
      ].join('|');

    if (
      existingClipKeys.has(
        clipKey
      )
    ) {
      continue;
    }

    existingClipKeys.add(
      clipKey
    );

    existing.clips.push(
      clip
    );
  }

  existing.extracted_clip_count =
    existing.clips.length;

  existing.total_footage_seconds =
    round3(
      existing.clips.reduce(
        (sum, clip) =>
          sum +
          num(
            clip.duration,
            0
          ),
        0
      )
    );
}

const sourcePackages =
  [...sourceMap.values()];

sourcePackages.forEach(
  (pkg, index) => {

    pkg.source_index =
      index + 1;
  }
);

// ======================================================
// FLATTEN CLIPS
// ======================================================

const clips = [];

let globalOrder =
  1;

for (
  const pkg
  of sourcePackages
) {

  for (
    let i = 0;
    i < pkg.clips.length;
    i++
  ) {

    const clip =
      pkg.clips[i];

    const clipUid =
      clean(
        clip.clip_uid
      ) ||
      [
        pkg.source_id ||
        `source-${pkg.source_index}`,

        clean(
          clip.scene_id
        ) ||
        'scene',

        String(
          clip.order ||
          i + 1
        ).padStart(
          2,
          '0'
        )
      ].join('__');

    clips.push({

      ...clip,

      clip_uid:
        clipUid,

      global_order:
        globalOrder++,

      source_index:
        pkg.source_index,

      source_id:
        clean(
          clip.source_id ||
          pkg.source_id
        ),

      source_title:
        clean(
          clip.source_title ||
          pkg.source_title
        ),

      source_url:
        canonicalizeUrl(
          clip.source_url ||
          pkg.source_url
        ),

      source_channel:
        clean(
          clip.source_channel ||
          pkg.source_channel
        ),

      source_platform:
        clean(
          clip.source_platform ||
          pkg.source_platform
        ),

      source_class:
        clean(
          clip.source_class ||
          pkg.source_class
        ),

      source_file_path:
        clean(
          clip.source_file_path ||
          pkg.source_file_path
        ),

      path:
        getClipPath(
          clip
        ),

      duration:
        round3(
          getClipDuration(
            clip
          )
        )
    });
  }
}

// ======================================================
// TOTALS
// ======================================================

const actualSourceCount =
  sourcePackages.length;

const totalFootageSeconds =
  round3(
    clips.reduce(
      (sum, clip) =>
        sum +
        num(
          clip.duration,
          0
        ),
      0
    )
  );

const enoughSources =
  actualSourceCount >=
  desiredSourceCount;

const minimumRealFootageSeconds = targetVideoDurationSec * 1.05;
const enoughFootage = totalFootageSeconds >= minimumRealFootageSeconds;

const collectionReady =
  enoughSources &&
  enoughFootage;

const sourceCountShortfall =
  Math.max(
    0,
    desiredSourceCount -
    actualSourceCount
  );

const footageShortfallSeconds =
  Math.max(
    0,
    desiredFootageSeconds -
    totalFootageSeconds
  );

const footageCoverageRatio =
  desiredFootageSeconds > 0
    ? totalFootageSeconds /
      desiredFootageSeconds
    : 1;

// ======================================================
// SEARCH / COLLECTION EXHAUSTION
// ======================================================

const incomingAction =
  clean(
    input.next_source_action ||
    input.next_collection_action ||
    input.next_action
  );

const sourcesExhausted =
  (
    incomingAction ===
      'trusted_sources_exhausted' ||

    incomingAction ===
      'source_search_exhausted' ||

    input.sources_exhausted ===
      true ||

    input.search_exhausted ===
      true ||

    input.expanded_search_exhausted ===
      true
  );

const hasUsableCollection =
  (
    sourcePackages.length > 0 &&
    clips.length > 0
  );

const partialCollectionAvailable =
  (
    sourcesExhausted &&
    hasUsableCollection &&
    !collectionReady
  );

const terminalEmptyCollection =
  (
    sourcesExhausted &&
    !hasUsableCollection
  );

// ======================================================
// COLLECTION STATUS
// ======================================================

let collectionStatus =
  'incomplete';

if (
  terminalEmptyCollection
) {

  collectionStatus =
    'empty';

} else if (
  collectionReady
) {

  collectionStatus =
    'ready';

} else if (
  sourcesExhausted &&
  !enoughSources &&
  !enoughFootage
) {

  collectionStatus =
    'ready_with_source_and_footage_shortfall';

} else if (
  sourcesExhausted &&
  !enoughSources
) {

  collectionStatus =
    'ready_with_source_shortfall';

} else if (
  sourcesExhausted &&
  !enoughFootage
) {

  collectionStatus =
    'ready_with_footage_shortfall';
}

// ======================================================
// TEMPORAL DEDUP INPUT
// ======================================================

const temporalDedupInput =
  [...clips].sort(
    (a, b) => {

      if (
        a.source_index !==
        b.source_index
      ) {

        return (
          a.source_index -
          b.source_index
        );
      }

      if (
        a.start_time !==
        b.start_time
      ) {

        return (
          a.start_time -
          b.start_time
        );
      }

      return (
        a.global_order -
        b.global_order
      );
    }
  );

const readyForTemporalDedup =
  (
    hasUsableCollection &&
    (
      collectionReady ||
      sourcesExhausted
    )
  );

const requiresVisualSupplement =
  (
    partialCollectionAvailable &&
    footageShortfallSeconds > 0
  );

// ======================================================
// SOURCE URLS
// ======================================================

const sourceUrls =
  uniqueStrings(
    sourcePackages
      .map(
        pkg =>
          canonicalizeUrl(
            pkg.source_url
          )
      )
      .filter(Boolean)
  );

// ======================================================
// ROUTE
// ======================================================

let collectionRoute =
  'collection_incomplete';

if (
  readyForTemporalDedup
) {

  collectionRoute =
    'process_temporal_dedup';

} else if (
  terminalEmptyCollection
) {

  collectionRoute =
    'fallback_no_usable_clips';
}

// ======================================================
// OUTPUT
// ======================================================

const output = {

  // Preserve ALL request/search/retry state.
  ...input,

  requested_asset_type:
    requestedAssetType,

  asset_type:
    requestedAssetType,

  // ==================================================
  // TARGETS
  // ==================================================

  target_video_duration_sec:
    round3(
      targetVideoDurationSec
    ),

  visual_coverage_ratio:
    round3(
      visualCoverageRatio
    ),

  desired_footage_seconds:
    round3(
      desiredFootageSeconds
    ),

  seconds_per_desired_source:
    SECONDS_PER_DESIRED_SOURCE,

  desired_source_count:
    desiredSourceCount,

  // ==================================================
  // ADAPTIVE SAFETY
  // ==================================================

  max_unique_candidate_attempts:
    maxUniqueCandidateAttempts,

  // ==================================================
  // COLLECTION
  // ==================================================

  actual_source_count:
    actualSourceCount,

  source_count_shortfall:
    sourceCountShortfall,

  source_package_count:
    sourcePackages.length,

  total_clip_count:
    clips.length,

  total_footage_seconds:
    round3(
      totalFootageSeconds
    ),

  footage_shortfall_seconds:
    round3(
      footageShortfallSeconds
    ),

  real_footage_target_shortfall_seconds:
    round3(
      footageShortfallSeconds
    ),

  footage_coverage_ratio:
    round3(
      footageCoverageRatio
    ),

  enough_sources:
    enoughSources,

  enough_footage:
    enoughFootage,

  collection_ready:
    collectionReady,

  sources_exhausted:
    sourcesExhausted,

  has_usable_collection:
    hasUsableCollection,

  partial_collection_available:
    partialCollectionAvailable,

  requires_visual_supplement:
    requiresVisualSupplement,

  collection_terminal_failure:
    terminalEmptyCollection,

  collection_status:
    collectionStatus,

  collection_route:
    collectionRoute,

  source_urls:
    sourceUrls,

  source_packages:
    sourcePackages,

  clips,

  temporal_dedup_input:
    temporalDedupInput,

  ready_for_temporal_dedup:
    readyForTemporalDedup,

  editorial_collection_version:
    '2.1-adaptive-duration-empty-guard-state-safe'
};

// ======================================================
// CLEAN TERMINAL FAILURE
// ======================================================

if (
  terminalEmptyCollection
) {

  output.status =
    'failed';

  output.result_type =
    'no_asset';

  output.workflow_outcome =
    'fallback_required';

  output.asset_ready =
    false;

  output.ready_for_assembly =
    false;

  output.ready_for_content_pipeline =
    false;

  output.requires_fallback =
    true;

  output.error =
    'Trusted editorial search was exhausted without producing any usable editorial clips.';

  output.fallback_reason =
    output.error;

  output.recommended_next_action =
    'fallback_no_usable_editorial_clips';
}

return [
  {
    json:
      output
  }
];

const input =
  $input.first().json || {};

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function canonicalizeUrl(value) {

  const raw =
    clean(value);

  if (!raw) {
    return '';
  }

  // --------------------------------------------------
  // YouTube
  // --------------------------------------------------

  const yt =
    raw.match(
      /(?:youtube\.com\/watch\?(?:[^#\s]*&)?v=|youtu\.be\/)([A-Za-z0-9_-]{6,})/i
    );

  if (yt?.[1]) {

    return (
      `https://www.youtube.com/watch?v=${yt[1]}`
