  }

  // --------------------------------------------------
  // Dailymotion
  // --------------------------------------------------

  const dm =
    raw.match(
      /https?:\/\/(?:www\.)?dailymotion\.com\/video\/([A-Za-z0-9]+)/i
    );

  if (dm?.[1]) {

    return (
      `https://www.dailymotion.com/video/${dm[1]}`
    );
  }

  // --------------------------------------------------
  // Generic HTTP URL
  // --------------------------------------------------

  const http =
    raw.match(
      /https?:\/\/[^\s<>"']+/i
    );

  if (!http?.[0]) {
    return '';
  }

  try {

    const parsed =
      new URL(http[0]);

    parsed.hash = '';

    return parsed.toString();

  } catch {

    return http[0];
  }
