  const http =
    raw.match(/https?:\/\/[^\s<>"']+/i);

  if (!http?.[0]) {
    return '';
  }

  try {
    const parsed = new URL(http[0]);
    parsed.hash = '';
    return parsed.toString();
  } catch {
    return http[0];
  }
}

function uniqueCanonicalUrls(values) {
  if (!Array.isArray(values)) {
