const OVERLAP_EPSILON_SECONDS = 0.12;

// Once an overlap has been accepted for removal,
// even a very small individual head/tail trim must be executed.
const PHYSICAL_TRIM_EPSILON_SECONDS = 0.001;

// An overlap covering at least this fraction of the SHORTER clip's own
// duration is treated as "this is really the same moment selected twice",
// not two genuinely distinct-but-adjacent shots -- in that case the
// weaker representative is discarded entirely rather than splitting both
// down the middle and keeping two now-tiny adjacent slivers.
const SUBSTANTIAL_OVERLAP_RATIO = 0.6;

// ======================================================
// HELPERS
