function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function round3(value) {
  return Number(num(value).toFixed(3));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function makeDedupPath(path) {
  const p = clean(path);

  if (!p) {
    return '';
  }

  if (/\.mp4$/i.test(p)) {
    return p.replace(/\.mp4$/i, '-dedup.mp4');
  }

  return `${p}-dedup.mp4`;
}

function buildTrimReason(head, tail) {
  const hasHead =
    head > PHYSICAL_TRIM_EPSILON_SECONDS;

  const hasTail =
    tail > PHYSICAL_TRIM_EPSILON_SECONDS;

  if (hasHead && hasTail) {
    return 'trim_head_and_tail_to_remove_overlap';
  }

  if (hasHead) {
    return 'trim_head_to_remove_overlap';
  }

  if (hasTail) {
    return 'trim_tail_to_remove_overlap';
  }

  return '';
}

