      clip.source_id ||
      clip.source_url ||
      clip.source_title
    );

  const uid =
    clean(clip.clip_uid) ||
    `${sourceKey || 'source'}__${clean(clip.scene_id) || index + 1}__${index + 1}`;

  const originalPath =
    clean(
      clip.original_path ||
      clip.path
    );

  return {
    ...clip,

    clip_uid:
      uid,

    source_key:
      sourceKey,

    original_global_order:
      num(
        clip.original_global_order ??
        clip.global_order,
        index + 1
      ),

    original_start_time:
      round3(originalStart),

    original_end_time:
      round3(originalEnd),

    original_duration:
      round3(originalDuration),

    adjusted_start_time:
      originalStart,

    adjusted_end_time:
      originalEnd,

    trim_head_seconds:
      0,

    trim_tail_seconds:
      0,

    needs_temporal_trim:
      false,

    temporal_trim_reason:
      '',

    dropped_as_near_duplicate:
      false,

    dropped_reason:
      '',

    original_path:
      originalPath,

    dedup_output_path:
      makeDedupPath(originalPath)
  };
});

// ======================================================
// GROUP BY SOURCE
//
// Source timestamps are only comparable inside the
// same source video.
// ======================================================

const groups = new Map();

for (const clip of clips) {

  const key =
    clip.source_key ||
    `unknown-source-${clip.original_global_order}`;

  if (!groups.has(key)) {
    groups.set(key, []);
  }

  groups.get(key).push(clip);
}

// ======================================================
// DETECT + RESOLVE TEMPORAL OVERLAPS
// ======================================================

const detectedOverlaps = [];
const resolvedOverlaps = [];
const unresolvedOverlaps = [];
const discardedClipUids = new Set();

for (const [sourceKey, group] of groups.entries()) {

  group.sort((a, b) => {

    if (
      a.adjusted_start_time !==
      b.adjusted_start_time
    ) {
      return (
        a.adjusted_start_time -
        b.adjusted_start_time
      );
    }

    return (
      a.adjusted_end_time -
      b.adjusted_end_time
    );
  });

  for (let i = 1; i < group.length; i++) {

    const previous =
      group[i - 1];

    const current =
      group[i];

    // A clip already discarded as a near-duplicate of an earlier
    // neighbor in this same source cannot itself be a "previous" for
    // further comparisons -- skip forward to the last surviving clip.
    if (discardedClipUids.has(previous.clip_uid)) {
      continue;
    }

    if (discardedClipUids.has(current.clip_uid)) {
      continue;
    }

    const overlapStart =
      Math.max(
        previous.adjusted_start_time,
        current.adjusted_start_time
      );

    const overlapEnd =
      Math.min(
        previous.adjusted_end_time,
        current.adjusted_end_time
      );

    const overlapSeconds =
      overlapEnd - overlapStart;

    if (
      overlapSeconds <=
      OVERLAP_EPSILON_SECONDS
    ) {
      continue;
    }

    const overlapInfo = {

      source_key:
        sourceKey,

      previous_clip_uid:
        previous.clip_uid,

      current_clip_uid:
        current.clip_uid,

      previous_scene_id:
        clean(previous.scene_id),

      current_scene_id:
        clean(current.scene_id),

      overlap_start:
        round3(overlapStart),

      overlap_end:
        round3(overlapEnd),

      overlap_seconds:
        round3(overlapSeconds)
    };

    detectedOverlaps.push(
      overlapInfo
    );

    // ==================================================
    // SUBSTANTIAL OVERLAP -- SAME MOMENT SELECTED TWICE
    //
    // Covers both full containment (current entirely inside previous,
    // or vice versa) and any partial overlap that consumes most of the
    // shorter clip's own duration. Discard the weaker representative
    // entirely instead of splitting both into two tiny adjacent slivers.
    // "Stronger" is judged by validated stable duration (the strongest
    // quality signal already available at this pipeline stage -- visual/
    // semantic scores are not attached to clips until later).
    // ==================================================

    const previousDuration =
      previous.adjusted_end_time - previous.adjusted_start_time;

    const currentDuration =
      current.adjusted_end_time - current.adjusted_start_time;

    const shorterDuration =
      Math.min(previousDuration, currentDuration);

    const substantial =
      shorterDuration > 0 &&
      (overlapSeconds / shorterDuration) >= SUBSTANTIAL_OVERLAP_RATIO;

    if (substantial) {

      const keepPrevious =
        previousDuration >= currentDuration;

      const loser =
        keepPrevious ? current : previous;

      const winner =
        keepPrevious ? previous : current;

      discardedClipUids.add(loser.clip_uid);

      loser.dropped_as_near_duplicate = true;
      loser.dropped_reason = 'substantial_same_source_overlap_kept_stronger_representative';

      resolvedOverlaps.push({

        ...overlapInfo,

        resolution:
          'discarded_weaker_representative',

        kept_clip_uid:
          winner.clip_uid,

        discarded_clip_uid:
          loser.clip_uid,

        overlap_ratio_of_shorter_clip:
          round3(overlapSeconds / shorterDuration)
      });

      continue;
    }

    // ==================================================
    // GENUINE PARTIAL OVERLAP
    //
    // Two otherwise-distinct adjacent shots with a small timing overlap:
    // preserve the existing split-at-midpoint behavior, protecting a
    // minimum viable duration on both sides.
    // ==================================================

    const preferredBoundary =
      (
        overlapStart +
        overlapEnd
      ) / 2;

    const minimumBoundary =
      previous.adjusted_start_time +
      MIN_FINAL_CLIP_SECONDS;

    const maximumBoundary =
      current.adjusted_end_time -
      MIN_FINAL_CLIP_SECONDS;

    const validBoundaryLow =
      Math.max(
        overlapStart,
        minimumBoundary
      );

    const validBoundaryHigh =
      Math.min(
        overlapEnd,
        maximumBoundary
      );

    // If both clips cannot safely survive the trim,
    // preserve them instead of deleting one.
    if (
      validBoundaryLow >
      validBoundaryHigh
    ) {

      unresolvedOverlaps.push({
        ...overlapInfo,

        reason:
          'minimum_clip_duration_protection'
      });

      continue;
    }

    const boundary =
      clamp(
        preferredBoundary,
        validBoundaryLow,
        validBoundaryHigh
      );

    const oldPreviousEnd =
      previous.adjusted_end_time;

    const oldCurrentStart =
      current.adjusted_start_time;

    previous.adjusted_end_time =
      boundary;

    current.adjusted_start_time =
      boundary;

    resolvedOverlaps.push({

      ...overlapInfo,

      resolution:
        'split_at_boundary',

      split_boundary:
        round3(boundary),

      previous_tail_removed_seconds:
        round3(
          oldPreviousEnd -
          boundary
        ),

      current_head_removed_seconds:
        round3(
          boundary -
          oldCurrentStart
        )
    });
  }
}

// ======================================================
// FINALIZE CLIP TRIM INFORMATION
// (discarded near-duplicates are excluded here)
// ======================================================

const survivingClips =
  clips.filter(
    clip => !discardedClipUids.has(clip.clip_uid)
  );

const discardedClips =
  clips.filter(
    clip => discardedClipUids.has(clip.clip_uid)
  );

const finalClips =
  survivingClips
    .sort(
      (a, b) =>
        a.original_global_order -
        b.original_global_order
    )
    .map((clip, index) => {

      const adjustedDuration =
        Math.max(
          0,
          clip.adjusted_end_time -
          clip.adjusted_start_time
        );

      const trimHead =
        Math.max(
          0,
          clip.adjusted_start_time -
          clip.original_start_time
        );

      const trimTail =
        Math.max(
          0,
          clip.original_end_time -
          clip.adjusted_end_time
        );

      const needsTrim =
        (
          trimHead >
            PHYSICAL_TRIM_EPSILON_SECONDS ||
          trimTail >
            PHYSICAL_TRIM_EPSILON_SECONDS
        );

      const trimReason =
        buildTrimReason(
          trimHead,
          trimTail
        );

      const originalPath =
        clean(
          clip.original_path ||
          clip.path
        );

      const dedupPath =
        makeDedupPath(
          originalPath
        );

      return {

        ...clip,

        global_order:
          index + 1,

        start_time:
          round3(
            clip.adjusted_start_time
          ),

        end_time:
          round3(
            clip.adjusted_end_time
          ),

        duration:
          round3(
            adjustedDuration
          ),

        adjusted_start_time:
          round3(
            clip.adjusted_start_time
          ),

        adjusted_end_time:
          round3(
            clip.adjusted_end_time
          ),

        adjusted_duration:
          round3(
            adjustedDuration
          ),

        trim_head_seconds:
          round3(
            trimHead
          ),

        trim_tail_seconds:
          round3(
            trimTail
          ),

        needs_temporal_trim:
          needsTrim,

        temporal_trim_reason:
          trimReason,

        original_path:
          originalPath,

        dedup_output_path:
          dedupPath,

        // These three fields are specifically for FFmpeg.
        physical_trim_start_offset_seconds:
          round3(
            trimHead
          ),

        physical_trim_duration_seconds:
          round3(
            adjustedDuration
          ),

        physical_trim_tail_removed_seconds:
          round3(
            trimTail
          ),

        final_path:
          needsTrim
            ? dedupPath
            : originalPath
      };
    });

// ======================================================
// FOOTAGE CALCULATION
// ======================================================

const footageBefore =
  clips.reduce(
    (sum, clip) =>
      sum +
      num(
        clip.original_duration
      ),
    0
  );

const footageAfter =
  finalClips.reduce(
    (sum, clip) =>
      sum +
      num(
        clip.adjusted_duration
      ),
    0
  );

const overlapRemovedSeconds =
  Math.max(
    0,
    footageBefore -
    footageAfter
  );

const enoughFootage =
  desiredFootageSeconds <= 0 ||
  footageAfter >=
    desiredFootageSeconds;

const footageShortfallSeconds =
  Math.max(
    0,
    desiredFootageSeconds -
    footageAfter
  );

const footageCoverageRatio =
  desiredFootageSeconds > 0
    ? footageAfter /
      desiredFootageSeconds
    : 0;

const clipsNeedingPhysicalTrim =
  finalClips.filter(
    clip =>
      clip.needs_temporal_trim
  );

// ======================================================
// FFmpeg TRIM PLAN
// ======================================================

const physicalTrimPlan =
  clipsNeedingPhysicalTrim.map(
    clip => ({
      clip_uid:
        clip.clip_uid,

      global_order:
        clip.global_order,

      source_id:
        clip.source_id,

      scene_id:
        clip.scene_id,

      input_path:
        clip.original_path,

      output_path:
        clip.final_path,

      trim_head_seconds:
        clip.trim_head_seconds,

      trim_tail_seconds:
        clip.trim_tail_seconds,

      start_offset_seconds:
        clip.physical_trim_start_offset_seconds,

      output_duration_seconds:
        clip.physical_trim_duration_seconds,

      reason:
        clip.temporal_trim_reason
    })
  );

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      ...input,

      clips_before_temporal_dedup:
        rawClips,

      clips_before_temporal_dedup_count:
        rawClips.length,

      detected_temporal_overlaps:
        detectedOverlaps,

      detected_temporal_overlap_count:
        detectedOverlaps.length,

      resolved_temporal_overlaps:
        resolvedOverlaps,

      resolved_temporal_overlap_count:
        resolvedOverlaps.length,

      unresolved_temporal_overlaps:
        unresolvedOverlaps,

      unresolved_temporal_overlap_count:
        unresolvedOverlaps.length,

      discarded_near_duplicate_clips:
        discardedClips.map(c => ({
          clip_uid: c.clip_uid,
          source_key: c.source_key,
          scene_id: c.scene_id,
          original_start_time: c.original_start_time,
          original_end_time: c.original_end_time,
          reason: c.dropped_reason,
        })),

      discarded_near_duplicate_count:
        discardedClips.length,

      clips:
        finalClips,

      temporal_dedup_input:
        finalClips,

      clips_needing_physical_trim:
        clipsNeedingPhysicalTrim,

      clips_needing_physical_trim_count:
        clipsNeedingPhysicalTrim.length,

      physical_trim_plan:
        physicalTrimPlan,

      physical_trim_plan_count:
        physicalTrimPlan.length,

      total_clip_count:
        finalClips.length,

      footage_before_temporal_dedup_seconds:
        round3(
          footageBefore
        ),

      total_footage_seconds:
        round3(
          footageAfter
        ),

      overlap_removed_seconds:
        round3(
          overlapRemovedSeconds
        ),

      footage_shortfall_seconds:
        round3(
          footageShortfallSeconds
        ),

      footage_coverage_ratio:
        round3(
          footageCoverageRatio
        ),

      enough_footage:
        enoughFootage,

      // No longer always zero: a substantial-overlap duplicate is now
      // genuinely discarded (keeping the single stronger representative
      // instead of splitting both into tiny adjacent slivers). See
      // discarded_near_duplicate_count / discarded_near_duplicate_clips.
      deleted_clip_count:
        discardedClips.length,

      temporal_dedup_status:
        unresolvedOverlaps.length > 0
          ? 'trim_plan_ready_with_preserved_complex_overlaps'
          : 'trim_plan_ready',

      ready_for_physical_trim:
        clipsNeedingPhysicalTrim.length > 0,

      ready_for_final_clip_selection:
        (
          clipsNeedingPhysicalTrim.length === 0 &&
          enoughFootage
        ),

      temporal_dedup_version:
        '3.0-keep-best-discard-weaker'
    }
  }
];

parameters.command:
=PLAN_FILE="/tmp/temporal-trim-plan-$$.json"

cat > "$PLAN_FILE" <<'JSON'
{{ JSON.stringify($json.physical_trim_plan || []) }}
JSON

node - "$PLAN_FILE" <<'NODE'

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const planPath = process.argv[2];

// ======================================================
// HELPERS
// VERSION: 1.1-fail-safe
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {

  return Math.round(
    num(value) * 1000
  ) / 1000;
}

function printSummary(summary) {

  console.log(
    `TRIM_STATUS=${clean(summary.status)}`
  );

  console.log(
    `REQUESTED_TRIM_COUNT=${num(summary.requested_trim_count, 0)}`
  );

  console.log(
    `SUCCESSFUL_TRIM_COUNT=${num(summary.successful_trim_count, 0)}`
  );

  console.log(
    `FAILED_TRIM_COUNT=${num(summary.failed_trim_count, 0)}`
  );

  console.log(
    `ACTUAL_TRIMMED_FOOTAGE_SECONDS=${round3(summary.actual_trimmed_footage_seconds)}`
  );

  console.log(
    'TEMPORAL_TRIM_RESULT_JSON=' +
    JSON.stringify(summary)
  );
}

function buildPlanFailureResults(
  plan,
  error
) {

  return (
    Array.isArray(plan)
      ? plan
      : []
  ).map(
    item => ({

      clip_uid:
        clean(item?.clip_uid),

      global_order:
        num(
          item?.global_order,
          0
        ),

      source_id:
        clean(
          item?.source_id
        ),

      scene_id:
        clean(
          item?.scene_id
        ),

      input_path:
        clean(
          item?.input_path
        ),

      output_path:
        clean(
          item?.output_path
        ),

      trim_head_seconds:
        round3(
          item?.trim_head_seconds
        ),

      trim_tail_seconds:
        round3(
          item?.trim_tail_seconds
        ),

      start_offset_seconds:
        round3(
          item?.start_offset_seconds
        ),

      requested_output_duration_seconds:
        round3(
          item?.output_duration_seconds
        ),

      actual_output_duration_seconds:
        0,

      duration_difference_seconds:
        0,

      file_size_bytes:
        0,

      reason:
        clean(
          item?.reason
        ),

      status:
        'failed',

      error:
        clean(error)
    })
  );
}

function structuredFatal(
  message,
  plan = []
) {

  const results =
    buildPlanFailureResults(
      plan,
      message
    );

  const summary = {

    status:
      'failed',

    fatal_error:
      clean(message),

    requested_trim_count:
      Array.isArray(plan)
        ? plan.length
        : 0,

    successful_trim_count:
      0,

    failed_trim_count:
      results.length,

    requested_trimmed_footage_seconds:
      round3(
        results.reduce(
          (sum, item) =>
            sum +
            num(
              item.requested_output_duration_seconds,
              0
            ),
          0
        )
      ),

    actual_trimmed_footage_seconds:
      0,

    all_trimmed_files_ready:
      false,

    results,

    physical_trim_version:
      '1.1-fail-safe'
  };

  printSummary(summary);

  process.exit(0);
}

// ======================================================
// READ PLAN
// ======================================================

if (
  !planPath ||
  !fs.existsSync(planPath)
) {

  structuredFatal(
    'physical_trim_plan_file_missing',
    []
  );
}

let plan;

try {

  plan =
    JSON.parse(
      fs.readFileSync(
        planPath,
        'utf8'
      )
    );

} catch (error) {

  structuredFatal(
    `invalid_trim_plan_json: ${error.message}`,
    []
  );
}

if (!Array.isArray(plan)) {

  structuredFatal(
    'physical_trim_plan_must_be_array',
    []
  );
}

// ======================================================
// NO TRIM REQUIRED
// ======================================================

if (plan.length === 0) {

  const summary = {

    status:
      'no_trim_required',

    requested_trim_count:
      0,

    successful_trim_count:
      0,

    failed_trim_count:
      0,

    requested_trimmed_footage_seconds:
      0,

    actual_trimmed_footage_seconds:
      0,

    all_trimmed_files_ready:
      true,

    results:
      [],

    physical_trim_version:
      '1.1-fail-safe'
  };

  printSummary(summary);

  process.exit(0);
}

// ======================================================
// CHECK FFMPEG
// ======================================================

const ffmpegCheck =
  spawnSync(
    'ffmpeg',
    [
      '-version'
    ],
    {
      encoding:
        'utf8',

      maxBuffer:
        20 * 1024 * 1024
    }
  );

if (
  ffmpegCheck.status !== 0
) {

  structuredFatal(
    'ffmpeg_not_available',
    plan
  );
}

const ffprobeCheck =
  spawnSync(
    'ffprobe',
    [
      '-version'
    ],
    {
      encoding:
        'utf8',

      maxBuffer:
        20 * 1024 * 1024
    }
  );

if (
  ffprobeCheck.status !== 0
) {

  structuredFatal(
    'ffprobe_not_available',
    plan
  );
}

// ======================================================
// APPLY TRIMS
// ======================================================

const results = [];

let successCount = 0;
let failureCount = 0;

let requestedOutputDuration = 0;
let actualOutputDuration = 0;

for (const item of plan) {

  const clipUid =
    clean(
      item?.clip_uid
    );

  const inputPath =
    clean(
      item?.input_path
    );

  const outputPath =
    clean(
      item?.output_path
    );

  const startOffset =
    Math.max(
      0,
      num(
        item?.start_offset_seconds,
        0
      )
    );

  const outputDuration =
    Math.max(
      0,
      num(
        item?.output_duration_seconds,
        0
      )
    );

  requestedOutputDuration +=
    outputDuration;

  const result = {

    clip_uid:
      clipUid,

    global_order:
      num(
        item?.global_order,
        0
      ),

    source_id:
      clean(
        item?.source_id
      ),

    scene_id:
      clean(
        item?.scene_id
      ),

    input_path:
      inputPath,

    output_path:
      outputPath,

    trim_head_seconds:
      round3(
        item?.trim_head_seconds
      ),

    trim_tail_seconds:
      round3(
        item?.trim_tail_seconds
      ),

    start_offset_seconds:
      round3(
        startOffset
      ),

    requested_output_duration_seconds:
      round3(
        outputDuration
      ),

    actual_output_duration_seconds:
      0,

    duration_difference_seconds:
      0,

    file_size_bytes:
      0,

    reason:
      clean(
        item?.reason
      ),

    status:
      'pending',

    error:
      ''
  };

  // ==================================================
  // VALIDATION
  // ==================================================

  if (!clipUid) {

    result.status =
      'failed';

    result.error =
      'clip_uid_missing';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  if (!inputPath) {

    result.status =
      'failed';

    result.error =
      'input_path_missing';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  if (!outputPath) {

    result.status =
      'failed';

    result.error =
      'output_path_missing';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  if (
    !fs.existsSync(
      inputPath
    )
  ) {

    result.status =
      'failed';

    result.error =
      'input_file_not_found';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  if (
    outputDuration <= 0.05
  ) {

    result.status =
      'failed';

    result.error =
      'invalid_output_duration';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  // ==================================================
  // OUTPUT DIRECTORY
  // ==================================================

  try {

    fs.mkdirSync(
      path.dirname(
        outputPath
      ),
      {
        recursive:
          true
      }
    );

  } catch (error) {

    result.status =
      'failed';

    result.error =
      `cannot_create_output_directory: ${error.message}`;

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  // ==================================================
  // REMOVE OLD OUTPUT
  // ==================================================

  try {

    if (
      fs.existsSync(
        outputPath
      )
    ) {

      fs.unlinkSync(
        outputPath
      );
    }

  } catch (error) {

    result.status =
      'failed';

    result.error =
      `cannot_remove_old_output: ${error.message}`;

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  // ==================================================
  // FFMPEG
  // ==================================================

  const ffmpegArgs = [

    '-hide_banner',

    '-loglevel',
    'error',

    '-y',

    '-i',
    inputPath,

    '-ss',
    startOffset.toFixed(3),

    '-t',
    outputDuration.toFixed(3),

    '-map',
    '0:v:0',

    '-an',

    '-c:v',
    'libx264',

    '-preset',
    'veryfast',

    '-crf',
    '18',

    '-pix_fmt',
    'yuv420p',

    '-movflags',
    '+faststart',

    outputPath
  ];

  const ffmpeg =
    spawnSync(
      'ffmpeg',
      ffmpegArgs,
      {
        encoding:
          'utf8',

        maxBuffer:
          100 * 1024 * 1024
      }
    );

  if (
    ffmpeg.status !== 0
  ) {

    result.status =
      'failed';

    result.error =
      clean(
        ffmpeg.stderr ||
        ffmpeg.stdout ||
        'ffmpeg_failed'
      )
        .slice(
          0,
          4000
        );

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  // ==================================================
  // FILE CHECK
  // ==================================================

  if (
    !fs.existsSync(
      outputPath
    )
  ) {

    result.status =
      'failed';

    result.error =
      'ffmpeg_finished_but_output_missing';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  const outputStat =
    fs.statSync(
      outputPath
    );

  if (
    outputStat.size <= 1000
  ) {

    result.status =
      'failed';

    result.error =
      'output_file_too_small';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  // ==================================================
  // FFPROBE
  // ==================================================

  const probe =
    spawnSync(
      'ffprobe',
      [
        '-v',
        'error',

        '-show_entries',
        'format=duration',

        '-of',
        'default=noprint_wrappers=1:nokey=1',

        outputPath
      ],
      {
        encoding:
          'utf8',

        maxBuffer:
          20 * 1024 * 1024
      }
    );

  if (
    probe.status !== 0
  ) {

    result.status =
      'failed';

    result.error =
      `ffprobe_failed: ${clean(probe.stderr)}`;

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  const actualDuration =
    num(
      clean(
        probe.stdout
      ),
      0
    );

  result.actual_output_duration_seconds =
    round3(
      actualDuration
    );

  const durationDifference =
    Math.abs(
      actualDuration -
      outputDuration
    );

  result.duration_difference_seconds =
    round3(
      durationDifference
    );

  if (
    actualDuration <= 0.05
  ) {

    result.status =
      'failed';

    result.error =
      'invalid_trimmed_duration';

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  if (
    durationDifference > 0.35
  ) {

    result.status =
      'failed';

    result.error =
      (
        `duration_mismatch_expected_` +
        `${round3(outputDuration)}_actual_` +
        `${round3(actualDuration)}`
      );

    failureCount++;

    results.push(
      result
    );

    continue;
  }

  // ==================================================
  // SUCCESS
  // ==================================================

  result.status =
    'success';

  result.file_size_bytes =
    outputStat.size;

  successCount++;

  actualOutputDuration +=
    actualDuration;

  results.push(
    result
  );
}

// ======================================================
// FINAL STATUS
// ======================================================

let finalStatus =
  'success';

if (
  failureCount > 0 &&
  successCount > 0
) {

  finalStatus =
    'partial_failure';

} else if (
  failureCount > 0
) {

  finalStatus =
    'failed';
}

const summary = {

  status:
    finalStatus,

  requested_trim_count:
    plan.length,

  successful_trim_count:
    successCount,

  failed_trim_count:
    failureCount,

  requested_trimmed_footage_seconds:
    round3(
      requestedOutputDuration
    ),

  actual_trimmed_footage_seconds:
    round3(
      actualOutputDuration
    ),

  all_trimmed_files_ready:
    (
      failureCount === 0 &&
      successCount === plan.length
    ),

  results,

  physical_trim_version:
    '1.1-fail-safe'
};

printSummary(
  summary
);

// ======================================================
// IMPORTANT:
// Never crash n8n because one trim failed.
// Parser/Rebuild handles structured failure.
// ======================================================

process.exit(0);

