// ======================================================

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function toNumber(
  value,
  fallback = 0
) {

  const n =
    Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function toBoolean(
  value,
  fallback = false
) {

  if (
    value === true ||
    value === false
  ) {
    return value;
  }

  const text =
    clean(value)
      .toLowerCase();

  if (
    text === 'true'
  ) {
    return true;
  }

  if (
    text === 'false'
  ) {
    return false;
  }

  return fallback;
}

// ======================================================
// COMMAND OUTPUT
// ======================================================

const exitCode =
  toNumber(
    input.exitCode,
    0
  );

const stderr =
  clean(
    input.stderr
  );

const stdout =
  clean(
    input.stdout
  );

// ======================================================
// READ KEY=VALUE
// ======================================================

function readLineValue(
  key
) {

  const expression =
    new RegExp(
      `(?:^|\\n)${key}=([^\\r\\n]*)`
    );

  const match =
    stdout.match(
      expression
    );

  return match?.[1]
    ? clean(
        match[1]
      )
    : '';
}

