  toNumber(
    readLineValue(
      'SUCCESSFUL_TRIM_COUNT'
    ),
    0
  );

const failedTrimCount =
  toNumber(
    readLineValue(
      'FAILED_TRIM_COUNT'
    ),
    0
  );

const actualTrimmedFootageSeconds =
  toNumber(
    readLineValue(
      'ACTUAL_TRIMMED_FOOTAGE_SECONDS'
    ),
    0
  );

// ======================================================
// STRUCTURED JSON
// ======================================================

let trimResult = null;

const jsonLine =
  stdout
    .split(/\r?\n/)
    .find(
      line =>
        line.startsWith(
          'TEMPORAL_TRIM_RESULT_JSON='
        )
