const failedResults =
  results.filter(
    item =>
      clean(
        item?.status
      ).toLowerCase() !==
        'success'
  );

// ======================================================
// NO TRIM CASE
// ======================================================

const normalizedResultStatus =
  clean(
    trimResult?.status ||
    trimStatus
