// IMPORTANT:
// Includes BOTH success and failure results.
// ======================================================

const trimResultByClipUid =
  {};

for (const item of results) {

  const clipUid =
    clean(
      item?.clip_uid
    );

  if (!clipUid) {
    continue;
  }

  trimResultByClipUid[
    clipUid
  ] = {

    clip_uid:
      clipUid,

    global_order:
      toNumber(
        item?.global_order,
        0
      ),

    source_id:
      clean(
        item?.source_id
      ),

    scene_id:
      clean(
        item?.scene_id
      ),

    original_path:
      clean(
        item?.input_path
      ),

    trimmed_path:
      clean(
        item?.output_path
      ),

    trim_head_seconds:
      toNumber(
        item?.trim_head_seconds,
        0
      ),

    trim_tail_seconds:
      toNumber(
        item?.trim_tail_seconds,
        0
      ),

    requested_duration_seconds:
      toNumber(
        item
          ?.requested_output_duration_seconds,
        0
      ),

    actual_duration_seconds:
      toNumber(
        item
          ?.actual_output_duration_seconds,
        0
      ),

    duration_difference_seconds:
      toNumber(
        item
          ?.duration_difference_seconds,
        0
      ),

    file_size_bytes:
      toNumber(
        item?.file_size_bytes,
        0
      ),

    reason:
      clean(
        item?.reason
      ),

    error:
      clean(
        item?.error
      ),

    status:
      clean(
        item?.status
      )
        .toLowerCase()
  };
}

// ======================================================
// VALIDATION
// ======================================================

let parseStatus =
  'success';

let readyForClipRebuild =
  true;

let parseFailureReason =
  '';

if (
  exitCode !== 0
) {

  parseStatus =
    'failed';

  readyForClipRebuild =
    false;

  parseFailureReason =
    `execute_command_exit_code_${exitCode}`;

} else if (
  !trimResult
