  parseStatus =
    'failed';

  readyForClipRebuild =
    false;

  parseFailureReason =
    'trim_result_json_parse_error';

} else if (
  normalizedResultStatus ===
    'failed'
) {

  parseStatus =
    'failed';

  readyForClipRebuild =
    false;

  parseFailureReason =
    clean(
      trimResult?.fatal_error
    ) ||
    'physical_trim_failed';

} else if (
  normalizedResultStatus ===
    'partial_failure'
) {

  parseStatus =
    'failed';

  readyForClipRebuild =
    false;

  parseFailureReason =
    'one_or_more_physical_trims_failed';

} else if (
  !allTrimmedFilesReady
) {

  parseStatus =
    'failed';

  readyForClipRebuild =
    false;

  parseFailureReason =
    'not_all_trimmed_files_ready';

} else if (
  !noTrimRequired &&
  successfulResults.length !==
    requestedTrimCount
) {

  parseStatus =
    'failed';

  readyForClipRebuild =
    false;

  parseFailureReason =
    'trim_result_count_mismatch';
}

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      ffmpeg_exit_code:
        exitCode,

      ffmpeg_stderr:
        stderr,

      ffmpeg_stdout:
        stdout,

      trim_status:
