      no_trim_required:
        noTrimRequired,

      requested_trim_count:
        requestedTrimCount,

      successful_trim_count:
        successfulTrimCount,

      failed_trim_count:
        failedTrimCount,

      actual_trimmed_footage_seconds:
        actualTrimmedFootageSeconds,

      requested_trimmed_footage_seconds:
        toNumber(
          trimResult
            ?.requested_trimmed_footage_seconds,
          0
        ),

      all_trimmed_files_ready:
        allTrimmedFilesReady,

      trim_results:
        results,

      successful_trim_results:
        successfulResults,

      failed_trim_results:
        failedResults,

      trim_result_by_clip_uid:
        trimResultByClipUid,

      physical_trim_version:
        clean(
          trimResult
