const input = $input.first()?.json || {};

// ======================================================
// REBUILD FINAL EDITORIAL CLIPS
// VERSION: 1.2-fail-safe-per-clip-trim-aware
// ======================================================

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {
  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {
  return Number(
    num(value).toFixed(3)
  );
}

function bool(value, fallback = false) {

  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }

  const text =
    clean(value).toLowerCase();

  if (text === 'true') {
    return true;
  }

  if (text === 'false') {
    return false;
  }

  return fallback;
}

function uniqueStrings(values) {

  return [
    ...new Set(
      (
        Array.isArray(values)
          ? values
          : []
      )
        .map(clean)
        .filter(Boolean)
    )
  ];
}

// ======================================================
// REQUEST TYPE
// ======================================================

const requestedAssetType =
  clean(
    input.requested_asset_type ||
    input.asset_type ||
    'video'
  )
    .toLowerCase() === 'image'
    ? 'image'
    : 'video';

// ======================================================
// INPUT CLIPS
// ======================================================

const clips =
  Array.isArray(input.clips)
    ? input.clips
    : (
        Array.isArray(
          input.temporal_dedup_input
        )
          ? input.temporal_dedup_input
          : []
      );

const trimMap =
  (
    input.trim_result_by_clip_uid &&
    typeof input.trim_result_by_clip_uid ===
      'object' &&
    !Array.isArray(
      input.trim_result_by_clip_uid
    )
  )
    ? input.trim_result_by_clip_uid
    : {};

const desiredFootageSeconds =
  num(
    input.desired_footage_seconds,
    0
  );

const desiredSourceCount =
  Math.max(
    1,
    num(
      input.desired_source_count,
      3
    )
  );

const actualSourceCount =
  Math.max(
    0,
    num(
      input.actual_source_count,
      uniqueStrings(
        clips.map(
          clip =>
            clip?.source_id ||
            clip?.source_url
        )
      ).length
    )
  );

// ======================================================
// EMPTY INPUT â€” CLEAN FAILURE, NEVER THROW
// ======================================================

if (
  clips.length === 0
) {

  return [
    {
      json: {

        ...input,

        requested_asset_type:
          requestedAssetType,

        asset_type:
          requestedAssetType,

        status:
          'failed',

        result_type:
          'no_asset',

        workflow_outcome:
          'fallback_required',

        asset_ready:
          false,

        ready_for_assembly:
          false,

        ready_for_content_pipeline:
          false,

        requires_fallback:
          true,

        requires_visual_supplement:
          false,

        clips:
          [],

        final_editorial_clips:
          [],

        assembly_clips:
          [],

        total_clip_count:
          0,

        trimmed_clip_count:
          0,

        untouched_clip_count:
          0,

        failed_trim_clip_count:
          0,

        final_footage_seconds:
          0,

        total_footage_seconds:
          0,

        desired_footage_seconds:
          round3(
            desiredFootageSeconds
          ),

        footage_shortfall_seconds:
          round3(
            desiredFootageSeconds
          ),

        real_footage_target_shortfall_seconds:
          round3(
            desiredFootageSeconds
          ),

        footage_coverage_ratio:
          0,

        enough_footage:
          false,

        enough_sources:
          false,

        partial_collection_ready:
          false,

        complete_collection_ready:
          false,

        missing_final_files:
          [],

        missing_final_file_count:
          0,

        all_final_clip_paths_ready:
          false,

        ready_for_final_clip_selection:
          false,

        final_clip_rebuild_status:
          'empty_collection',

        collection_terminal_failure:
          true,

        error:
          clean(
            input.error ||
            input.fallback_reason ||
            'No usable editorial clips were available for final rebuild.'
          ),

        fallback_reason:
          clean(
            input.fallback_reason ||
            input.error ||
            'No usable editorial clips were available for final rebuild.'
          ),

        recommended_next_action:
          'fallback_no_usable_editorial_clips',

        final_clip_rebuild_version:
          '1.2-fail-safe-per-clip-trim-aware'
