// ======================================================
// REBUILD PER CLIP
//
// Important:
// We no longer trust one global "trim ready" flag.
// Each clip is evaluated individually.
// ======================================================

let trimmedClipCount = 0;
let untouchedClipCount = 0;
let failedTrimClipCount = 0;

const failedTrimClips = [];

const rebuiltClips =
  clips.map(
    (clip, index) => {

      const clipUid =
        clean(
          clip?.clip_uid
        );

      const needsTrim =
        clip?.needs_temporal_trim === true ||
        num(
          clip?.trim_head_seconds,
          0
        ) > 0.001 ||
