          ...clip,

          global_order:
            index + 1,

          original_clip_path:
            clean(
              trimResult.original_path ||
              clip?.original_path ||
              clip?.path
            ),

          path:
            trimmedPath,

          final_path:
            trimmedPath,

          final_clip_path:
            trimmedPath,

          duration:
            round3(
              actualDuration
            ),

          actual_duration:
            round3(
              actualDuration
            ),

          planned_duration:
            round3(
              trimResult
                .requested_duration_seconds ??
              clip?.duration
            ),

          trim_head_seconds:
            round3(
              trimResult
                .trim_head_seconds ??
              clip?.trim_head_seconds
            ),

          trim_tail_seconds:
            round3(
              trimResult
                .trim_tail_seconds ??
              clip?.trim_tail_seconds
            ),

          temporal_trim_applied:
            true,

          temporal_trim_status:
            'success',

          final_file_ready:
            true,

          final_file_size_bytes:
            num(
              trimResult
                .file_size_bytes,
              0
            )
        };
      }

      // ==================================================
      // TRIM REQUIRED + FAILED/MISSING
      //
      // Do NOT silently use the overlapping original.
      // Mark clip invalid instead of crashing workflow.
      // ==================================================

      if (
        needsTrim &&
        !trimSucceeded
      ) {

        failedTrimClipCount++;

        const failure = {

          clip_uid:
            clipUid,

          global_order:
            index + 1,

          source_id:
            clean(
              clip?.source_id
            ),

          scene_id:
            clean(
              clip?.scene_id
            ),

          reason:
            trimResult
