  );

// ======================================================
// FINAL PATH VALIDATION
// ======================================================

const missingFinalFiles =
  rebuiltClips
    .filter(
      clip =>
        !clip.final_file_ready ||
        !clean(
          clip.final_clip_path
        )
    )
    .map(
      clip => ({

        clip_uid:
          clean(
            clip.clip_uid
          ),

        global_order:
          num(
            clip.global_order
          ),

        scene_id:
          clean(
            clip.scene_id
          ),

        source_id:
          clean(
            clip.source_id
          ),

        temporal_trim_status:
          clean(
            clip.temporal_trim_status
          )
      })
    );

