  rebuiltClips.length > 0 &&
  missingFinalFiles.length === 0;

// ======================================================
// FOOTAGE
//
// Only clips that are genuinely ready count.
// ======================================================

const readyClips =
  rebuiltClips.filter(
    clip =>
      clip.final_file_ready === true &&
      clean(
        clip.final_clip_path
      ) &&
      num(
        clip.actual_duration ??
        clip.duration,
        0
      ) > 0
  );

const finalFootageSeconds =
  readyClips.reduce(
    (sum, clip) =>
      sum +
      num(
        clip.actual_duration ??
        clip.duration,
        0
      ),
    0
  );

const minimumRealFootageSeconds = desiredFootageSeconds * 0.85;
const enoughFootage = desiredFootageSeconds <= 0 || finalFootageSeconds >= minimumRealFootageSeconds;

const footageShortfallSeconds =
  Math.max(
    0,
    desiredFootageSeconds -
    finalFootageSeconds
  );

const footageCoverageRatio =
  desiredFootageSeconds > 0
    ? finalFootageSeconds /
      desiredFootageSeconds
    : 1;

// ======================================================
// SOURCE STATE
// ======================================================

const enoughSources =
  typeof input.enough_sources ===
    'boolean'
    ? input.enough_sources
    : (
        actualSourceCount >=
        desiredSourceCount
      );

const sourcesExhausted =
  input.sources_exhausted ===
    true;

const incomingCollectionStatus =
  clean(
    input.collection_status
  );

const upstreamPartialCollection =
  (
    input.partial_collection_available ===
      true ||
    incomingCollectionStatus.startsWith(
      'ready_with_'
    )
  );

// ======================================================
// FINAL COLLECTION STATE
// ======================================================

const completeCollectionReady =
  (
    allFinalFilesReady &&
    readyClips.length > 0 &&
    enoughSources &&
