  (
    allFinalFilesReady &&
    readyClips.length > 0 &&
    sourcesExhausted &&
    !enoughSources &&
    enoughFootage
  );

const footageShortfallReady =
  (
    allFinalFilesReady &&
    readyClips.length > 0 &&
    sourcesExhausted &&
    !enoughFootage
  );

const partialCollectionReady =
  (
    !completeCollectionReady &&
    (
      sourceShortfallReady ||
      footageShortfallReady ||
      (
        allFinalFilesReady &&
        readyClips.length > 0 &&
        upstreamPartialCollection
      )
    )
  );

const rebuildReady =
  completeCollectionReady ||
  partialCollectionReady;

const requiresVisualSupplement =
  (
    rebuildReady &&
