// ======================================================

let finalClipRebuildStatus =
  'not_ready';

if (
  failedTrimClipCount > 0
) {

  finalClipRebuildStatus =
    'trim_failure';

} else if (
  completeCollectionReady
) {

  finalClipRebuildStatus =
    'ready';

} else if (
  partialCollectionReady &&
  enoughFootage &&
  !enoughSources
) {

  finalClipRebuildStatus =
    'ready_with_source_shortfall';

} else if (
  partialCollectionReady &&
  !enoughFootage
) {

  finalClipRebuildStatus =
    'ready_with_footage_shortfall';

} else if (
  partialCollectionReady
) {

  finalClipRebuildStatus =
    'ready_with_shortfall';
}

// ======================================================
// ASSEMBLY CLIPS
//
// Only valid final files are exposed for assembly.
// ======================================================

const assemblyClips =
  readyClips.map(
    (clip, index) => ({

      timeline_order:
        index,

      global_order:
        clip.global_order,

      clip_uid:
        clean(
          clip.clip_uid
        ),

      source_id:
        clean(
          clip.source_id
        ),

      source_title:
        clean(
          clip.source_title
        ),

      source_url:
        clean(
          clip.source_url
        ),

      source_channel:
        clean(
          clip.source_channel
        ),

      source_class:
        clean(
          clip.source_class
        ),

      scene_id:
        clean(
          clip.scene_id
        ),

      path:
        clean(
          clip.final_clip_path
        ),

      duration:
        round3(
          clip.actual_duration ??
          clip.duration
        ),

