    assemblyClips,

  total_clip_count:
    readyClips.length,

  rebuilt_input_clip_count:
    rebuiltClips.length,

  trimmed_clip_count:
    trimmedClipCount,

  untouched_clip_count:
    untouchedClipCount,

  failed_trim_clip_count:
    failedTrimClipCount,

  failed_trim_clips:
    failedTrimClips,

  expected_trimmed_clip_count:
    num(
      input.successful_trim_count,
      0
    ),

  final_footage_seconds:
    round3(
      finalFootageSeconds
    ),

  total_footage_seconds:
    round3(
      finalFootageSeconds
    ),

  desired_footage_seconds:
    round3(
      desiredFootageSeconds
    ),

  footage_shortfall_seconds:
    round3(
      footageShortfallSeconds
    ),

  real_footage_target_shortfall_seconds:
    round3(
      footageShortfallSeconds
    ),

  footage_coverage_ratio:
    round3(
      footageCoverageRatio
    ),

  desired_source_count:
    desiredSourceCount,

  actual_source_count:
    actualSourceCount,

  enough_footage:
    enoughFootage,

  enough_sources:
    enoughSources,

  sources_exhausted:
    sourcesExhausted,

  partial_collection_ready:
    partialCollectionReady,

  complete_collection_ready:
    completeCollectionReady,

  requires_visual_supplement:
    requiresVisualSupplement,

  missing_final_files:
    missingFinalFiles,

  missing_final_file_count:
    missingFinalFiles.length,

  all_final_clip_paths_ready:
    allFinalFilesReady,

  ready_for_final_clip_selection:
    rebuildReady,

  final_clip_rebuild_status:
    finalClipRebuildStatus,

  final_clip_rebuild_version:
    '1.2-fail-safe-per-clip-trim-aware'
};

// ======================================================
// DO NOT THROW â€” RETURN STRUCTURED FAILURE
// ======================================================

if (
  unrecoverableRebuildFailure
) {

  output.status =
    'failed';

  output.workflow_outcome =
    'fallback_required';

  output.asset_ready =
    false;

  output.ready_for_assembly =
    false;

  output.ready_for_content_pipeline =
    false;

  output.requires_fallback =
    true;

  output.requires_visual_supplement =
    false;

  output.result_type =
    'no_asset';

  output.error =
    failedTrimClipCount > 0
      ? (
          `${failedTrimClipCount} editorial clip(s) required temporal trimming but did not produce a valid trimmed file.`
        )
      : 'No valid final editorial clips were available after rebuild.';

  output.fallback_reason =
    output.error;

  output.recommended_next_action =
    'fallback_after_editorial_rebuild_failure';
