return [
  {
    json:
      output
  }
];

const input =
  $input.first()?.json || {};

// ======================================================
// PLAN FINAL EDITORIAL TIMELINE
// VERSION: 1.2-fail-safe-validated-clips
// ======================================================

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function num(value, fallback = 0) {

  const n =
    Number(value);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function round3(value) {

  return Number(
    num(value)
      .toFixed(3)
  );
}

function failedOutput(
  reason
) {

  const requestedAssetType =
    clean(
      input.requested_asset_type ||
      input.asset_type ||
      'video'
    )
      .toLowerCase() === 'image'
      ? 'image'
      : 'video';

  return [
    {
      json: {

        ...input,

        requested_asset_type:
          requestedAssetType,

        asset_type:
          requestedAssetType,

        status:
          'failed',

        result_type:
          'no_asset',

        workflow_outcome:
          'fallback_required',

        asset_ready:
          false,

        ready_for_assembly:
          false,

        ready_for_content_pipeline:
          false,

        requires_fallback:
          true,

        editorial_timeline:
          [],

        assembly_clips:
          [],

        editorial_timeline_clip_count:
          0,

        editorial_timeline_duration_seconds:
          0,

        missing_timeline_path_count:
          0,

        timeline_all_paths_ready:
          false,

        timeline_coverage_status:
          'not_ready',

        final_timeline_status:
          'not_ready',

        ready_for_asset_finalize:
          false,

        error:
          clean(
            reason
          ),

        fallback_reason:
          clean(
            reason
          ),

        recommended_next_action:
          'fallback_after_timeline_failure',

        final_timeline_version:
          '1.2-fail-safe-validated-clips'
      }
    }
  ];
