// ======================================================
// INPUT
//
// Prefer validated clips from Rebuild.
// ======================================================

const clips =
  (
    Array.isArray(
      input.assembly_clips
    ) &&
    input.assembly_clips.length > 0
  )
    ? input.assembly_clips
    : (
        Array.isArray(
          input.final_editorial_clips
        )
          ? input.final_editorial_clips
          : (
              Array.isArray(
                input.clips
              )
                ? input.clips
                : []
            )
      );

// ======================================================
// REBUILD STATE
// ======================================================

const rebuildStatus =
  clean(
    input.final_clip_rebuild_status
  )
    .toLowerCase();

const acceptedRebuildStatuses =
  new Set([
