  const clip =
    clips[index] || {};

  const clipPath =
    clean(
      clip.final_clip_path ||
      clip.final_path ||
      clip.path
    );

  const duration =
    num(
      clip.actual_duration ??
      clip.duration,
      0
    );

  const sourceKey =
    clean(
      clip.source_id ||
      clip.source_url
    );

  if (
    !clipPath ||
    duration <= 0 ||
    !sourceKey
  ) {

    invalidClips.push({

      index,

      clip_uid:
        clean(
          clip.clip_uid
        ),

      source_id:
        clean(
          clip.source_id
        ),

      source_url:
        clean(
          clip.source_url
        ),

      path:
        clipPath,

      duration:
        round3(
          duration
        )
    });

    continue;
  }

  validClips.push({
    ...clip,

    path:
      clipPath,

    duration:
      round3(
        duration
      )
  });
}

if (
  validClips.length === 0
) {

  return failedOutput(
    'No valid editorial clips remained for timeline planning.'
  );
}

if (
  invalidClips.length > 0
) {

  return failedOutput(
    `${invalidClips.length} invalid editorial clip(s) reached timeline planning.`
  );
}

// ======================================================
// GROUP BY SOURCE
// ======================================================

const sourceGroups =
  new Map();

for (const clip of validClips) {

  const sourceKey =
    clean(
      clip.source_id ||
      clip.source_url
    );

  if (
    !sourceGroups.has(
      sourceKey
    )
  ) {

    sourceGroups.set(
      sourceKey,
      []
    );
  }

  sourceGroups
    .get(
      sourceKey
    )
    .push({
      ...clip
    });
}

// ======================================================
// SORT WITHIN SOURCE
// ======================================================

for (
  const group
  of sourceGroups.values()
) {

  group.sort(
    (a, b) => {

      const aTime =
        num(
          a.adjusted_start_time ??
          a.start_time,
          0
        );

      const bTime =
        num(
          b.adjusted_start_time ??
          b.start_time,
          0
        );

      if (
        aTime !== bTime
      ) {
        return (
          aTime -
          bTime
        );
      }

      return (
        num(
          a.global_order,
          0
        ) -
        num(
          b.global_order,
          0
        )
      );
    }
  );
}

// ======================================================
// SOURCE PRIORITY
// ======================================================

const sourceInfos =
  [...sourceGroups.entries()]
    .map(
      ([sourceId, group]) => {

        const first =
          group[0] || {};

        const sourceClass =
          clean(
            first.source_class
          );

        let priority = 50;

        if (
          sourceClass ===
          'official_first_party'
        ) {

          priority =
            100;

        } else if (
          sourceClass ===
          'official_publisher'
        ) {

          priority =
            95;

        } else if (
          sourceClass ===
          'official_platform'
        ) {

          priority =
            90;

        } else if (
          sourceClass ===
          'established_editorial_media'
        ) {

          priority =
            80;
        }

        return {

          source_id:
            sourceId,

          source_title:
            clean(
              first.source_title
            ),

          source_url:
            clean(
              first.source_url
            ),

          source_channel:
            clean(
              first.source_channel
            ),

          source_class:
            sourceClass,

          source_index:
            num(
              first.source_index,
              0
            ),

          priority,

          clips:
            group
        };
      }
    )
    .sort(
      (a, b) => {

        if (
          b.priority !==
          a.priority
        ) {

          return (
            b.priority -
            a.priority
          );
        }

        return (
          a.source_index -
          b.source_index
        );
      }
    );

// ======================================================
// ROUND ROBIN
// ======================================================

const workingGroups =
  sourceInfos.map(
    source => ({

      ...source,

      cursor:
        0
    })
  );

const timelineClips =
  [];

let remainingClips =
  validClips.length;

while (
  remainingClips > 0
) {

  let addedThisRound =
    0;

  for (
    const source
    of workingGroups
  ) {

    if (
      source.cursor >=
      source.clips.length
    ) {
      continue;
    }

    const clip =
      source.clips[
        source.cursor
      ];

    source.cursor++;

    timelineClips.push({
      ...clip
    });

    addedThisRound++;

    remainingClips--;
  }

  if (
    addedThisRound === 0
  ) {

    break;
  }
}

if (
  timelineClips.length !==
  validClips.length
) {

  return failedOutput(
    'Timeline interleave did not consume every validated editorial clip.'
  );
}

// ======================================================
// TIMELINE POSITIONS
// ======================================================

let cursorSeconds =
  0;

const finalTimeline =
  timelineClips.map(
    (clip, index) => {

      const duration =
        num(
          clip.duration,
          0
        );

      const timelineStart =
        cursorSeconds;

      const timelineEnd =
        timelineStart +
        duration;

      cursorSeconds =
        timelineEnd;

      return {

        timeline_order:
          index + 1,

        timeline_start_sec:
          round3(
            timelineStart
          ),

        timeline_end_sec:
          round3(
            timelineEnd
          ),

        duration:
          round3(
            duration
          ),

        clip_uid:
          clean(
            clip.clip_uid
          ),

        source_index:
          num(
            clip.source_index,
            0
          ),

        source_id:
          clean(
            clip.source_id
          ),

        source_title:
          clean(
            clip.source_title
          ),

        source_url:
          clean(
            clip.source_url
          ),

        source_channel:
          clean(
            clip.source_channel
          ),

        source_class:
          clean(
            clip.source_class
          ),

        scene_id:
          clean(
            clip.scene_id
          ),

        path:
          clean(
            clip.path
          ),

        temporal_trim_applied:
          clip.temporal_trim_applied ===
            true,

        muted:
          clip.muted !== false
      };
    }
  );

// ======================================================
// COVERAGE
// ======================================================

const missingPaths =
  finalTimeline.filter(
    clip =>
      !clean(
        clip.path
      )
  );

const timelineDurationSeconds =
  finalTimeline.reduce(
    (sum, clip) =>
      sum +
      num(
        clip.duration,
        0
      ),
    0
  );

const targetVideoDuration =
  num(
    input.target_video_duration_sec,
    120
  );

const desiredFootageSeconds =
  num(
    input.desired_footage_seconds,
    0
  );

const remainingVideoSeconds =
  Math.max(
    0,
    targetVideoDuration -
    timelineDurationSeconds
  );

const editorialCoverageRatio =
  targetVideoDuration > 0
    ? (
        timelineDurationSeconds /
        targetVideoDuration
      )
    : 0;

const footageAboveTargetSeconds =
  Math.max(
    0,
    timelineDurationSeconds -
    desiredFootageSeconds
  );

const realFootageTargetShortfallSeconds =
  Math.max(
    0,
    desiredFootageSeconds -
    timelineDurationSeconds
  );

const minimumRealFootageSeconds = targetVideoDuration * 0.85;
const enoughFootage = desiredFootageSeconds <= 0 || timelineDurationSeconds >= minimumRealFootageSeconds;

const partialCollectionReady =
  input.partial_collection_ready ===
    true;

const requiresVisualSupplement =
  (
    input.requires_visual_supplement ===
      true ||
    (
      partialCollectionReady &&
      !enoughFootage &&
      realFootageTargetShortfallSeconds >
        0
    )
  );

