// SOURCE DISTRIBUTION
// ======================================================

const sourceDistribution =
  sourceInfos.map(
    source => {

      const sourceTimelineClips =
        finalTimeline.filter(
          clip =>
            clip.source_id ===
            source.source_id
        );

      const seconds =
        sourceTimelineClips.reduce(
          (sum, clip) =>
            sum +
            num(
              clip.duration,
              0
            ),
          0
        );

      return {

        source_id:
          source.source_id,

        source_title:
          source.source_title,

        source_url:
          source.source_url,

        source_channel:
          source.source_channel,

        source_class:
          source.source_class,

        clip_count:
          sourceTimelineClips.length,

        footage_seconds:
          round3(
            seconds
          )
      };
    }
  );

// ======================================================
// FINAL STATE
// ======================================================

const timelineReady =
  (
    finalTimeline.length > 0 &&
    missingPaths.length === 0
  );

let timelineCoverageStatus =
  'not_ready';

if (
  timelineReady &&
  enoughFootage
) {

  timelineCoverageStatus =
    'real_footage_target_met';

} else if (
  timelineReady &&
  partialCollectionReady
) {

  timelineCoverageStatus =
    'partial_after_search_exhausted';

} else if (
  timelineReady
) {

  timelineCoverageStatus =
    'real_footage_shortfall';
}

// ======================================================
// OUTPUT
// ======================================================

return [
  {
    json: {

      ...input,

      editorial_timeline:
        finalTimeline,

      final_timeline:
        finalTimeline,

      assembly_clips:
        finalTimeline,

      editorial_timeline_clip_count:
        finalTimeline.length,

      editorial_timeline_duration_seconds:
        round3(
