// ======================================================
// BUILD POLICY UNAVAILABLE RESULT
// VERSION: 1.0-graceful-policy-fallback
// Mode: Run Once for All Items
// ======================================================

const inputItems = $input.all();

const items =
  inputItems.length > 0
    ? inputItems
    : [{ json: {} }];

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function extractErrorMessage(json) {

  if (!json || typeof json !== 'object') {
    return '';
  }

  const candidates = [
    json.policy_unavailable_reason,

    json.error?.message,
    json.error?.description,
    json.error?.details,

    typeof json.error === 'string'
      ? json.error
      : '',

    json.message,
    json.description
  ];

  for (const value of candidates) {

    const text =
      clean(value);

    if (text) {
      return text;
    }
  }

  return '';
}

// ======================================================
// OUTPUT
// ======================================================

return items.map(item => {

  const json =
    item.json || {};

  const detectedError =
    extractErrorMessage(
      json
    );

  const reason =
    detectedError ||
    (
      clean(json.policy_url)
        ? 'The selected usage-policy page could not be retrieved automatically.'
        : 'No sufficiently reliable official usage-policy page was found.'
    );

  const candidateAssetType =
    clean(
      json.candidate_asset_type ||
      json.asset_type ||
      'unknown'
    );

  return {
    json: {

      // Preserve whatever state arrived.
      ...json,

      // ==================================================
      // POLICY AVAILABILITY
      // ==================================================

      policy_evidence_available:
        false,

      policy_check_failed:
        true,

      policy_unavailable_reason:
        reason,

      policy_source_url:
        clean(
          json.policy_url
