        'unclear',

      candidate_asset_type:
        candidateAssetType,

      candidate_reuse_status:
        'unclear',

      safe_for_auto_use:
        false,

      requires_human_review:
        true,

      key_permissions:
        [],

      key_restrictions:
        [
          'Automated policy verification was unavailable.'
        ],

      candidate_reasoning:
        reason,

      policy_summary:
        reason,

      policy_fallback_version:
        '1.0-graceful-policy-fallback'
    }
  };
});

// ======================================================
// NORMALIZE POLICY DECISION
// VERSION: 1.0-analyze-to-rights-gate
// Mode: Run Once for All Items
// ======================================================

const items = $input.all();

// ======================================================
// HELPERS
// ======================================================

function clean(value) {
  return String(value ?? '').trim();
}

function bool(value, fallback = false) {

  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }

  if (value === 'true') {
    return true;
  }

  if (value === 'false') {
    return false;
  }

  return fallback;
}

// ======================================================
// NORMALIZE EVERY POLICY RESULT
// ======================================================

return items.map(item => {

  const json =
    item.json || {};

  const evidenceAvailable =
    json.policy_evidence_available !==
      false &&
    json.policy_check_failed !==
      true;

  const policyAppliesToGame =
    bool(
      json.policy_applies_to_game,
      true
    );

  const policyConfidence =
    clean(
      json.policy_confidence
    ).toLowerCase();

  const candidateReuseStatus =
    clean(
      json.candidate_reuse_status
    ).toLowerCase();

  const safeForAutoUse =
    bool(
      json.safe_for_auto_use,
      false
    );

  const requiresHumanReview =
    bool(
      json.requires_human_review,
      false
    );

  const transformativeUseRequired =
    clean(
      json.transformative_use_required
    ).toLowerCase();

  // ====================================================
  // DECISION
  // ====================================================

  let policyDecision =
    'manual_review';

  let policyAllowsUse =
    false;

  let policyAllowsEditorial =
    false;

  let policyRequiresReview =
    true;

  let policyBlocksUse =
    false;

  // ----------------------------------------------------
  // NO VERIFIED POLICY
  // ----------------------------------------------------

  if (!evidenceAvailable) {

    policyDecision =
      'manual_review';

    policyRequiresReview =
      true;
  }

  // ----------------------------------------------------
  // POLICY DOES NOT CLEARLY APPLY
  // ----------------------------------------------------

  else if (!policyAppliesToGame) {

    policyDecision =
      'manual_review';

    policyRequiresReview =
      true;
  }

  // ----------------------------------------------------
  // EXPLICIT BLOCK
  // ----------------------------------------------------

  else if (
    candidateReuseStatus ===
      'not_allowed'
  ) {

    policyDecision =
      'block';

    policyBlocksUse =
      true;

    policyRequiresReview =
      false;
  }

  // ----------------------------------------------------
  // LOW CONFIDENCE / UNCLEAR
  // ----------------------------------------------------

  else if (
    requiresHumanReview === true ||
    policyConfidence === 'low' ||
    !candidateReuseStatus ||
    candidateReuseStatus === 'unclear'
  ) {

    policyDecision =
      'manual_review';

    policyRequiresReview =
      true;
  }

  // ----------------------------------------------------
  // EXPLICIT SAFE AUTO USE
  // ----------------------------------------------------

  else if (
    candidateReuseStatus ===
      'allowed' &&
    safeForAutoUse === true
  ) {

    policyDecision =
      'auto_use';

    policyAllowsUse =
      true;

    policyAllowsEditorial =
      true;

    policyRequiresReview =
      false;
  }

  // ----------------------------------------------------
  // ALLOWED, BUT NOT SAFE FOR UNRESTRICTED AUTO USE
  // ----------------------------------------------------

  else if (
    candidateReuseStatus ===
      'allowed'
  ) {

    policyDecision =
      'editorial_use';

    policyAllowsEditorial =
      true;

    policyRequiresReview =
      false;
  }

  // ----------------------------------------------------
  // CONDITIONAL + TRANSFORMATIVE USE
  // ----------------------------------------------------

  else if (
    candidateReuseStatus ===
      'conditional' &&
    transformativeUseRequired ===
      'yes'
  ) {

    policyDecision =
      'editorial_use';

    policyAllowsEditorial =
      true;

    policyRequiresReview =
      false;
  }

  // ----------------------------------------------------
  // CONDITIONAL BUT CONDITIONS NOT CLEAR ENOUGH
  // ----------------------------------------------------

  else {

    policyDecision =
      'manual_review';

    policyRequiresReview =
      true;
  }

  // ====================================================
  // REASON
  // ====================================================

  const policyReason =
    clean(
      json.policy_unavailable_reason ||
      json.candidate_reasoning ||
      json.policy_summary
    ) ||
    (
      policyDecision === 'auto_use'
        ? 'The verified policy supports automated use of the candidate.'
        : policyDecision === 'editorial_use'
          ? 'The verified policy supports limited editorial or transformative use.'
          : policyDecision === 'block'
            ? 'The verified policy does not permit use of the candidate.'
            : 'The available policy evidence is not sufficient for automatic use.'
    );

  // ====================================================
  // OUTPUT
  // ====================================================

  return {
    json: {

      ...json,

      // ==================================================
      // FIELDS EXPECTED BY FINALIZE RIGHTS GATE
      // ==================================================

      policy_decision:
        policyDecision,

      usage_decision:
        policyDecision,

      policy_rights_decision:
        policyDecision,

      final_policy_decision:
        policyDecision,

      policy_allows_use:
        policyAllowsUse,

      usage_allowed:
        policyAllowsUse,

      commercial_use_allowed:
        policyAllowsUse,

      editorial_use_permitted:
        policyAllowsEditorial,

      editorial_use_allowed_by_policy:
        policyAllowsEditorial,

      transformative_use_allowed:
        policyAllowsEditorial,

      manual_review_required:
        policyRequiresReview,

      policy_requires_human_review:
        policyRequiresReview,

      policy_blocks_use:
        policyBlocksUse,

      usage_prohibited:
        policyBlocksUse,

      policy_reason:
        policyReason,

      policy_analysis_reason:
        policyReason,

      normalized_policy_result:
        true,

      policy_normalizer_version:
        '1.0-analyze-to-rights-gate'
    }
  };
});

