const fs = require('fs');
const { spawnSync } = require('child_process');

const planPath = process.argv[2];
let plan = [];
try {
  plan = JSON.parse(fs.readFileSync(planPath, 'utf8'));
} catch {
  plan = [];
}

// dHash: resize to 9x8 grayscale, compare each pixel to its right neighbor -> 64-bit hash.
// Developed and unit-tested standalone (phase1-lib.cjs) and validated against real cached
// production clips before being transplanted here.
function dHashFromGrayBuffer(buf, width, height) {
  if (!buf || buf.length !== width * height) return null;
  let bits = '';
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width - 1; x++) {
      bits += buf[y * width + x] < buf[y * width + x + 1] ? '1' : '0';
    }
  }
  return bits;
}

const results = [];

for (const item of plan) {

  if (!item.path || !fs.existsSync(item.path)) {
    results.push({ clip_uid: item.clip_uid, hash: null, error: 'file_missing' });
    continue;
  }

  const dur = Math.max(0.1, Number(item.duration) || 1);
  const at = Math.max(0.05, dur * 0.5);

  // IMPORTANT: do not pass -v error here -- verified live that it silently suppresses the
  // rawvideo pipe output path used elsewhere in this pipeline's showinfo-based cut detection;
  // -v error is fine for a plain frame grab (no showinfo involved) but kept consistent/minimal.
  const ff = spawnSync('ffmpeg', [
    '-v', 'error', '-ss', String(at), '-i', item.path,
