const rebuilt = $('Rebuild Final Editorial Clips').item.json;
const hashOut = $json.stdout || '';

const lines = hashOut.split(/\r?\n/);
const jsonLine = lines.find(l => l.startsWith('PERCEPTUAL_HASH_RESULT_JSON='));

let hashResults = [];
try {
  hashResults = jsonLine ? JSON.parse(jsonLine.slice('PERCEPTUAL_HASH_RESULT_JSON='.length)) : [];
} catch {
  hashResults = [];
}

const hashByUid = new Map(hashResults.filter(h => h.hash).map(h => [h.clip_uid, h.hash]));

const clips = Array.isArray(rebuilt.assembly_clips) ? rebuilt.assembly_clips : [];
const withHash = [];
const withoutHash = [];

for (const clip of clips) {
  const hash = hashByUid.get(clip.clip_uid);
  if (hash) withHash.push({ ...clip, perceptual_hash: hash });
  else withoutHash.push(clip);
}

// Threshold empirically tuned against 276 real pairwise comparisons from an actual production run
// (24 already-temporally-deduped Resonance clips): 0 false positives at <=6, first false positive
// (visually confirmed: two compositionally-similar but scene-distinct dark corridor shots) appears
// at distance 8. Kept conservative -- wrongly discarding a good, distinct shot is worse than
// occasionally missing a true duplicate.
const THRESHOLD = 6;

function hammingDistance(a, b) {
  let d = 0;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) d++;
  return d;
}

const n = withHash.length;
const parent = withHash.map((_, i) => i);
function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
function union(a, b) { const ra = find(a), rb = find(b); if (ra !== rb) parent[ra] = rb; }

for (let i = 0; i < n; i++) {
  for (let j = i + 1; j < n; j++) {
    if (hammingDistance(withHash[i].perceptual_hash, withHash[j].perceptual_hash) <= THRESHOLD) union(i, j);
  }
}

const groups = new Map();
for (let i = 0; i < n; i++) {
  const r = find(i);
  if (!groups.has(r)) groups.set(r, []);
  groups.get(r).push(withHash[i]);
}

const kept = [];
const dropped = [];

for (const group of groups.values()) {
  if (group.length === 1) { kept.push(group[0]); continue; }
  // Keep the longer validated clip -- the strongest local quality signal available at this stage
  // (semantic/opening-score annotations are not joined onto clips until the very end of this
  // workflow, in "Return Find Game Assets Result").
  group.sort((a, b) => (Number(b.actual_duration) || 0) - (Number(a.actual_duration) || 0));
  kept.push(group[0]);
  for (let i = 1; i < group.length; i++) {
    dropped.push({
      clip_uid: group[i].clip_uid,
      duplicate_of: group[0].clip_uid,
      hamming_distance_to_kept: hammingDistance(group[i].perceptual_hash, group[0].perceptual_hash),
      reason: 'visual_near_duplicate_cross_source_or_cross_timestamp',
    });
  }
}

// FLAG-ONLY MODE (see comment above): live-tested against two real production samples, dHash
// at this threshold produced 0 confirmed true positives and 2 confirmed false positives (visually
// verified both times). Do not auto-discard on this signal alone yet -- report candidates for
// visibility only. assembly_clips is intentionally left unmodified (all clips preserved).
const finalClips = clips;

return [{
  json: {
    ...rebuilt,
    assembly_clips: finalClips,
    visual_near_duplicate_flagged: dropped,
    visual_near_duplicate_flagged_count: dropped.length,
    visual_near_duplicate_auto_discard_enabled: false,
    visual_near_duplicate_hash_error_count: withoutHash.length,
    visual_dedup_threshold: THRESHOLD,
    visual_dedup_version: '1.1-dhash-flag-only-pending-semantic-validation',
  }
}];
